window.__CHRONICLE_CHUNK["wd-02"] = [
  { id: "world--b478--p01", track: "world", year: -478, yearApprox: false, dim: "politics", weight: 4, title: "提洛同盟成立", summary: "二十余邦在德洛斯结盟，贡金四百六十塔兰同交雅典统管。", detail: { background: "萨拉米斯后波斯海军仍驻爱奥尼亚，希腊邦需长期护航；斯巴达的统帅被召回，领导权落于雅典。", process: "前478年冬诸邦在德洛斯宣誓结盟，阿里斯泰德额定初年贡四百六十塔兰同，盟邦纳船或纳银，金库与会议设于岛神庙。", impact: "雅典取得爱琴海制海权，贡金渐成其岁入；纳克索斯、萨索斯先后被强制留盟，攻守同盟转为财政帝国。", figures: ["阿里斯泰德", "客蒙"], place: "德洛斯岛", state: "雅典与提洛同盟", sources: ["修昔底德《伯罗奔尼撒战争史》第一卷", "《雅典贡金名录》铭刻辑录", "《剑桥古代史》第四卷"], tags: ["同盟", "贡金", "爱琴海"] }, related: [] },
  { id: "world--b472--a01", track: "world", year: -472, yearApprox: false, dim: "art", weight: 3, title: "埃斯库罗斯《波斯人》首演", summary: "以波斯宫廷视角写萨拉米斯之败，为现存最早悲剧。", detail: { background: "雅典酒神节竞赛由城邦出资排演，埃斯库罗斯曾参战马拉松与萨拉米斯，把亲历战事搬上舞台。", process: "前472年由伯里克利斯任合唱资助役出资，写薛西斯得败讯、宫廷哀悼与亡魂显灵，歌队颂唱萨拉米斯海战。", impact: "全剧仅存且为现存最古悲剧，确立三联剧之外的历史题材写法，为后世以敌营视角观战提供范本。", figures: ["埃斯库罗斯", "伯里克利斯"], place: "雅典狄奥尼索斯剧场", state: "雅典城邦", sources: ["埃斯库罗斯《波斯人》剧本及题解", "《剑桥古代史》第四卷"], tags: ["悲剧", "酒神节", "萨拉米斯"] }, related: [] },
  { id: "world--b462--p01", track: "world", year: -462, yearApprox: false, dim: "politics", weight: 4, title: "厄菲阿尔特斯剥夺长老会", summary: "把阿雷奥帕古斯的政裁权分给议事会与公民法庭。", detail: { background: "阿雷奥帕古斯由卸任执政官终身任席，握有监察法律与道德之权，成为贵族政治的最后堡垒。", process: "前462年前后，厄菲阿尔特斯以公民大会表决削去其政裁职能，权分归五百人议事会、公民大会与陪审法庭。", impact: "雅典民主的最后一块制度障碍被清除，四十余年后他遭贵族刺杀；伯里克利斯时代由此开启。", figures: ["厄菲阿尔特斯", "伯里克利斯"], place: "雅典亚勒乌帕戈斯山丘", state: "雅典城邦", sources: ["亚里士多德《雅典政制》第二十五至二十七章", "修昔底德《伯罗奔尼撒战争史》第一卷"], tags: ["民主改革", "陪审法庭", "贵族"] }, related: [] },
  { id: "world--b458--c01", track: "world", year: -458, yearApprox: false, dim: "culture", weight: 3, title: "《奥瑞斯忒亚》三联剧上演", summary: "唯一完整传世的三部曲，以血仇到法庭收束。", detail: { background: "酒神节竞赛要求诗人一日演毕三联剧，埃斯库罗斯晚年以阿特柔斯家族的世仇为题材。", process: "前458年《阿伽门农》《献酒者》《复仇神》连演，写弑夫、复仇与被释罪，末剧由雅典娜设阿雷奥帕古斯法庭投票定罪。", impact: "把部族血亲复仇转化为城邦司法程序，是现存唯一完整三部曲，亦为法庭与投票合法性的文学奠基。", figures: ["埃斯库罗斯"], place: "雅典狄奥尼索斯剧场", state: "雅典城邦", sources: ["埃斯库罗斯《奥瑞斯忒亚》三剧原文", "《剑桥古代史》第四卷"], tags: ["悲剧", "法庭", "血仇"] }, related: [] },
  { id: "world--b454--p01", track: "world", year: -454, yearApprox: true, dim: "politics", weight: 3, title: "同盟金库迁往雅典", summary: "德洛斯金库与贡籍归雅典掌管，盟费渐成邦库岁入。", detail: { background: "雅典远征埃及失利，需就近控制财源；同盟会议每年在雅典召开已成惯例。", process: "约前454至前453年，金库自德洛斯移至雅典，贡金改存雅典娜神庙，逐年名册改于卫城铭刻。", impact: "盟邦财产由一邦代管，雅典得以免税并资助神庙营建；亚里士多德后来指此为同盟变为帝国之始。", figures: ["伯里克利斯", "修昔底德（反对派领袖）"], place: "雅典卫城", state: "雅典与提洛同盟", sources: ["亚里士多德《雅典政制》第二十七章", "《雅典贡金名录》铭刻辑录"], tags: ["贡金", "帝国化", "财政"] }, related: [] },
  { id: "world--b451--i01", track: "world", year: -451, yearApprox: false, dim: "institution", weight: 5, title: "十二铜表法颁行", summary: "十人委员会刻十二表法律于广场，罗马成文法自此始。", detail: { background: "平民长期不满贵族法官专断解释习惯法，特伦提留斯等提议设委员会编纂并公布法律。", process: "前451年选十人委员会，遣使赴雅典考察梭伦立法；前451年拟十表，前450年续二表，条文刻于十二块铜（或木）表立于广场。", impact: "量刑与诉讼程式公开可查，贵族解释空间被压缩；此表成为罗马市民法之根源，李维称之为一切公私法之源。", figures: ["阿庇乌斯·克劳狄乌斯", "斯巴留斯·特伦提留斯"], place: "罗马广场", state: "罗马共和国", sources: ["李维《自建城以来》第三卷", "十二表法残条辑校本"], tags: ["成文法", "平民", "罗马"] }, related: [] },
  { id: "world--b449--i01", track: "world", year: -449, yearApprox: false, dim: "institution", weight: 3, title: "保民官不可侵法", summary: "十人政治被推翻后，保民官人身神圣与申诉权成文。", detail: { background: "第二次十人委员会期满拒不解职，以阿庇乌斯案激起平民第二次撤离圣山。", process: "前449年通过瓦尔利亚-霍拉提亚法，确认保民官人身不可侵犯、可行救助与申诉，侵害者依法可被处死并没收财产。", impact: "平民有了常设的否决与申诉机关，此后两百年间成为制约元老院与执政官的制度杠杆。", figures: ["卢基乌斯·维吉尼乌斯", "斯巴留斯·霍拉提乌斯"], place: "罗马", state: "罗马共和国", sources: ["李维《自建城以来》第三卷", "阿庇安《罗马史·王政与早期共和》残篇"], tags: ["保民官", "否决权", "成文法"] }, related: [] },
  { id: "world--b447--a01", track: "world", year: -447, yearApprox: false, dim: "art", weight: 4, title: "帕特农神庙动工", summary: "以同盟贡金建多立克式大理石大殿，工期十六年。", detail: { background: "波斯毁卫城旧庙，雅典以同盟金库偿神恩并宣示霸权；伯里克利斯主持营建计划。", process: "前447年奠基，伊克提诺斯与卡利克拉特斯设计，菲狄亚斯总监理；彭特利库斯大理石，八列十七柱环列，视觉矫正使柱身微凸、角柱内倾。", impact: "多立克式与爱奥尼亚饰带的合璧成为古典建筑的尺度基准，后世新古典主义公共建筑反复摹其比例。", figures: ["菲狄亚斯", "伊克提诺斯", "卡利克拉特斯", "伯里克利斯"], place: "雅典卫城", state: "雅典城邦", sources: ["普鲁塔克《伯里克利斯传》十三至十五节", "帕特农工程铭文辑录"], tags: ["神庙", "比例", "多立克"] }, related: [] },
  { id: "world--b445--i01", track: "world", year: -445, yearApprox: false, dim: "institution", weight: 3, title: "卡努莱亚法废通婚禁令", summary: "平民与贵族合法通婚，官职壁垒随后松动。", detail: { background: "十二表法禁止两等级通婚，平民子弟在财产与仕途上被隔绝于贵族网络之外。", process: "前445年护民官卡努莱乌斯提出法案，取消通婚禁令；同年允许设五人军事护民官以替代执政官职。", impact: "两等级在血缘与继承上打通，为日后平民任执政官、祭司与开放官职体系铺路。", figures: ["盖乌斯·卡努莱乌斯"], place: "罗马", state: "罗马共和国", sources: ["李维《自建城以来》第四卷"], tags: ["通婚", "官职", "平民"] }, related: [] },
  { id: "world--b444--s01", track: "world", year: -444, yearApprox: true, dim: "science", weight: 3, title: "希波达穆斯的方格规划", summary: "以直角街道与等分地块建图里奥伊与派里厄。", detail: { background: "希波达穆斯提出以数学方式分配城建用地，反对按血缘部族分地的旧例。", process: "约前444年希波达穆斯受命设计图里奥伊，城内以直角街网分十区；同期设计雅典派里厄新区与米利都重建。", impact: "方格网加功能分区的范式随殖民城扩散，成为希腊化与罗马新城及军营的通用底图。", figures: ["希波达穆斯", "图里奥伊建城委员会"], place: "图里奥伊、米利都、派里厄", state: "泛希腊殖民城", sources: ["亚里士多德《政治学》第二卷", "修昔底德《伯罗奔尼撒战争史》第二卷派里厄段"], tags: ["城规", "方格网", "殖民"] }, related: [] },
  { id: "world--b443--c01", track: "world", year: -443, yearApprox: true, dim: "culture", weight: 3, title: "希罗多德《历史》公布", summary: "以波斯战争为主线，首创分卷考述与见闻并录。", detail: { background: "希罗多德生于小亚哈利卡尔纳苏斯，流亡图里奥伊，游走埃及、黑海与两河收集口述。", process: "约前440年代九卷《历史》在泛雅典尼亚节等场合宣读，前九卷记各族地理风俗，后写伊奥尼亚起义至普拉提亚。", impact: "把异族风俗置于可考述的秩序中，确立考问与并存的史学方法，被后世尊为史学之父亦受修昔底德批评。", figures: ["希罗多德"], place: "雅典、图里奥伊", state: "希腊世界", sources: ["希罗多德《历史》序言及各卷", "修昔底德《伯罗奔尼撒战争史》第一卷方法自述"], tags: ["史学", "风俗志", "波斯战争"] }, related: [] },
  { id: "world--b440--e01", track: "world", year: -440, yearApprox: true, dim: "economy", weight: 3, title: "同盟币制与度量衡统一", summary: "雅典以猫头鹰银币与标准度量强盟内通用。", detail: { background: "盟邦币重与衡制不一，贡金折算与舰队补给屡生争执。", process: "约前450至前440年代颁同盟法令，各邦须以雅典四德拉克马银币与本邦衡器交易，出口谷物集中于派里厄。", impact: "阿提卡猫头鹰币成东地中海通用结算手段，雅典以币衡控制贸易节点，此制为希腊化诸王沿用。", figures: ["伯里克利斯"], place: "雅典、派里厄", state: "雅典与提洛同盟", sources: ["同盟度量衡法令铭刻残片辑录", "《剑桥古代史》第四卷"], tags: ["银币", "度量衡", "贸易"] }, related: [] },
  { id: "world--b438--a01", track: "world", year: -438, yearApprox: false, dim: "art", weight: 3, title: "雅典娜黄金象牙巨像落成", summary: "菲狄亚斯制十二米高金象牙像入帕特农后殿。", detail: { background: "帕特农大殿竣工前需内殿神像，黄金象牙工艺费巨，用金约四十塔兰同。", process: "前438年大雅典娜像立成，高约十二米，甲胄与肌肤分施金与象牙，基座刻潘多拉与诸神诞生。", impact: "该像成为古典神像的范型并被摹刻于钱币与浮雕；菲狄亚斯后因挪金与不敬案受审，反映神像与国库一体。", figures: ["菲狄亚斯", "伯里克利斯"], place: "雅典帕特农神庙", state: "雅典城邦", sources: ["普鲁塔克《伯里克利斯传》三十一节", "帕乌萨尼亚斯《希腊志》第一卷"], tags: ["金象牙", "神像", "雕塑"] }, related: [] },
  { id: "world--b432--p01", track: "world", year: -432, yearApprox: false, dim: "politics", weight: 3, title: "麦加拉敕令与最后通牒", summary: "封闭港口与市场，科林斯促斯巴达对雅典宣战。", detail: { background: "麦加拉倚科林斯海峡贩运，与雅典在墨伽拉殖民地争执；波提狄亚叛离亦由科林斯煽动。", process: "前432年公民大会通过敕令，禁麦加拉人入同盟港口与雅典市场；斯巴达开会表决，要求撤令未果。", impact: "经济封锁成为开战杠杆，伯罗奔尼撒战争由两件地方争端升级为全希腊对阵。", figures: ["伯里克利斯", "阿基达马斯二世"], place: "雅典、斯巴达、科林斯地峡", state: "雅典与伯罗奔尼撒同盟", sources: ["修昔底德《伯罗奔尼撒战争史》第一卷六十七至八十八节"], tags: ["封锁", "宣战", "同盟"] }, related: [] },
  { id: "world--b431--c01", track: "world", year: -431, yearApprox: false, dim: "culture", weight: 4, title: "阵亡者国葬演说", summary: "以公民平等与公共生活为词，成民主自我描述经典。", detail: { background: "阿提卡战争首年雅典于公共坟墓为国殁者举葬，惯由名士致辞。", process: "前431年冬伯里克利斯发表演说，称政体不由少数而由多数、穷人不碍于地位、公共事务与私人判断并行。", impact: "经修昔底德录文，此段成为后世论民主政制最常引的古典文本，也被批评为战时宣传。", figures: ["伯里克利斯", "修昔底德"], place: "雅典凯拉米科斯公墓", state: "雅典城邦", sources: ["修昔底德《伯罗奔尼撒战争史》第二卷三十五至四十六节"], tags: ["葬礼演说", "民主", "修辞"] }, related: [] },
  { id: "world--b431--a01", track: "world", year: -431, yearApprox: false, dim: "art", weight: 3, title: "欧里庇得斯《美狄亚》首演", summary: "以异邦妇人复仇写背誓，仅得竞赛第三名。", detail: { background: "战争初年起悲剧竞赛照常，欧里庇得斯把科尔奇斯公主置于被弃的科林斯宫廷。", process: "前431年上演，写伊阿宋背誓另娶，美狄亚以毒袍与杀子复仇后乘龙车离去，歌队为妇人立誓。", impact: "首次让异邦人与女性成为道德主体，其独白结构影响后世新剧与罗马悲剧，演员以女角扮演的传统亦受检验。", figures: ["欧里庇得斯"], place: "雅典狄奥尼索斯剧场", state: "雅典城邦", sources: ["欧里庇得斯《美狄亚》原文及古代题解"], tags: ["悲剧", "异邦人", "背誓"] }, related: [] },
  { id: "world--b431--m01", track: "world", year: -431, yearApprox: false, dim: "military", weight: 4, title: "阿基达马斯战争爆发", summary: "斯巴达年侵阿提卡，雅典守城恃舰队。", detail: { background: "双方备战十余年，斯巴达有陆上同盟步兵，雅典有三百船舰队与长城通道。", process: "前431年三月底比斯袭普拉提亚，五月阿基达马斯率军入阿提卡焚毁农田，依约五年三侵。", impact: "伯里克利斯避战守城、以舰队袭海岸的战略使战争长期化，农民迁居城内酿成疫病，双方皆陷消耗。", figures: ["阿基达马斯二世", "伯里克利斯", "普拉提亚守军"], place: "阿提卡、伯罗奔尼撒", state: "雅典与斯巴达两同盟", sources: ["修昔底德《伯罗奔尼撒战争史》第二卷"], tags: ["侵农", "战略", "围城"] }, related: [] },
  { id: "world--b430--d01", track: "world", year: -430, yearApprox: false, dim: "disaster", weight: 4, title: "雅典大疫", summary: "两度高发的热疫夺去约三分之一人口与伯里克利斯二子。", detail: { background: "阿提卡农民集中于长城内，卫生恶化，病自比雷埃夫斯与东地中海航线传入。", process: "前430至前426年反复暴发，始发高热、咽赤、咳喘、腹泄，第四旬多转衰竭；因无人收殓而弃尸于公共火葬堆。", impact: "人口与兵源大减，信仰与法纪动摇，修昔底德本人染病幸存并录症状；此后雅典的征兵与国库长期紧张。", figures: ["修昔底德"], place: "雅典与派里厄", state: "雅典城邦", sources: ["修昔底德《伯罗奔尼撒战争史》第二卷四十七至五十四节", "《希波克拉底文集·流行病学》对照记述"], tags: ["疫病", "人口", "丧葬"] }, related: [] },
  { id: "world--b429--f01", track: "world", year: -429, yearApprox: false, dim: "figure", weight: 3, title: "伯里克利斯去世", summary: "疫后受罚罢职，旋卒，温和民主时代告终。", detail: { background: "伯罗奔尼撒军屡侵阿提卡，盟邦米蒂利尼叛，公民大会将战事失利归咎于其战略。", process: "前430年被罚巨款并免将军职，前429年复任后不久病死，其两子先死于疫病；遗言戒亲属举哀。", impact: "后继者以公民直接授金争取支持，财政与决策更受情绪牵动；修昔底德称其名虽民主、实为第一人之治。", figures: ["伯里克利斯", "克里昂"], place: "雅典", state: "雅典城邦", sources: ["普鲁塔克《伯里克利斯传》三十五至三十九节", "修昔底德《伯罗奔尼撒战争史》第二卷"], tags: ["瘟疫", "将权", "民主"] }, related: [] },
  { id: "world--b425--a01", track: "world", year: -425, yearApprox: false, dim: "art", weight: 3, title: "阿里斯托芬《阿卡奈人》首演", summary: "以私约讲和讽刺主战派，喜剧登上政治前台。", detail: { background: "老喜剧在酒神节竞赛中可指名攻击在任将领与政客，战争疲劳使和谈成公共议题。", process: "前425年上演，农人狄凯奥波利斯自营私市与斯巴达通商，以三段歌队辩论讥诮克里昂与将领。", impact: "旧喜剧确立以城邦事务为笑料的传统，亦留下直接史料；阿里斯托芬后于《骑士》把克里昂搬上舞台受辱。", figures: ["阿里斯托芬", "克里昂"], place: "雅典勒奈亚节剧场", state: "雅典城邦", sources: ["阿里斯托芬《阿卡奈人》原文及古代演出题解"], tags: ["旧喜剧", "主战派", "和谈"] }, related: [] },
  { id: "world--b424--c01", track: "world", year: -424, yearApprox: false, dim: "culture", weight: 3, title: "修昔底德任将军与著史", summary: "援救失期遭流放，二十余年成信史方法。", detail: { background: "雅典需保住色雷斯金银与木材产地，修昔底德以财产与舰力被选为将军。", process: "前424年安菲波利斯陷落，修昔底德赴援迟缓被控通敌，流放至约前404年，期间遍访两地当事人。", impact: "其书以演证与演说重构因果，弃神意而求人性与制度，成为政治史与科学史学的方法起点。", figures: ["修昔底德", "克里昂", "伯拉西达"], place: "色雷斯、雅典", state: "雅典城邦", sources: ["修昔底德《伯罗奔尼撒战争史》第四卷序述、第一卷方法章"], tags: ["史学方法", "流放", "因果"] }, related: [] },
  { id: "world--b421--p01", track: "world", year: -421, yearApprox: false, dim: "politics", weight: 3, title: "尼基阿斯和约", summary: "五十年停战、按现状换地，科林斯与波奥提亚拒签。", detail: { background: "双方均在安菲波利斯与派罗斯损失惨重，克里昂与伯拉西达同年阵亡，和议得以成事。", process: "前421年签五十年和约，规定互还占领地与囚犯、神庙中立、争议由仲裁；斯巴达盟友以未获利益为由拒盟。", impact: "和约未能重构希腊秩序，伯罗奔尼撒同盟信誉受损，雅典主战派随即以远征西西里打破停战。", figures: ["尼基阿斯", "拉刻代蒙使团"], place: "雅典、斯巴达", state: "两大同盟", sources: ["修昔底德《伯罗奔尼撒战争史》第五卷十四至二十四节", "和约铭刻残石辑录"], tags: ["和约", "仲裁", "停战"] }, related: [] },
  { id: "world--b416--m01", track: "world", year: -416, yearApprox: false, dim: "military", weight: 3, title: "米洛斯岛陷落与处置", summary: "拒绝加入同盟的中立岛被围降，男子处死、妇孺为奴。", detail: { background: "米洛斯为斯巴达移民岛，保持中立并纳贡斯巴达，雅典欲整肃海上不服者。", process: "前416年夏围城，冬断粮而降；雅典公民大会决议处死成年男子，卖妇孺为奴，后移民三百占其地。", impact: "修昔底德以米洛斯辩论录下强权直言，成为国际道德论争的永久案例；雅典在西西里前夕已显苛暴。", figures: ["雅典使节", "米洛斯长老"], place: "米洛斯岛", state: "雅典城邦", sources: ["修昔底德《伯罗奔尼撒战争史》第五卷八十四至一百一十六节"], tags: ["围城", "奴役", "强权"] }, related: [] },
  { id: "world--b415--m01", track: "world", year: -415, yearApprox: false, dim: "military", weight: 5, title: "西西里远征出发", summary: "两百船与万余重甲远征叙拉古，亚西比德中途被召回。", detail: { background: "埃格斯塔求援并称库藏充足，雅典青年派欲以战争取粮源与荣耀。", process: "前415年夏启航，载重甲约五千一百、骑兵三百余、船百三十四；出发前夜城中赫尔墨斯石像被毁，亚西比德被控渎神，至叙拉古后被召返。", impact: "远征以战略误判与将权分裂为特征，亚西比德投奔斯巴达，建议占德凯利亚，战局由攻转守。", figures: ["亚西比德", "尼基阿斯", "拉马科斯"], place: "派里厄、卡塔尼亚、叙拉古", state: "雅典城邦", sources: ["修昔底德《伯罗奔尼撒战争史》第五卷末至第六卷", "普鲁塔克《亚西比德传》"], tags: ["远征", "渎神案", "叛投"] }, related: [] },
  { id: "world--b413--m01", track: "world", year: -413, yearApprox: false, dim: "military", weight: 3, title: "叙拉古围城军覆没", summary: "海港被封、陆墙断援，七万陆军终降于采石场。", detail: { background: "尼基阿斯迟迟不撤，斯巴达援将吉利波斯入城，叙拉古舰队增至与雅典相当。", process: "前413年九月雅典海军战败于大港，陆路撤退夜误于月蚀迟疑，终被截于阿西纳波斯河，主力在采石场投降。", impact: "雅典损失战舰约两百、兵员数万，国库与兵源枯竭，远征军整建制覆没是古典史上罕有之败。", figures: ["尼基阿斯", "德谟斯提尼斯（将军）", "吉利波斯"], place: "叙拉古", state: "雅典与叙拉古", sources: ["修昔底德《伯罗奔尼撒战争史》第七卷、第八卷首"], tags: ["围城", "舰队", "降卒"] }, related: [] },
  { id: "world--b413--m02", track: "world", year: -413, yearApprox: false, dim: "military", weight: 3, title: "斯巴达占德凯利亚", summary: "在阿提卡立永久要塞，两万奴隶逃往叙拉古。", detail: { background: "亚西比德献策：短期入侵无用，应在敌境常年筑垒断其农时与银矿。", process: "前413年国王阿基斯二世率军占据德凯利亚，筑垒驻守，连年劫掠阿提卡田庄。", impact: "劳里昂银矿停产、租银锐减，公民大会被迫向盟邦强征与课港口税，雅典财政从此依赖海运收入。", figures: ["阿基斯二世", "亚西比德"], place: "阿提卡德凯利亚", state: "斯巴达", sources: ["修昔底德《伯罗奔尼撒战争史》第六卷末、第七卷十八至十九节", "色诺芬《希腊志》第二卷收入章"], tags: ["要塞", "奴隶逃亡", "财政"] }, related: [] },
  { id: "world--b411--p01", track: "world", year: -411, yearApprox: false, dim: "politics", weight: 3, title: "四百人寡头政变", summary: "公民大会改选四百家，民主在两周内被废。", detail: { background: "西西里败后民心震动，奥林托罗戈斯等以召回旧贵族可获波斯资助为号召。", process: "前411年四月在科洛诺斯开会，废五千人与九执政官之权，选四百人议事会；不久内讧，温和派推翻极端派。", impact: "水师与萨摩斯拒不承认新政，民主在前410年复辟；亚里士多德称此案暴露寡头派缺乏群众基础。", figures: ["普桑德尔", "弗吕尼科斯", "特拉绪布鲁斯"], place: "雅典、萨摩斯", state: "雅典城邦", sources: ["亚里士多德《雅典政制》第二十九至三十三节", "修昔底德《伯罗奔尼撒战争史》第八卷"], tags: ["寡头", "复辟", "水师"] }, related: [] },
  { id: "world--b406--i01", track: "world", year: -406, yearApprox: false, dim: "institution", weight: 3, title: "六将军未经审判被处死", summary: "胜战后因未救落水者遭集体审判处刑。", detail: { background: "阿吉努萨海战雅典获胜，八船因风暴未及回收落难水手，公民群情激愤。", process: "前406年将军们被同案起诉、集体表决，六人就刑；塞萨利亚等城为其立碑昭雪，苏格拉底时任议事会议员曾反对程序。", impact: "该案成为雅典司法自我批评的标本，色诺芬与亚里士多德皆指其违法；此后将领避任、指挥趋于保守。", figures: ["苏格拉底", "特拉叙布鲁斯"], place: "雅典", state: "雅典城邦", sources: ["色诺芬《希腊志》第一卷七章", "亚里士多德《政治学》第三卷论集体审判"], tags: ["审判", "程序", "水师"] }, related: [] },
  { id: "world--b405--m01", track: "world", year: -405, yearApprox: false, dim: "military", weight: 3, title: "羊河之战舰队被歼", summary: "吕山德突袭停泊中的雅典舰队，俘船近两百。", detail: { background: "雅典最后一支远征舰队泊于赫勒斯滂羊河口，日日出泊挑衅而敌不动。", process: "前405年秋，吕山德待敌军散就食时突入，俘一百五十余船，杀水手三千余；仅科农等八船逃。", impact: "雅典失去制海与粮道，塞斯托斯围城八月后饥饿请降，伯罗奔尼撒战争以雅典战败告终。", figures: ["吕山德", "科农", "特拉叙布鲁斯"], place: "赫勒斯滂羊河口", state: "斯巴达", sources: ["色诺芬《希腊志》第二卷一章", "狄奥多罗斯《历史丛书》第十四卷"], tags: ["海战", "封锁", "饥降"] }, related: [] },
  { id: "world--b404--p01", track: "world", year: -404, yearApprox: false, dim: "politics", weight: 4, title: "雅典投降与和约条款", summary: "拆长城、交舰队、三十人执政，同盟解散。", detail: { background: "饥困中的雅典派使求和，斯巴达内部虽反对毁城但将领坚持苛刻条件。", process: "前404年和约：拆长墙与派里厄城垣，留十二船，交出战败期全部船只与人员，拆毁帝国并听斯巴达号令。", impact: "希腊失去可能统一的海权政体，流亡贵族与三十人统治引发内战，斯巴达的霸权从此失去合法性。", figures: ["吕山德", "特拉迈叙鲁斯", "克里提阿斯"], place: "雅典、斯巴达", state: "雅典与斯巴达", sources: ["色诺芬《希腊志》第二卷二章", "亚里士多德《雅典政制》第三十四章"], tags: ["和约", "寡头", "霸权"] }, related: [] },
  { id: "world--b403--p01", track: "world", year: -403, yearApprox: false, dim: "politics", weight: 3, title: "民主复辟与全面大赦", summary: "以不记前罪为誓重建民主，并编定新法典。", detail: { background: "特拉绪布鲁斯自费莱山聚流亡者，比雷埃夫斯之战胜三十人，内战死伤后需和解。", process: "前403年订大赦誓，除三十人核心外不追既往；选欧克利德斯任名年执政官，公法由诺莫得泰编校并刻石。", impact: "以自我限制暴力换取城邦统一，成为后世内战和解的经典范式；同时苏格拉底案的历史阴影由此埋下。", figures: ["特拉绪布鲁斯", "欧克利德斯", "安尼图斯"], place: "雅典、比雷埃夫斯", state: "雅典城邦", sources: ["亚里士多德《雅典政制》第三十五至三十九章", "色诺芬《希腊志》第二卷四章"], tags: ["大赦", "法典", "和解"] }, related: [] },
  { id: "world--b401--m01", track: "world", year: -401, yearApprox: false, dim: "military", weight: 3, title: "万人大撤退", summary: "雇佣希腊军自两河退至黑海，暴露波斯腹地空虚。", detail: { background: "小居鲁士借希腊重甲一万一千争王位，前401年库纳克萨战败身死，将领被诱杀。", process: "色诺芬等选新将，沿底格里斯—山道退至特拉佩祖斯，历时约五月，日行军与卡杜启人山战不绝。", impact: "希腊重甲方阵在两千里敌境内存活，波斯不可战胜的神话破灭；此事为亚历山大东征提供路线与情报。", figures: ["色诺芬", "克里尔库斯", "提萨弗尼斯"], place: "两河流域至黑海南岸", state: "波斯帝国与希腊雇佣军", sources: ["色诺芬《长征记》前四卷", "《剑桥古代史》第六卷"], tags: ["撤退", "雇佣军", "方阵"] }, related: [] },
  { id: "world--b400--s01", track: "world", year: -400, yearApprox: true, dim: "science", weight: 4, title: "希波克拉底文集成形", summary: "科斯学派以观察、预后与四体液立医学规范。", detail: { background: "医学自神庙祈愈与哲学宇宙论分出，科斯与克尼多两派竞讲病机。", process: "约前五世纪末至前四世纪编定约六十篇，含《流行病学》《预后》《论空气饮水地方》等，逐日记热、脉、便、神志。", impact: "把疾病写成可观察可预期的自然过程，四体液说主导欧洲与伊斯兰医学逾两千年；誓言确立医者伦理。", figures: ["希波克拉底"], place: "科斯岛", state: "希腊医派", sources: ["《希波克拉底文集》篇目校释本", "盖伦注希波克拉底残篇"], tags: ["医学", "预后", "体液"] }, related: [] },
  { id: "world--b400--c01", track: "world", year: -400, yearApprox: true, dim: "culture", weight: 3, title: "德谟克利特的原子论", summary: "以原子与虚空解释万象，著述及自然与伦理。", detail: { background: "承留基伯之说，回应巴门尼德关于存在不可分的诘难。", process: "约前5世纪末至前4世纪初讲学于阿布德拉，主张原子形状、排列与位置成物，感觉为约定而非真性。", impact: "其说经伊壁鸠鲁与卢克莱修传至近代，成为原子论传统的古代源头；其伦理著作则倡宁静与有度。", figures: ["德谟克利特", "留基伯"], place: "阿布德拉", state: "希腊自然哲学", sources: ["亚里士多德《论生成与毁灭》卷一述评", "第欧根尼·拉尔修《名哲言行录》第九卷"], tags: ["原子", "感觉", "伦理"] }, related: [] },
  { id: "world--b399--c01", track: "world", year: -399, yearApprox: false, dim: "culture", weight: 4, title: "苏格拉底受审与饮鸩", summary: "以不敬与败坏青年罪成，五十人法庭表决处死。", detail: { background: "内战后大赦禁止追诉旧案，控方改以宗教与教育之名发难，安尼图斯等三人起诉。", process: "前399年五月开庭，五百零一名陪审员表决，先定罪后量刑；拒绝流放与朋友劝逃，如期饮钩吻而死。", impact: "柏拉图以《申辩》《克力同》《斐多》记之，开哲学与城邦张力的母题；其追问方法成后世辩证法原型。", figures: ["苏格拉底", "柏拉图", "安尼图斯", "克里同"], place: "雅典法庭与囚所", state: "雅典城邦", sources: ["柏拉图《申辩篇》", "色诺芬《回忆苏格拉底》第一卷", "第欧根尼·拉尔修《名哲言行录》第二卷"], tags: ["审判", "哲学", "殉道"] }, related: [] },
  { id: "world--b394--m01", track: "world", year: -394, yearApprox: false, dim: "military", weight: 3, title: "克尼多斯海战", summary: "波斯-希腊联合舰队歼斯巴达海军，长墙重建。", detail: { background: "阿格西劳斯在亚细亚连胜，雅典与科林斯、阿尔戈斯结反斯巴达同盟并求波斯金。", process: "前394年科农与波斯总督法尔纳巴佐斯率九十九船，在克尼多斯角击溃斯巴达舰队，斯巴达统帅皮桑德尔战死。", impact: "斯巴达失去爱琴海，波以金换地：和小亚希腊城重归波斯；雅典靠波斯钱重建长墙，科林斯战争持续至前387年。", figures: ["科农", "法尔纳巴佐斯", "阿格西劳斯二世"], place: "克尼多斯", state: "波斯与反斯巴达同盟", sources: ["色诺芬《希腊志》第四卷二章", "狄奥多罗斯《历史丛书》第十四卷"], tags: ["海战", "金援", "长墙"] }, related: [] },
  { id: "world--b390--m01", track: "world", year: -390, yearApprox: true, dim: "military", weight: 4, title: "高卢人破罗马城", summary: "阿利亚河溃败后城被焚，卡皮托林山以鹅警守。", detail: { background: "塞诺内斯等波埃高卢部落南下伊特鲁里亚，罗马遣三使调停而违约参战。", process: "约前390（或前387）阿利亚河边六个军团溃，居民多逃，城焚七日；卡皮托林山被围，守军夜攀崖袭营。", impact: "李维谓此即罗马第二次建国：祭司年表中断、古籍佚失，此后筑塞尔维乌斯城墙、军制改大队，并对高卢怀世仇。", figures: ["布伦努斯", "卡米卢斯"], place: "罗马", state: "罗马共和国", sources: ["李维《自建城以来》第五卷", "普鲁塔克《卡米卢斯传》"], tags: ["劫掠", "城防", "军制"] }, related: [] },
  { id: "world--b387--p01", track: "world", year: -387, yearApprox: true, dim: "politics", weight: 3, title: "大王和约", summary: "以波斯王名义确认诸邦独立，小亚城归波斯。", detail: { background: "科林斯战争因波斯金援而难决，斯巴达使者安塔尔基达斯赴苏萨请和。", process: "前387（或前386）约成：小亚细亚诸城与克拉兹美奈归王，其余希腊邦一律独立，舰队限十二船以下。", impact: "希腊以自治之名接受外邦裁定，斯巴达获执法权而独行，底比斯因拒签被孤立，曼丁尼亚体系至前362年崩解。", figures: ["安塔尔基达斯", "阿尔塔薛西斯二世", "阿格西劳斯二世"], place: "苏萨、斯巴达", state: "波斯帝国与希腊诸邦", sources: ["色诺芬《希腊志》第四卷八章", "狄奥多罗斯《历史丛书》第十四卷"], tags: ["和约", "自治", "波斯"] }, related: [] },
  { id: "world--b387--i01", track: "world", year: -387, yearApprox: true, dim: "institution", weight: 4, title: "柏拉图创立阿卡德米学园", summary: "在圣林公地上办学，以几何与辩证法为课程。", detail: { background: "苏格拉底之死使柏拉图离雅典游历梅加腊、昔勒尼与埃及，返后购地开学。", process: "约前387年创学园于城墙外阿卡德米圣林，门额传刻不通几何者勿入，设讲辩、数学与天文课程，收女生与外邦人。", impact: "办学延续约九百年至前86年中断，形成第一所系统性研究型学园；其理念为后世大学与研究院所本。", figures: ["柏拉图", "斯彪西波"], place: "雅典城外阿卡德米", state: "雅典城邦", sources: ["第欧根尼·拉尔修《名哲言行录》第三卷", "《剑桥古代史》第六卷"], tags: ["学园", "教育", "几何"] }, related: [] },
  { id: "world--b380--c01", track: "world", year: -380, yearApprox: true, dim: "culture", weight: 3, title: "《理想国》写成", summary: "以正义之问构三阶城邦与哲人王之治。", detail: { background: "雅典民主在战败与三十人之治后信誉受损，柏拉图追问何种政制可使人不私其利。", process: "约前390至前380年代写成十卷，由凯法洛斯家对话起，设卫国者、辅助者、生产者三阶，以洞喻与日喻说善的理念。", impact: "确立了以教育选拔替代血统与财富的乌托邦传统，亦遭亚里士多德与近代自由主义批评其共产与审查主张。", figures: ["柏拉图", "格劳孔", "苏格拉底"], place: "雅典、学园", state: "希腊思想界", sources: ["柏拉图《理想国》卷二至卷七", "亚里士多德《政治学》卷二批驳"], tags: ["政制", "正义", "教育"] }, related: [] },
  { id: "world--b378--p01", track: "world", year: -378, yearApprox: false, dim: "politics", weight: 3, title: "第二次雅典海上同盟", summary: "明言不纳贡、不得有雅典官，十七邦起盟。", detail: { background: "斯巴达在留克特拉前仍驻底比斯卫城，海上征税激起盟邦旧怨。", process: "前378年公民大会通过公民大会决议，立同盟：不设总督、不纳贡、争端回雅典仲裁，初十七邦后逾六十。", impact: "以反斯巴达为旗号重建雅典海权，却仍渐生驻将征金之弊；前357年同盟战争即为旧病复发。", figures: ["哈布里阿斯", "提摩太奥斯"], place: "雅典", state: "雅典与其盟邦", sources: ["第二次同盟决议铭刻全文辑录", "狄奥多罗斯《历史丛书》第十五卷"], tags: ["海盟", "免贡", "铭刻"] }, related: [] },
  { id: "world--b373--d01", track: "world", year: -373, yearApprox: false, dim: "disaster", weight: 3, title: "赫利刻一夜陆沉", summary: "地震与海侵吞没阿凯亚城，两千人逃出。", detail: { background: "赫利刻为阿凯亚十二城之首，奉波塞冬为邦神，据传因夺祭器触怒神。", process: "前373年冬夜连震，次夜海水涌入，全城与十船随沉陷没入海湾；逃者得免，邻境亦陷裂。", impact: "古代视为神罚，德尔斐令献金赎罪；今考古在海湾故址下发现古典期城垣与墓葬，为地史与考古对照的坐标。", figures: ["阿凯亚使节"], place: "科林斯湾赫利刻", state: "阿凯亚同盟", sources: ["狄奥多罗斯《历史丛书》第十五卷", "老普林尼《自然史》第二卷"], tags: ["地震", "海侵", "考古"] }, related: [] },
  { id: "world--b371--m01", track: "world", year: -371, yearApprox: false, dim: "military", weight: 4, title: "留克特拉战役", summary: "底比斯以五十列纵深斜击，斯巴达精锐歼灭。", detail: { background: "底比斯拒签大王和约，斯巴达以克雷翁布罗图斯率六千余入波奥提亚。", process: "前371年八月，伊巴米农达斯将圣队与主力列于左翼五十列，令右翼后却斜进，一击破斯巴达王军。", impact: "三百名圣队与六百斯巴达公民兵仅约三百七十生还，斯巴达军事神话破产，底比斯取得十年霸权。", figures: ["伊巴米农达斯", "克雷翁布罗图斯", "佩罗皮达斯"], place: "波奥提亚留克特拉", state: "底比斯与斯巴达", sources: ["色诺芬《希腊志》第六卷四章", "普鲁塔克《佩罗皮达斯传》"], tags: ["方阵", "斜线", "霸权"] }, related: [] },
  { id: "world--b369--m01", track: "world", year: -369, yearApprox: false, dim: "military", weight: 3, title: "底比斯解放美塞尼亚", summary: "两侵拉科尼亚，建都邦城并散希洛人为自由民。", detail: { background: "美塞尼亚自前七世纪被斯巴达征服，希洛人世代为其农业剩余劳力。", process: "前370至前369年伊巴米农达斯两度入伯罗奔尼撒，前369年建美塞尼亚都邦，又立麦加罗波利斯合阿凯亚村落。", impact: "斯巴达失去约三分之一的土地与劳役来源，从此沦为二流邦；底比斯以解放之名确立对半岛的支配。", figures: ["伊巴米农达斯", "墨萨涅（传说命名女王）"], place: "拉科尼亚、美塞尼亚", state: "底比斯", sources: ["色诺芬《希腊志》第六卷四至五章", "帕乌萨尼亚斯《希腊志》第四卷"], tags: ["希洛人", "建城", "霸权"] }, related: [] },
  { id: "world--b367--i01", track: "world", year: -367, yearApprox: false, dim: "institution", weight: 4, title: "李锡尼-塞克斯图法", summary: "两执政官必有一平民，并限占公地与清债。", detail: { background: "连年战争使平民失地与负债，护民官李锡尼与财务官塞克斯图提出三案。", process: "前367年通过：执政官二人中一人为平民，债务利息已偿者从本金扣除，个人占公地不得逾五百尤盖拉。", impact: "罗马权力门径首次以法条向平民开放，此后贵族以选举与宗教职反制，形成新的等级妥协。", figures: ["盖乌斯·李锡尼", "卢西乌斯·塞克斯图", "马尔库斯·弗乌里乌斯"], place: "罗马", state: "罗马共和国", sources: ["李维《自建城以来》第六卷", "阿庇安《罗马史·内战史》卷一论公地"], tags: ["官职", "公地", "债务"] }, related: [] },
  { id: "world--b362--m01", track: "world", year: -362, yearApprox: false, dim: "military", weight: 3, title: "曼丁尼亚战役与霸权崩解", summary: "两军主帅俱亡，战后希腊无邦能断胜负。", detail: { background: "麦加罗波利斯与斯巴达争执，底比斯再次北援伯罗奔尼撒。", process: "前362年七月会战，底比斯骑兵先破，伊巴米农达斯以斜阵突入敌营受刺，临终劝立后印与和约。", impact: "战术胜而战略败，双方皆弃战场；前361年所谓通约和约签订但斯巴达拒签，希腊进入集体疲弱期。", figures: ["伊巴米农达斯", "阿格西劳斯二世", "达马斯提昂"], place: "阿凯亚曼丁尼亚", state: "底比斯与反底比斯联军", sources: ["色诺芬《希腊志》第七卷五章", "狄奥多罗斯《历史丛书》第十五卷"], tags: ["会战", "主帅阵亡", "和约"] }, related: [] },
  { id: "world--b360--s01", track: "world", year: -360, yearApprox: true, dim: "science", weight: 3, title: "尼多斯的阿佛洛狄忒", summary: "普拉克西特列斯作裸体女神像，开女性全裸先例。", detail: { background: " 科斯与尼多斯同求一像，科斯因避羞而取衣饰版，尼多斯得裸像。", process: "约前360年代普拉克西特列斯以帕罗斯大理石作坐立于浴室前的女神，发式与体量成对式样，前四世纪末广为摹刻。", impact: "女性裸体自此起为高雅艺术题材，希腊化与罗马时期摹本逾百，成为后世人体表现的传统源头。", figures: ["普拉克西特列斯", "弗里涅"], place: "尼多斯", state: "希腊小亚城邦", sources: ["老普林尼《自然史》第三十六卷", "帕乌萨尼亚斯《希腊志》第五卷"], tags: ["雕塑", "裸体", "摹本"] }, related: [] },
  { id: "world--b359--p01", track: "world", year: -359, yearApprox: true, dim: "politics", weight: 3, title: "腓力二世继位与马其顿改制", summary: "以长矛方阵与金币重组军队，收金矿为财。", detail: { background: "前359年佩尔狄卡斯三世对伊利里亚战死，婴主在位，北方三敌压境。", process: "腓力摄政后自立：步兵执六米长萨里沙、配轻盾与小盔，编大队与伙伴骑兵；以安菲波利斯金山铸金斯塔特，银币按岛制。", impact: "马其顿由边邦转为能常年动员两万余人的军国，其合成军制与财制成为亚历山大东征的物质基础。", figures: ["腓力二世", "帕尔梅尼奥", "安提帕特"], place: "佩拉、安菲波利斯", state: "马其顿王国", sources: ["狄奥多罗斯《历史丛书》第十六卷", "《剑桥古代史》第六卷"], tags: ["军制", "金币", "矿藏"] }, related: [] },
  { id: "world--b356--d01", track: "world", year: -356, yearApprox: true, dim: "disaster", weight: 3, title: "以弗所神庙纵火案", summary: "希罗斯特拉图斯为留名焚毁阿尔忒弥斯大神庙。", detail: { background: "以弗所阿尔忒弥斯神庙为爱奥尼亚圣域，列柱百二十余，藏丰献礼。", process: "前356（或前355）夜，本地人希罗斯特拉图斯在灯下纵火，神殿与像毁；审讯后城邦禁其提名，仍流传后世。", impact: "神庙按名匠克雷特塞斯方案重建，规模更大，名列七大奇迹；此事成古代关于名声与破坏动机的道德案例。", figures: ["希罗斯特拉图斯", "克雷特塞斯"], place: "以弗所", state: "爱奥尼亚希腊城", sources: ["老普林尼《自然史》第十六卷、第三十六卷", "斯特拉波《地理学》第十四卷"], tags: ["纵火", "神庙", "名声"] }, related: [] },
  { id: "world--b351--c01", track: "world", year: -351, yearApprox: false, dim: "culture", weight: 3, title: "德摩斯提尼首次反腓力演说", summary: "以三句比克论海防，劝雅典以税制养舰队。", detail: { background: "腓力向色雷斯与卡尔基狄克扩张，雅典舰队因富人逃避财产捐助而常年不足。", process: "前351年德摩斯提尼在公民大会首就腓力发言，主张改财产捐助与观剧津贴，募步兵与骑兵。", impact: "开启其二十余年反马其顿宣传，亦暴露雅典财政动员的制度困境；其演说成后世政治修辞的教材。", figures: ["德摩斯提尼", "腓力二世"], place: "雅典普尼克斯山", state: "雅典城邦", sources: ["德摩斯提尼《第一腓力皮克》", "普鲁塔克《德摩斯提尼传》"], tags: ["演说", "税制", "反马其顿"] }, related: [] },
  { id: "world--b348--m01", track: "world", year: -348, yearApprox: false, dim: "military", weight: 3, title: "奥林索斯陷落", summary: "内应开门，城被夷、居民四散，同盟解散。", detail: { background: "卡尔基狄克同盟以奥林索斯为首，先与马其顿结盟后叛，腓力围之两年。", process: "前348年因二人引兵入城，城垣拆平，领土分予盟友，自由民多被卖为奴；斯塔吉拉同期被围后重建。", impact: "爱琴海北岸诸邦不再能抗拒马其顿，雅典失去殖民与木材来源，和战之争促成了前346年和约。", figures: ["腓力二世", "欧提克拉特底斯", "阿斯忒洛波斯"], place: "卡尔基狄克奥林索斯", state: "马其顿王国", sources: ["狄奥多罗斯《历史丛书》第十六卷", "德摩斯提尼《奥林托利亚克斯》"], tags: ["围城", "内应", "同盟"] }, related: [] },
  { id: "world--b347--f01", track: "world", year: -347, yearApprox: false, dim: "figure", weight: 3, title: "柏拉图逝世与学园传承", summary: "年八十一卒，学园长由亲属与弟子相继接任。", detail: { background: "晚年三度赴叙拉古教狄奥尼修斯二世失败，返雅典著《法律篇》未竟。", process: "前347年卒于雅典，遗嘱解放女奴并留园产；斯彪西波继任，后又传色诺克拉底，亚里士多德离学园赴亚索斯。", impact: "学园由理念论转向数学与辩证法研究，延续九个多世纪，其藏书与讲录为后世希腊哲学的骨干传承。", figures: ["柏拉图", "斯彪西波", "亚里士多德", "色诺克拉底"], place: "雅典学园", state: "希腊思想界", sources: ["第欧根尼·拉尔修《名哲言行录》第三卷、第四卷", "柏拉图《法律篇》末卷（未竟）"], tags: ["学园", "继承", "遗嘱"] }, related: [] },
  { id: "world--b346--p01", track: "world", year: -346, yearApprox: false, dim: "politics", weight: 3, title: "菲洛克拉特斯和约", summary: "雅典承认马其顿所得，宣誓不入敌盟。", detail: { background: "腓力取安提凯里亚、克拉塞罗奈与马格涅西亚，色萨利与伊利斯入其同盟。", process: "前346年以十人使团议和，约成于双方现占有地为基础，各不相攻；腓力遂以安菲克提昂主持者身份入希腊会议。", impact: "雅典以自保换取不干涉，德摩斯提尼斥其为卖盟；德尔菲近邻同盟会籍易手，为前338年喀罗尼亚铺路。", figures: ["菲洛克拉特斯", "德摩斯提尼", "埃斯库林涅斯"], place: "佩拉、雅典", state: "马其顿与雅典", sources: ["狄奥多罗斯《历史丛书》第十六卷", "埃斯库林涅斯《反提马尔库斯》"], tags: ["和约", "近邻同盟", "亲马其顿"] }, related: [] },
  { id: "world--b343--m01", track: "world", year: -343, yearApprox: false, dim: "military", weight: 3, title: "第一次萨莫奈战争", summary: "卡普亚求属罗马，罗马兵入坎帕尼亚。", detail: { background: "萨莫奈山民围卡普亚，该城以款附求援；元老院以同盟誓约接纳。", process: "前343至前341年执政官科尔温努斯与瓦勒里乌斯两路入坎帕尼亚，山道小胜后议和，罗马驻军未果。", impact: "罗马的盟约网越出拉丁与萨宾，伸入希腊化城市圈，为后续两次萨莫奈战争与南意大利秩序埋下冲突。", figures: ["阿乌卢斯·科尔温努斯", "瓦勒里乌斯·科乌斯"], place: "坎帕尼亚", state: "罗马共和国与卡普亚", sources: ["李维《自建城以来》第七卷", "狄奥多罗斯《历史丛书》第十六卷"], tags: ["附庸", "山道战", "盟约"] }, related: [] },
  { id: "world--b341--m01", track: "world", year: -341, yearApprox: false, dim: "military", weight: 3, title: "拉丁战争与城权重构", summary: "拉丁城争平等执政官，战败后只得无投票权公民籍。", detail: { background: "前340年拉丁人与坎帕尼亚人不满罗马单方征税与征兵，要求二人中一执政官归拉丁。", process: "前340至前338年两军会战于维苏威与菲拉里亚，罗马一方以双倍军力与内部分化取胜，城邦或拆墙或驻守。", impact: "以无表决权的公民籍、殖民城与条约城三种层级取代平等同盟，此差别体制成为罗马扩张的样板。", figures: ["马尔库斯·瓦勒里乌斯", "卢基乌斯·安尼乌斯（拉丁统帅）", "普布利乌斯·德奇乌斯"], place: "拉丁姆、坎帕尼亚", state: "罗马共和国与拉丁同盟", sources: ["李维《自建城以来》第八卷", "《剑桥古代史》第七卷"], tags: ["公民权", "殖民", "差别同盟"] }, related: [] },
  { id: "world--b338--m01", track: "world", year: -338, yearApprox: false, dim: "military", weight: 4, title: "喀罗尼亚战役", summary: "马其顿联军击破雅典与底比斯，圣队全员战死。", detail: { background: "安菲克提昂以耕地寺产案向福基斯课金，腓力借机入中希腊，雅典与底比斯结盟抗之。", process: "前338年夏秋之际会战于玻奥提亚喀罗尼亚平原，马其顿右翼由亚历山大率领击溃底比斯圣队三百人。", impact: "城邦自主军队的时代终结：雅典城墙外收埋战死者，底比斯驻马其顿卫戍，腓力取得对全希腊用兵的主导权。", figures: ["腓力二世", "亚历山大三世", "德摩斯提尼"], place: "玻奥提亚喀罗尼亚", state: "马其顿与雅典底比斯联军", sources: ["狄奥多罗斯《历史丛书》第十六卷", "普鲁塔克《德摩斯提尼传》"], tags: ["会战", "圣队", "霸权"] }, related: [] },
  { id: "world--b337--i01", track: "world", year: -337, yearApprox: false, dim: "institution", weight: 3, title: "科林斯同盟成立", summary: "诸邦推马其顿王为统帅，设共同会议表决战和。", detail: { background: "喀罗尼亚后腓力入伯罗奔尼撒，拆反马其顿的麦加罗波利斯，但以平等盟约而非附庸待诸邦。", process: "前337年在科林斯立同盟：成员保留内政与地产，按比例派代表入共同会议，战时由盟主统率，不得擅起兵。", impact: "希腊首次出现常设的邦际议事机构，其表决机器成为后世近邻同盟扩编与联邦论的模型；远征波斯据此征税征兵。", figures: ["腓力二世", "科林斯各邦代表"], place: "科林斯", state: "马其顿与科林斯同盟", sources: ["狄奥多罗斯《历史丛书》第十六卷", "科林斯同盟决议铭刻残片辑录"], tags: ["同盟", "议事会", "盟主"] }, related: [] },
  { id: "world--b336--p01", track: "world", year: -336, yearApprox: false, dim: "politics", weight: 3, title: "腓力二世在埃盖遇刺", summary: "婚礼剧场中被近卫刺杀，二十岁亚历山大继位。", detail: { background: "腓力将女儿克娄巴特拉嫁与伊庇鲁斯王亚历山大，自己已在阿塔路斯前婚礼上立新后。", process: "前336年十月在马其顿旧都埃盖剧场，近卫保桑尼亚斯以匕首刺杀腓力，当场被藤枝刺死；动机至今众说。", impact: "亚历山大即位数周内清算王族竞争者并镇压伊利里亚与色雷斯叛乱，未等波斯的反攻先渡海峡。", figures: ["腓力二世", "亚历山大三世", "保桑尼亚斯", "奥林匹亚丝"], place: "马其顿埃盖", state: "马其顿王国", sources: ["狄奥多罗斯《历史丛书》第十六卷、第十七卷", "普鲁塔克《亚历山大传》"], tags: ["刺杀", "继位", "近卫"] }, related: [] },
  { id: "world--b335--i01", track: "world", year: -335, yearApprox: false, dim: "institution", weight: 4, title: "亚里士多德建吕克昂学园", summary: "以公款租房讲学，辑百五十余邦政制与博物资料。", detail: { background: "亚里士多德离开柏拉图学园后在莱斯博斯与佩拉讲学，回雅典时无公民权者不得置产，遂租吕克昂体育场旁屋。", process: "前335年前后开课，晨讲高深、午讲通俗，弟子分题采集一百五十八邦政制、动物志、植物志与矿物说。", impact: "经验分类与专题协作的研究方式首次制度化，泰奥弗拉斯托斯的植物与矿物著作、后世博学传统皆出其门。", figures: ["亚里士多德", "泰奥弗拉斯托斯", "德摩斯提尼（同期讲士）"], place: "雅典吕克昂", state: "雅典城邦", sources: ["第欧根尼·拉尔修《名哲言行录》第五卷", "《剑桥古代史》第六卷"], tags: ["学园", "分类", "博物"] }, related: [] },
  { id: "world--b335--m01", track: "world", year: -335, yearApprox: false, dim: "military", weight: 4, title: "底比斯城被毁与居民处置", summary: "七日而下，男子见杀、妇孺入奴，其地分予盟友。", detail: { background: "亚历山大转战色雷斯时传其已死，底比斯遂杀马其顿卫戍军官并围另两城。", process: "前335年八月围城三日破城，死者约六千，三万余人卖为奴，城夷平；唯神庙、宾亲友属与诗人后裔得免。", impact: "以一次极端惩戒换得希腊十年不敢再叛，雅典当场遣使劳军；此事亦成为古代关于威慑与城邦毁灭的著名案例。", figures: ["亚历山大三世", "底比斯守军将领"], place: "波奥提亚底比斯", state: "马其顿王国", sources: ["狄奥多罗斯《历史丛书》第十七卷", "普鲁塔克《亚历山大传》十一至十四章"], tags: ["毁城", "奴卖", "威慑"] }, related: [] },
  { id: "world--b334--m01", track: "world", year: -334, yearApprox: false, dim: "military", weight: 3, title: "格拉尼库斯河之战", summary: "渡河突击破波斯总督联军，小亚希腊城相继开门。", detail: { background: "亚历山大以三万余步兵、五千余骑渡赫勒斯滂，波斯在小亚驻有重兵并掌制海。", process: "前334年五月会战于格拉尼库斯河西岸，马其顿骑兵破其两翼，波斯总督与雇佣步兵阵亡数千。", impact: "萨第斯、以弗所等城不战而下，亚历山大以恢复自治为号撤卫戍，却仍征收原付波斯的贡金。", figures: ["亚历山大三世", "帕尔梅尼奥", "波斯总督阿尔西特斯"], place: "小亚格拉尼库斯河", state: "马其顿与波斯", sources: ["阿里安《亚历山大远征记》第一卷", "普鲁塔克《亚历山大传》十六节"], tags: ["渡河", "总督", "开门"] }, related: [] },
  { id: "world--b333--m01", track: "world", year: -333, yearApprox: false, dim: "military", weight: 3, title: "伊苏斯战役", summary: "海岸狭地击溃王大军的步兵，俘其妻母儿女。", detail: { background: "亚历山大病中北上，波斯王大流士三世避开其锋，占其后方伊苏斯断其归路。", process: "前333年十一月在皮纳鲁斯河口狭岸会战，马其顿右翼直插敌阵，波斯左翼崩溃，王大母与妻女被俘。", impact: "波斯失去小亚税源与辎重，亚历山大以宽礼待王族为政治资本；推罗与埃及自此向其开放海岸。", figures: ["亚历山大三世", "大流士三世", "帕尔梅尼奥"], place: "奇里乞亚伊苏斯", state: "马其顿与波斯", sources: ["阿里安《亚历山大远征记》第二卷", "狄奥多罗斯《历史丛书》第十七卷"], tags: ["会战", "俘虏", "狭地"] }, related: [] },
  { id: "world--b332--m01", track: "world", year: -332, yearApprox: false, dim: "military", weight: 3, title: "推罗七个月围城", summary: "筑堤断岛城，以船载攻城器破其海墙。", detail: { background: "推罗表面归附而仍奉其海上保护神，城内藏波斯舰队与大量库存。", process: "前332年一月起筑六百英尺宽海堤，陆上造高台与撞锤，西顿与塞浦路斯船来助，七月后城墙破。", impact: "据古代记载破城后屠杀与出卖者数万，沿路钉十字架二千；此役确立马其顿军可克任何设防海岸的名声。", figures: ["亚历山大三世", "推罗王阿巴尔芒", "西顿使节"], place: "腓尼基推罗", state: "马其顿与推罗", sources: ["阿里安《亚历山大远征记》第二卷", "《剑桥古代史》第六卷"], tags: ["筑堤", "攻城器", "屠戮"] }, related: [] },
  { id: "world--b332--p01", track: "world", year: -332, yearApprox: false, dim: "politics", weight: 3, title: "埃及归附与锡瓦神谕", summary: "以解放者入孟斐斯，赴锡瓦问阿蒙神子之说。", detail: { background: "波斯在埃及统治失人心，当地祭司与居民视马其顿军为驱波之力。", process: "前332年末亚历山大入孟斐斯，依埃及礼加冠并祭圣牛；翌年春西行锡瓦绿洲，向阿蒙祭司献问。", impact: "王号与阿蒙之子的称号为其死后托勒密王朝的神圣合法性奠基，亦为其在希腊世界被奉为近神之人的起点。", figures: ["亚历山大三世", "锡瓦阿蒙祭司"], place: "孟斐斯、锡瓦绿洲", state: "马其顿治埃及", sources: ["阿里安《亚历山大远征记》第三卷", "普鲁塔克《亚历山大传》二十六至二十七节"], tags: ["加冠", "神谕", "合法性"] }, related: [] },
  { id: "world--b331--m01", track: "world", year: -331, yearApprox: false, dim: "military", weight: 5, title: "高加米拉决战", summary: "以斜开通道破刀轮车与象队，王大营尽获。", detail: { background: "大流士征发两河、伊朗与印度兵，择平地布刀轮车与前驱象队以待。", process: "前331年十月初会战于尼尼微东高加米拉，马其顿军斜行让开刀轮车通道，骑兵楔入敌王所在。", impact: "波斯军溃散、王东遁被弑，巴比伦与苏萨库藏数千金归马其顿；古代史家记其战果差异极大，须以铭刻与钱币校订。", figures: ["亚历山大三世", "大流士三世", "帕尔梅尼奥", "阿里安所据托勒密回忆"], place: "亚述高加米拉", state: "马其顿与波斯", sources: ["阿里安《亚历山大远征记》第三卷", "巴比伦编年史残篇"], tags: ["会战", "刀轮车", "库藏"] }, related: [] },
  { id: "world--b331--p01", track: "world", year: -331, yearApprox: false, dim: "politics", weight: 5, title: "亚历山大里亚建城", summary: "以方格街、双港与王区开希腊化最大都市。", detail: { background: "亚历山大择法罗斯岛与湖岸之间的地带，舍旧贸易口而新建面向希腊的海港城。", process: "前331年建城，德诺克拉特斯规划：平行街道以公里计，七区字母编号，以海堤连岛成两港。", impact: "托勒密时代人口或逾二十万，成为希腊文学术、粮运与地中海贸易的枢纽，其城格与灯塔为后世港口城市样板。", figures: ["亚历山大三世", "德诺克拉特斯", "托勒密一世"], place: "埃及亚历山大里亚", state: "马其顿治埃及", sources: ["斯特拉波《地理学》第十七卷", "阿里安《亚历山大远征记》第三卷"], tags: ["建城", "方格街", "海港"] }, related: [] },
  { id: "world--b330--p01", track: "world", year: -330, yearApprox: false, dim: "politics", weight: 4, title: "波斯波利斯宫城焚毁", summary: "掠库藏后举火，古记或归因酒后失德或言复仇。", detail: { background: "高加米拉后亚历山大东入波斯故地，王宫库藏以骡马万头运之不尽。", process: "前330年一月占波斯波利斯，掠金银器与王档；数日后宫中起火，波斯王薛西斯焚雅典旧事被举为报复之由。", impact: "大流士三世旋被巴萨维斯弑杀，阿契美尼德王朝终；波斯王室仪制、行省与库藏制度则为马其顿继承。", figures: ["亚历山大三世", "大流士三世", "巴萨维斯"], place: "波斯波利斯", state: "马其顿与波斯", sources: ["阿里安《亚历山大远征记》第三卷", "狄奥多罗斯《历史丛书》第十七卷"], tags: ["焚宫", "库藏", "王朝终"] }, related: [] },
  { id: "world--b327--p01", track: "world", year: -327, yearApprox: false, dim: "politics", weight: 3, title: "中亚征战与索格底亚那联姻", summary: "娶罗克珊娜，筑城扼锡尔河以镇游牧。", detail: { background: "巴克特拉与索格底亚那依险城抵抗，斯皮塔梅内斯以游牧骑兵屡败留守部队。", process: "前327年亚历山大取帕罗帕米萨达与巗山要塞，娶奥克夏特底斯之女罗克珊娜，次年屠攻达利亚斯皮塔梅内斯。", impact: "中亚希腊城邦（绝域亚历山大里亚等）与联姻政治为此后两百年希腊—佛教艺术混合的前因，亦埋下军队离心。", figures: ["亚历山大三世", "罗克珊娜", "斯皮塔梅内斯", "奥克夏特底斯"], place: "索格底亚那、巴克特拉", state: "马其顿王国", sources: ["阿里安《亚历山大远征记》第四卷", "库尔提乌斯《亚历山大史》第七、八卷"], tags: ["联姻", "山要塞", "游牧"] }, related: [] },
  { id: "world--b326--m01", track: "world", year: -326, yearApprox: false, dim: "military", weight: 3, title: "希达斯佩斯河战役", summary: "夜渡雨季大河破波鲁斯战象阵，军心遂止东进。", detail: { background: "波鲁斯控印度河上游，率战象、骑兵与战车拒守，马其顿军首次以象当阵。", process: "前326年雨季于上游偷渡，以步兵分队穿象阵间缺口，象反践踏本阵，波鲁斯被俘后以王礼待。", impact: "军中厌战，拒再渡希帕尼斯河，东征止于旁遮普；其地为后来的孔雀帝国核心，希腊人与印度教义由此相接。", figures: ["亚历山大三世", "波鲁斯", "波吕佩尔孔"], place: "旁遮普希达斯佩斯河", state: "马其顿与印度诸王", sources: ["阿里安《亚历山大远征记》第五卷", "普鲁塔克《亚历山大传》六十节"], tags: ["渡河", "战象", "止兵"] }, related: [] },
  { id: "world--b325--x01", track: "world", year: -325, yearApprox: false, dim: "explore", weight: 4, title: "皮特亚斯环航不列颠", summary: "自马赛北航至极昼之地，记潮汐与北海冰。", detail: { background: "马赛需寻锡路与新商道，亚历山东征同时西方航路几乎无人系统记录。", process: "约前325年皮特亚斯北航，绕不列颠全岛，记夏至日影、六日不夜与图勒及北海凝滞之海。", impact: "《论海》虽佚，其纬度与潮说被喜帕恰斯、普林尼引用，首次把潮汐系于月相，也开北欧地理的希腊记载。", figures: ["皮特亚斯"], place: "不列颠、图勒", state: "马赛殖民航海", sources: ["老普林尼《自然史》第二、四卷引文", "《剑桥古代史》第七卷"], tags: ["环航", "极昼", "潮汐"] }, related: [] },
  { id: "world--b325--x02", track: "world", year: -325, yearApprox: false, dim: "explore", weight: 3, title: "尼亚库斯自印度河口西航", summary: "以百三十船航印度洋归波斯湾，记季风与海岸。", detail: { background: "亚历山大欲通印度与两河的海路，命克里特人尼亚库斯率舰队先行。", process: "前325年自印度河口沿海岸西航，横格德罗西亚沙漠时水绝，陆军分道接济，损失大半后入波斯湾。", impact: "留下首份希腊印度洋航记，其季风与港口记录为托勒密时代红海—印度贸易与后世《厄立特里亚海航行记》的前导。", figures: ["尼亚库斯", "亚历山大三世", "阿耳戈斯（同航者）"], place: "印度河至波斯湾", state: "马其顿王国", sources: ["斯特拉波《地理学》第十五、十六卷引尼亚库斯", "阿里安《印度志》"], tags: ["季风", "航路", "补给"] }, related: [] },
  { id: "world--b324--p01", track: "world", year: -324, yearApprox: false, dim: "politics", weight: 3, title: "苏萨联姻与欧庇斯兵变", summary: "以集体婚姻融合精英，老兵拒东徙而哗变。", detail: { background: "亚历山大欲以马其顿—波斯双轨官僚治国，马其顿老兵则不满东方礼仪与补充兵。", process: "前324年在苏萨行八十余场王与部将的联姻，自娶大流士女；同年欧庇斯老兵罢营五日，杀使者后请罪。", impact: "遣返万余老兵、以三万波斯青年习马其顿阵法，军心与王政的裂痕未合；其融合政策在继业者时代即被抛弃。", figures: ["亚历山大三世", "斯塔提拉", "赫费斯提翁"], place: "苏萨、欧庇斯", state: "马其顿王国", sources: ["阿里安《亚历山大远征记》第七卷", "普鲁塔克《亚历山大传》七十节"], tags: ["联姻", "兵变", "融合"] }, related: [] },
  { id: "world--b323--p01", track: "world", year: -323, yearApprox: false, dim: "politics", weight: 5, title: "亚历山大在巴比伦逝世", summary: "三十二岁病殁，帝国无嗣制而归诸将。", detail: { background: " 方筹阿拉伯与西地中海远征，军中宴饮后连日高热，诸医无策。", process: "前323年六月初在尼布甲尼撒宫去世，年三十二；传其遗命归最强者，遗体后被托勒密劫往埃及。", impact: "继业者二十余年混战使帝国三分，希腊城邦的自由与君政之争、波斯旧地的王朝更替由此重排，是为希腊化时代开端。", figures: ["亚历山大三世", "佩尔狄卡斯", "托勒密", "赫费斯提翁（先逝）"], place: "巴比伦", state: "马其顿王国", sources: ["阿里安《亚历山大远征记》第七、八卷", "巴比伦天文日记所载王卒月日"], tags: ["病逝", "继承", "分裂"] }, related: [] },
  { id: "world--b322--i01", track: "world", year: -322, yearApprox: false, dim: "institution", weight: 3, title: "雅典政制以财产资格重置", summary: "驻军穆尼基亚，公民权限于二千米纳以上。", detail: { background: "拉米亚战争失败，雅典被迫接受马其顿条件，亲马派掌政。", process: "前322年以安提帕特之令改政：取消津贴与几乎全部抽签职，公民名额限五千四百人，卫城旁驻马其顿军。", impact: "古典雅典的直接民主至此终结，流亡者与哲学家（含亚里士多德避居卡尔基斯）散入诸王宫廷，学术中心转向亚历山大里亚。", figures: ["安提帕特", "得墨特里乌斯（法莱鲁人）", "亚里士多德"], place: "雅典", state: "雅典与马其顿", sources: ["亚里士多德《雅典政制》尾声诸章（残）", "普鲁塔克《福基翁传》"], tags: ["财产资格", "驻军", "流亡"] }, related: [] },
  { id: "world--b321--i01", track: "world", year: -321, yearApprox: false, dim: "institution", weight: 3, title: "巴比伦分封协议", summary: "以行省表分配将领，成继业者秩序的起点。", detail: { background: "亚历山大死后佩尔狄卡斯摄政，诸将各据一方而需名分。", process: "前321年在巴比伦重订行省名单：托勒密得埃及，安提帕特与克拉特拉斯得马其顿与希腊，吕辛马库斯得色雷斯。", impact: "此表经狄奥多罗斯摘存，为古代少见的完整官职地理档案；协议未能止战，但确立了以行省为单位的王国蓝图。", figures: ["佩尔狄卡斯", "托勒密一世", "安提帕特", "利西马科斯"], place: "巴比伦", state: "继业者诸将", sources: ["狄奥多罗斯《历史丛书》第八卷末至第十八卷摘要"], tags: ["行省", "分封", "档案"] }, related: [] },
  { id: "world--b312--p01", track: "world", year: -312, yearApprox: false, dim: "politics", weight: 3, title: "塞琉古复有巴比伦与纪元起点", summary: "以少数兵取巴比伦，其纪年通行至数百年后。", detail: { background: "安提柯逐出巴比伦总督，塞琉古借马其顿援兵于前312年夺回。", process: "前312年秋入城，以该年春为纪元之始；其后十年间次第收服东方诸行省至印度河。", impact: "塞琉古纪年用于两河契约、犹太历与阿拉伯文书至六世纪以后，是古代近东沿用最久的纪年体系。", figures: ["塞琉古一世", "安提柯一世"], place: "巴比伦", state: "塞琉古王国", sources: ["巴比伦编年史残篇", "贝罗索斯《巴比伦志》残辑"], tags: ["纪元", "行省", "纪年"] }, related: [] },
  { id: "world--b312--s01", track: "world", year: -312, yearApprox: false, dim: "science", weight: 5, title: "阿庇乌斯大道与阿庇乌斯水道", summary: "监察官一举成两工，罗马自此有石路活水。", detail: { background: "萨莫奈战争需南运兵粮，城内水渠则多在右岸低地，贫民取水不便。", process: "前312年监察官阿庇乌斯·克劳狄乌斯主持：水道约十六公里多为地下，日入约十万立方米；大道初通卡普亚，后延至布林迪西三百余罗马里。", impact: "路—水并举的工程范式奠定意大利基础网络，大道两侧墓葬、里程碑与兵站成为罗马统治的有形骨架。", figures: ["阿庇乌斯·克劳狄乌斯（盲者）"], place: "罗马至卡普亚", state: "罗马共和国", sources: ["李维《自建城以来》第九卷", "弗龙蒂努斯《论水道》五"], tags: ["道路", "水道", "监察官"] }, related: [] },
  { id: "world--b306--m01", track: "world", year: -306, yearApprox: false, dim: "military", weight: 3, title: "塞浦路斯萨拉米斯海战", summary: "德米特里乌斯歼托勒密舰队，获攻城之名。", detail: { background: "托勒密据塞岛以锁东地中海，安提柯遣子德米特里乌斯率船百余救围城。", process: "前306年夏萨拉米斯外海决战，德米特里乌斯以重型撞船破敌，托勒密之弟阵亡，王仅率八船逃。", impact: "此胜使安提柯父子首称王号，其余继业者随之，马其顿王制变成诸王并立的外交体系；攻城器械之名传后世。", figures: ["德米特里乌斯一世", "托勒密一世", "安提柯一世"], place: "塞浦路斯萨拉米斯", state: "安提柯与托勒密", sources: ["狄奥多罗斯《历史丛书》第二卷、二十卷摘要", "普鲁塔克《德米特里乌斯传》"], tags: ["海战", "称王", "攻城器"] }, related: [] },
  { id: "world--b306--c01", track: "world", year: -306, yearApprox: false, dim: "culture", weight: 4, title: "伊壁鸠鲁在雅典建花园", summary: "以原子论与宁静之善收女子奴隶讲学。", detail: { background: "伊壁鸠鲁自米蒂利尼、兰普萨库斯讲学归来，雅典外邦人无政权可入。", process: "前306年购花园开课，书简传物理学与伦理学，门下三派并立，容许妇女与奴隶听课。", impact: "以感觉为准、以去惧神与死为务的学说在罗马共和末期大成，卢克莱修长诗为其唯一完整传本。", figures: ["伊壁鸠鲁", "墨特罗多鲁斯", "卢克莱修（后世传者）"], place: "雅典花园", state: "希腊思想界", sources: ["第欧根尼·拉尔修《名哲言行录》第十卷", "卢克莱修《物性论》第一卷"], tags: ["原子", "宁静", "学派"] }, related: [] },
  { id: "world--b305--p01", track: "world", year: -305, yearApprox: false, dim: "politics", weight: 3, title: "继业者普遍称王", summary: "托勒密、利西马科斯等相继戴王冠并立廷仪。", detail: { background: "安提柯父子前306年先称王，其余诸将以不落后为由跟进。", process: "前305年前后托勒密、塞琉古、利西马科斯、卡山德皆用王号，各设宫廷礼仪、纪年与铸币专权。", impact: "王号、王币与王家祭祀成为希腊化国家认同的核心，城邦自治被纳入朝贡与宫廷庇护体系。", figures: ["托勒密一世", "塞琉古一世", "利西马科斯"], place: "亚历山大里亚、安条克", state: "希腊化诸王国", sources: ["狄奥多罗斯《历史丛书》第二十卷摘要", "保萨尼亚斯《希腊志》卷一纪年段"], tags: ["王号", "廷仪", "铸币"] }, related: [] },
  { id: "world--b304--i01", track: "world", year: -304, yearApprox: false, dim: "institution", weight: 3, title: "弗拉维乌斯公布诉讼历", summary: "书记官刻日发布日与程式，法律知识不再保密。", detail: { background: "诉讼期日与套语由祭司掌握，平民无从起诉，程式错一字即败。", process: "前304年弗拉维乌斯（阿庇乌斯之自由民子）公布日历与诉讼套语并刻于板，后入元老院任市政官。", impact: "法律程序公开可习，职业法学家阶层由此产生，罗马法得以随商业与行省扩张而成为通用技术。", figures: ["格涅乌斯·弗拉维乌斯", "阿庇乌斯·克劳狄乌斯"], place: "罗马广场", state: "罗马共和国", sources: ["李维《自建城以来》第九卷至十卷", "西塞罗《论法律》残篇述及其人"], tags: ["诉讼程式", "公开", "法学家"] }, related: [] },
  { id: "world--b303--p01", track: "world", year: -303, yearApprox: false, dim: "politics", weight: 4, title: "塞琉古—孔雀和约", summary: "以五百年象军换东方三省与通婚之约。", detail: { background: "塞琉古东征至印度河，与旃陀罗笈多在旁遮普相持不下。", process: "约前303年订约：塞方割帕罗帕米萨达、加尔曼西亚等东部地区，孔雀赠战象五百，双方约为婚姻邦。", impact: "孔雀取得大象与西部通道，塞琉古得以象定伊普苏斯之胜；希腊使节驻华氏城，开两大帝国常使往来。", figures: ["塞琉古一世", "旃陀罗笈多", "麦加斯提尼"], place: "旁遮普、华氏城", state: "塞琉古王国与孔雀帝国", sources: ["斯特拉波《地理学》第十五卷", "阿庇安《罗马史·叙利亚战纪》首章"], tags: ["和约", "象军", "使节"] }, related: [] },
  { id: "world--b303--c01", track: "world", year: -303, yearApprox: true, dim: "culture", weight: 4, title: "《印度志》纪华氏城政制", summary: "以七等人身与城监记孔雀官制与风俗。", detail: { background: "麦加斯提尼两度使华氏城，依口述与所见编为书，为希腊论印之最古系统著作。", process: "约前300年前后成书四卷：分居民七级，记城塞、六十人管理委会、王不亲征、无诉讼与借贷等制。", impact: "其说经斯特拉波等摘存，虽有夸饰，仍是印度古代职官、种姓与城市规模最早的旁证，亦被近代学界考辨。", figures: ["麦加斯提尼", "旃陀罗笈多"], place: "华氏城", state: "孔雀帝国", sources: ["斯特拉波《地理学》第十五卷摘引", "阿里安《印度志》摘引"], tags: ["使节纪行", "职官", "风俗"] }, related: [] },
  { id: "world--b301--m01", track: "world", year: -301, yearApprox: false, dim: "military", weight: 4, title: "伊普苏斯战役与帝国三分", summary: "象军封锁敌骑兵，安提柯阵亡，版图再分。", detail: { background: "安提柯欲复统一帝国，利西马科斯、塞琉古与卡山德结盟。", process: "前301年春弗里吉亚伊普苏斯会战，塞琉古自东方运来四百余头象掩其侧翼，德米特里乌斯骑兵被隔于外。", impact: "安提柯八十岁战死，其子仅保马其顿；叙利亚与奇里乞亚归塞琉古，托勒密仍占柯里叙利亚，百年叙利亚战争由此始。", figures: ["塞琉古一世", "利西马科斯", "安提柯一世", "德米特里乌斯一世"], place: "弗里吉亚伊普苏斯", state: "继业者诸王国", sources: ["狄奥多罗斯《历史丛书》第二十卷摘要", "普鲁塔克《德米特里乌斯传》"], tags: ["象军", "会战", "版图"] }, related: [] },
  { id: "world--b300--s01", track: "world", year: -300, yearApprox: true, dim: "science", weight: 5, title: "欧几里得《几何原本》成书", summary: "以五条公设演绎四百六十余命题。", detail: { background: "亚历山大里亚需一套可用于测量、天文与教学的几何教材，旧学派散说无统。", process: "约前300年成十三卷：先设定义与公设，后证四百六十五命题，含不可公度量、正多面体与数论。", impact: "成为公理化方法的典范，译本经阿拉伯文返传拉丁西方，印刷后逾千年为几何教本，十九世纪的非欧几何正是对其第五公设的质疑。", figures: ["欧几里得", "托勒密一世"], place: "亚历山大里亚", state: "托勒密埃及", sources: ["欧几里得《几何原本》普洛克洛斯序说", "《剑桥古代史》第七卷"], tags: ["公理", "几何", "教材"] }, related: [] },
  { id: "world--b300--c01", track: "world", year: -300, yearApprox: true, dim: "culture", weight: 4, title: "芝诺在柱廊创斯多亚学派", summary: "以顺自然而活与世界城邦论讲于彩绘柱廊。", detail: { background: "芝诺自基提翁来雅典，因海难失财而问学，嫌学园讲法繁琐。", process: "约前300年起在集市彩绘柱廊讲学：善恶一体于德性，万物由火与逻各斯循环，智者之城无国界。", impact: "该派由克雷安特斯、克里西波斯建制，传入罗马成西塞罗与马可·奥勒留的伦理底色，其世界主义影响后世自然法。", figures: ["基提翁的芝诺", "克雷安特斯", "克里西波斯"], place: "雅典彩绘柱廊", state: "希腊思想界", sources: ["第欧根尼·拉尔修《名哲言行录》第七卷", "《剑桥古代史》第七卷"], tags: ["斯多亚", "逻各斯", "世界主义"] }, related: [] },
  { id: "world--b300--i01", track: "world", year: -300, yearApprox: true, dim: "institution", weight: 5, title: "托勒密设缪斯宫与大王图书馆", summary: "以王室俸养学者，征船收书抄藏。", detail: { background: "新建都城需文化机构以配王权，雅典学园与吕克昂的藏书传统可资摹仿。", process: "约前300年代至前290年代设缪斯宫：王室供养祭司与讲士，入港船只之书必取抄，抄本留而还其原本。", impact: "抄校、编目与语文学由此成专门之学，希伯来圣经译希腊文、《书目表》皆出其下，为古代最大文本中心。", figures: ["托勒密一世", "德米特里乌斯（法莱鲁）", "泽诺多图斯"], place: "亚历山大里亚缪斯宫", state: "托勒密埃及", sources: ["斯特拉波《地理学》第十七卷", "《剑桥古代史》第七卷"], tags: ["图书馆", "校勘", "王室供养"] }, related: [] },
  { id: "world--b300--s02", track: "world", year: -300, yearApprox: true, dim: "science", weight: 3, title: "亚历山大里亚的人体解剖", summary: "王室许解尸，医家第一次以人体定神经与脉搏。", detail: { background: "托勒密一世、二世在亚历山大里亚厚养医者，据古代记述王室容许取死囚之尸开视，医学遂得舍动物而据人体立说。", process: "赫罗菲卢斯分辨脑室与神经，谓神经有感觉、运动二司，以瞳孔为视路之入，定十二指肠之名，并把脉搏的数目与张力列为诊候；埃拉西斯特拉图斯解剖血管与心，推心为血脉之枢，以脑为感觉运动之本。", impact: "人体解剖之法自此入医门，盖伦仍引其二家之说；后世阿拉伯与拉丁医学的神经、脉搏观念皆循此线，近代解剖学兴起时亦以其名指认器官。", figures: ["赫罗菲卢斯", "埃拉西斯特拉图斯", "托勒密一世"], place: "埃及亚历山大里亚", state: "托勒密埃及", sources: ["《剑桥古代史》第七卷论希腊化医学", "老普林尼《自然史》第二十九章论解剖之始"], tags: ["解剖", "神经", "诊脉"] }, related: [] },
  { id: "world--b295--m01", track: "world", year: -295, yearApprox: false, dim: "military", weight: 3, title: "森提努姆战役", summary: "破萨莫奈—高卢十邦联军，夺中意大利。", detail: { background: "萨莫奈人联合埃特鲁里亚、翁布里亚与塞诺内斯高卢，凑起约十万之众抗罗马。", process: "前295年执政官德奇乌斯与法比乌斯会战于森提努姆，一方以自请神咒的突击扰乱敌阵，另一方坚守后合击。", impact: "罗马及其拉丁—坎帕尼亚同盟取得亚平宁中段，殖民网络向北延伸，为对皮洛士与迦太基的兵源奠基。", figures: ["普布利乌斯·德奇乌斯·穆尔凯", "昆图斯·法比乌斯·鲁利阿努斯"], place: "翁布里亚森提努姆", state: "罗马共和国与意大利同盟", sources: ["李维《自建城以来》第十卷", "《剑桥古代史》第七卷"], tags: ["会战", "同盟", "殖民"] }, related: [] },
  { id: "world--b287--i01", track: "world", year: -287, yearApprox: false, dim: "institution", weight: 4, title: "霍尔腾西亚法", summary: "平民会议决议无须元老院认可即拘束全民。", detail: { background: "债务与土地纠纷再起，平民依例退至雅尼库鲁姆山，贵族在汉诺之战后兵源紧张。", process: "前287年独裁官霍尔腾西亚法成，平民会议所通过的决议对全体罗马人民有法效力。", impact: "等级斗争以立法形式收尾，此后罗马多以平民决议推行财政、司法与公民权立法，贵族转而以金钱与庇护网操控表决。", figures: ["昆图斯·霍尔腾西乌斯"], place: "罗马", state: "罗马共和国", sources: ["李维《自建城以来》摘要卷十一", "西塞罗《论共和国》残篇引"], tags: ["平民决议", "立法", "等级"] }, related: [] },
  { id: "world--b286--i01", track: "world", year: -286, yearApprox: false, dim: "institution", weight: 3, title: "阿奎利亚法与损害赔偿责任", summary: "以三十日最高价计被杀奴隶与牲畜之赔。", detail: { background: "布匿战前后田畜被毁、奴隶被害之讼增多，旧十二表估价过轻。", process: "前286年平民决议第二章定：以非法杀死他人奴隶或四足群畜者，按该物前三十日内最高值赔偿。", impact: "把赔偿与客观市价、因果关系捆绑，成为罗马法学家长期注释的核心条文，也是近代侵权法的古典源头。", figures: ["马尼乌斯·阿奎利乌斯"], place: "罗马", state: "罗马共和国", sources: ["优士丁尼《法学阶梯》论阿奎利亚法", "盖尤斯《法学阶梯》第三卷"], tags: ["侵权", "赔偿", "法条"] }, related: [] },
  { id: "world--b285--c01", track: "world", year: -285, yearApprox: true, dim: "culture", weight: 3, title: "七十子译本开始流通", summary: "五经由希伯来文转通用希腊语，流散犹太用之。", detail: { background: "亚历山大里亚的犹太侨民日久不习希伯来文，礼拜与律法皆需希腊文本；托勒密二世欲取其律书入王宫图书馆。", process: "约前285年起摩西五经先成译，其后先知书与文集陆续补入，译语用市通行希腊语，神名以“主”之通称对写；后世因相传七十二老同译而名其本。", impact: "此本成为流散犹太人与初世纪基督教会所用经典，使希腊哲学术语第一次承载近东宗教概念，并与马所拉文本互为校勘之据。", figures: ["托勒密二世费拉德尔福斯", "亚历山大里亚犹太译经群"], place: "埃及亚历山大里亚", state: "托勒密埃及", sources: ["《阿里斯忒阿斯致菲洛克拉特斯书》", "七十子译本校勘本序述"], tags: ["译经", "流散", "希伯来"] }, related: [] },
  { id: "world--b282--p01", track: "world", year: -282, yearApprox: false, dim: "politics", weight: 3, title: "帕加马财库独立", summary: "以九千金库附丽塞琉古而自立，后成书与币都。", detail: { background: "利西马科斯战败前，其财库官菲莱塔埃罗斯据城堡与金银自守。", process: "前282年菲莱塔埃罗斯以帕加马城堡与约九千塔兰同库金附于托勒密·克劳诺斯，旋实际独立，养雇兵守隘。", impact: "阿塔罗斯王朝以财富买得外交空间，建图书馆并以羊皮卷代莎草纸，其遗赠罗马（前133）改变了东地中海格局。", figures: ["菲莱塔埃罗斯", "利西马科斯", "托勒密·克劳诺斯"], place: "米西亚帕加马", state: "帕加马邦", sources: ["斯特拉波《地理学》第十三卷", "保萨尼亚斯《希腊志》第七卷"], tags: ["财库", "王朝", "羊皮卷"] }, related: [] },
  { id: "world--b281--m01", track: "world", year: -281, yearApprox: false, dim: "military", weight: 3, title: "库鲁佩迪昂战役", summary: "塞琉古杀利西马科斯，旋遭刺杀得马其顿。", detail: { background: "利西马科斯杀妻、诛将后众叛，托勒密·克劳诺斯投塞琉古求援。", process: "前281年在小亚库鲁佩迪昂会战，塞琉古以象与骑兵胜且年逾八旬；翌年他在吕辛马凯亚被克劳诺斯所弑。", impact: "两代继业者同年出局，马其顿陷入二十余年无统王，高卢人随即涌入；塞琉古成为西亚唯一的强王国。", figures: ["塞琉古一世", "利西马科斯", "托勒密·克劳诺斯"], place: "小亚库鲁佩迪昂", state: "塞琉古王国", sources: ["查士丁《腓力史》摘要卷十七", "保萨尼亚斯《希腊志》卷一"], tags: ["会战", "弑主", "王位空"] }, related: [] },
  { id: "world--b280--m01", track: "world", year: -280, yearApprox: false, dim: "military", weight: 3, title: "皮洛士渡海入意大利", summary: "以伊壁鲁斯军与二十象援塔兰托，初胜赫拉克利亚。", detail: { background: "塔兰托惧罗马设省，雇希腊化名王皮洛士；其舅之女为王后，野心及西西里。", process: "前280年夏渡亚得里亚海，携二万余步兵、二千余骑与二十头象；秋于赫拉克利亚河滨以象冲溃罗马军团。", impact: "罗马首次遭遇希腊式合成军与战象，和谈因阿庇乌斯元老演说而止；战争延续五年，双方皆以消耗为名。", figures: ["皮洛士", "基涅阿斯", "阿庇乌斯·克劳狄乌斯"], place: "大希腊赫拉克利亚", state: "伊庇鲁斯与罗马", sources: ["普鲁塔克《皮洛士传》十七至二十一节", "弗洛鲁斯《罗马史纲》卷一"], tags: ["战象", "雇佣王", "和谈"] }, related: [] },
  { id: "world--b280--a01", track: "world", year: -280, yearApprox: true, dim: "art", weight: 3, title: "罗得岛巨像落成", summary: "以战资铸日神铜像，高十丈立港前。", detail: { background: "前305至前304年德米特里乌斯围罗德不克，岛人以弃置攻城器熔铜酬神。", process: "约前292至前280年哈革斯亚历山德鲁斯造赫利俄斯铜像，高约三十米，内以石垒与铁架分节铸铜皮。", impact: "列为古代七大奇迹之一，五十六年后为地震所毁，残件仍为游客胜迹，其铸造分节法见于后世大铜像工程。", figures: ["哈革斯的亚历山德鲁斯", "罗德拉各斯（出资者）"], place: "罗得岛港", state: "罗得岛", sources: ["老普林尼《自然史》第三十四卷", "《君士坦丁七世论节》残辑"], tags: ["青铜", "奇迹", "地震"] }, related: [] },
  { id: "world--b280--s01", track: "world", year: -280, yearApprox: true, dim: "science", weight: 3, title: "阿里斯塔克斯提出地动说", summary: "以月相之角推日远且大，令地球绕日自转。", detail: { background: "欧多克索斯的同心球与亚里士多德的地静宇宙为通行之说，然行星视动繁复，算家欲求简便之解。", process: "阿里斯塔克斯据上弦月与日月直角之差（取二分一之度）推日距倍于月距，又由同视径推日体远大于地，遂定地自转并绕日行；其书《论日月大小与距离》存，其宇宙说赖他人转述。", impact: "古代希腊唯一明载的地动说，塞琉古曾为之辩，芝诺则斥其不敬经典；千八百年后哥白尼自陈古人先有是说。", figures: ["萨摩斯的阿里斯塔克斯", "幼发拉底的塞琉古"], place: "萨摩斯与亚历山大里亚", state: "希腊化世界", sources: ["阿基米德《数沙者》序言转述", "普鲁塔克《露库鲁斯传》论地动"], tags: ["日心", "测距", "天文"] }, related: [] },
  { id: "world--b279--m01", track: "world", year: -279, yearApprox: false, dim: "military", weight: 3, title: "高卢人攻德尔斐", summary: "山口暴雪与崩岩被记作神助，掠夺军受创东去。", detail: { background: "前281年后马其顿王位争夺，高卢大部落约十万越色雷斯入希腊，求金与地。", process: "前279年秋至冬围德尔斐，希腊诸邦联军守隘，风雪、山崩与夜袭传说并起，掠军病疲后北撤。", impact: "圣域声望大涨，同盟献金与节会以拒高卢为题材；残部越赫勒斯滂入小亚，定居为加拉太人。", figures: ["高卢首领波尔基俄斯", "希腊守隘联军", "科律岱（记其役）"], place: "德尔斐", state: "希腊诸邦与高卢诸部", sources: ["保萨尼亚斯《希腊志》卷十", "查士丁《腓力史》摘要卷二十四"], tags: ["圣域", "风雪", "迁徙"] }, related: [] },
  { id: "world--b278--p01", track: "world", year: -278, yearApprox: false, dim: "politics", weight: 3, title: "加拉太人定居安纳托利亚中部", summary: "受雇渡海而自占高原，诸邦向其纳金求安。", detail: { background: "比提尼亚与某些城邦雇高卢兵内斗，三部落约万人于前278年前后渡入小亚。", process: "约前278至前275年据弗里吉亚北部高原，称加拉太，以托利斯托波伊等三部为骨架，向邻邦索贡。", impact: "半岛中部出现无城邦的部族政体，帕加马以战胜者像（垂死的高卢人）自誉，罗马东进亦以此为借口之一。", figures: ["列昂诺里乌斯", "罗里乌斯", "比提尼亚王齐莱斯"], place: "安纳托利亚中部", state: "加拉太诸部", sources: ["斯特拉波《地理学》第十二卷", "波利比乌斯《历史》残篇论加拉太高卢人"], tags: ["迁徙", "部族", "纳贡"] }, related: [] },
  { id: "world--b275--m01", track: "world", year: -275, yearApprox: false, dim: "military", weight: 3, title: "贝内文图姆之战与皮洛士退兵", summary: "以火矢与伏兵惊象反阵，罗马夺其营地。", detail: { background: "皮洛士自西西里返，意在坎帕尼亚与拉丁姆之间取利；罗马军由执政官库里乌斯统率。", process: "前275年秋在贝内文图姆附近林地设伏，以三支投火矢队扰象，象背冲己阵，王军溃，营寨尽失。", impact: "皮洛士弃意大利，据古代记述其凯旋式上首次示战象；罗马自此独控南意大利，把大希腊诸城编入同盟。", figures: ["马尼乌斯·库里乌斯·登塔图斯", "皮洛士"], place: "萨莫尼乌姆贝内文图姆", state: "罗马共和国", sources: ["李维《自建城以来》摘要卷十三", "弗洛鲁斯《罗马史纲》卷一"], tags: ["伏兵", "战象", "凯旋"] }, related: [] },
  { id: "world--b272--m01", track: "world", year: -272, yearApprox: false, dim: "military", weight: 3, title: "塔兰托陷落与南意归罗马", summary: "趁祭城宴开门，罗马驻军与条约并行。", detail: { background: "皮洛士返希腊后塔兰托孤立，城内主和与主战两派相攻。", process: "前272年罗马军借宴饮之乱入卫城，全城降；约定制：拆部分城墙、献舰队、纳卫戍并从征。", impact: "罗马完成对大希腊的整合，取得海船与港口；十三年后与迦太基冲突即在此岸展开，意大利同盟体系成型。", figures: ["卢基乌斯·列皮杜斯（使节）", "法比里基乌斯"], place: "塔兰托", state: "罗马共和国与塔兰托", sources: ["李维《自建城以来》摘要卷十三", "普鲁塔克《皮洛士传》十七至十八节"], tags: ["开门", "条约", "海权"] }, related: [] },
  { id: "world--b268--p01", track: "world", year: -268, yearApprox: true, dim: "politics", weight: 4, title: "阿育王继位", summary: "以血战得华氏城，后为孔雀第三王。", detail: { background: "宾头娑罗诸子争立，传其杀多兄弟而得位，佛教与耆那教文献所记互异。", process: "约前268年登位于华氏城，前269至前268年间行灌顶；其朝统治范围含除极南外的大半南亚。", impact: "在位约三十六年，其治下王朝由征伐转奉法，成为印度史上第一个把政令刻石遍示诸语言的君主。", figures: ["阿育王", "宾头娑罗", "诸兄弟"], place: "华氏城", state: "孔雀帝国", sources: ["《阿育王传》分门译述", "《摩诃僧祇律》校勘与法敕自述"], tags: ["继位", "灌顶", "王朝"] }, related: [] },
  { id: "world--b264--i01", track: "world", year: -264, yearApprox: false, dim: "institution", weight: 3, title: "罗马首场角斗表演", summary: "为丧父贵族以三对剑斗殉葬，成竞技先例。", detail: { background: "坎帕尼亚有以处决囚徒随葬的旧俗，罗马贵族的葬礼演说与竞技渐成政治资本。", process: "前264年马尔基乌斯兄弟为父丧在牛肉市场办三对奴俘角斗，系罗马文献所记最早的角斗表演。", impact: "丧仪竞技转为常设公共表演，四百余年后成斗兽场制度；其兵源训练与政治笼络功能为共和末期至帝制所倚。", figures: ["马尔库斯·尤尼乌斯·布鲁图（丧主二子）"], place: "罗马牛肉市场", state: "罗马共和国", sources: ["老普林尼《自然史》第七卷", "李维《自建城以来》摘要并角斗源流考述"], tags: ["角斗", "丧仪", "公共表演"] }, related: [] },
  { id: "world--b264--m01", track: "world", year: -264, yearApprox: false, dim: "military", weight: 5, title: "第一次布匿战争爆发", summary: "为墨萨纳雇兵之争，罗马迦太基开战二十三年。", detail: { background: "西西里的墨萨纳被意大利雇佣兵占据，先后求援于迦太基与罗马；元老院以盟友为壑。", process: "前264年罗马军渡海峡逐迦太基戍兵，围攻叙拉古，宣战方为两强，战场初在西西里与近海。", impact: "罗马由陆权邦被迫建海军并吞海岛，双方在此后二十三年中兵员与船损皆空前，西地中海秩序自此改属罗马。", figures: ["马尔凯路斯与瓦勒里乌斯（首批将领）", "阿伽托克勒亚旧部", "耶罗二世"], place: "西西里墨萨纳", state: "罗马共和国与迦太基", sources: ["波利比乌斯《历史》第一卷", "狄奥多罗斯《历史丛书》摘要卷二十三"], tags: ["宣战", "雇佣兵", "海权"] }, related: [] },
  { id: "world--b261--m01", track: "world", year: -261, yearApprox: false, dim: "military", weight: 5, title: "羯陵伽之战与阿育王转向", summary: "海陆破十万众后，以法代征成为国策。", detail: { background: "羯陵伽居恒河—戈达瓦里通道，拒不入孔雀版图，前此已累次征讨未服。", process: "约前261年大举水陆并进，其十三号法敕自陈死者十五万、被徙倍之，嗣后以法代兵。", impact: "此役成为古代最罕见的君主自记战罪并公开改弦的个案；其不征服的政策直接塑造东南亚法传说的远播。", figures: ["阿育王", "羯陵伽诸王公"], place: "羯陵伽（今奥里萨）", state: "孔雀帝国", sources: ["阿育王十三号岩刻法敕", "《阿育王传》战羯陵伽段"], tags: ["征伐", "自记", "转向"] }, related: [] },
  { id: "world--b260--m01", track: "world", year: -260, yearApprox: false, dim: "military", weight: 3, title: "米莱海战与接舷桥", summary: "以吊桥改海战为陆战，罗马获首胜与纪念柱。", detail: { background: "罗马船不善航且无经验，舰长会议决取坎帕尼亚式设计并以机械补其短。", process: "前260年执政官杜伊利乌斯在米莱外海以船首约十米高的接舷吊桥落敌船甲板，步兵过桥夺船。", impact: "歼迦太基船百余艘，罗马立船首柱纪功；海战从此不再取决于撞术训练，其战术为后世水战机械学的起点。", figures: ["盖乌斯·杜伊利乌斯"], place: "西西里米莱", state: "罗马共和国", sources: ["波利比乌斯《历史》第一卷二十一至二十三章", "杜伊利乌斯纪念柱铭刻残辑"], tags: ["海战", "机械", "纪念柱"] }, related: [] },
  { id: "world--b256--m01", track: "world", year: -256, yearApprox: false, dim: "military", weight: 3, title: "埃克诺穆斯海战与雷古路斯渡非洲", summary: "三百三十船破护航，罗马首次登陆利比亚。", detail: { background: "罗马欲逼迦太基本土议和，组建约三百三十艘船的最大远征舰队。", process: "前256年七月在埃克诺穆斯角会战分四队包抄破敌护航，随后登陆，取克利皮亚并进逼都城。", impact: "和谈条件过苛致迦太基死战，翌年雷古路斯被俘；此役双方海员损失逾十万，为古代海战最惨记录之一。", figures: ["马尔库斯·阿提利乌斯·雷古路斯", "卢基乌斯·曼利乌斯"], place: "利比亚克利皮亚", state: "罗马共和国与迦太基", sources: ["波利比乌斯《历史》第一卷二十五至三十一章", "狄奥多罗斯《历史丛书》摘要卷十六"], tags: ["登陆", "和谈", "船损"] }, related: [] },
  { id: "world--b250--i01", track: "world", year: -250, yearApprox: true, dim: "institution", weight: 5, title: "阿育王岩刻法敕", summary: "以多种文字刻二十余处，宣法、戒杀与设官。", detail: { background: "帝国语言与习俗差异极大，普通会议与使节不足传达王令，遂以刻石代宣。", process: "约前260年代起在今印度、尼泊尔、巴基斯坦二十余处与阿富汗坎大哈刻敕，用婆罗米、佉卢、希腊与亚兰文。", impact: "内容含禁屠宰数日、为人与畜设医、任法官、容诸派；其石刻传统为印度碑铭制度之始，亦使阿育王为近代首先释读的君主。", figures: ["阿育王", "法官（法之大臣）"], place: "达尔奥里、曼塞赫拉、坎大哈等", state: "孔雀帝国", sources: ["阿育王岩刻法敕校释本（第一至十四号）", "《剑桥印度史》第一卷"], tags: ["碑铭", "多语", "戒杀"] }, related: [] },
  { id: "world--b250--c01", track: "world", year: -250, yearApprox: true, dim: "culture", weight: 4, title: "华氏城第三次结集与遣使", summary: "以目犍连子帝须清僧团，九路传法外及四王。", detail: { background: "外道混入僧团受供，阿育王命大臣甄别，传曾因待僧过薄而下狱吏。", process: "约前250年结集，诵出律与论事，编《论事》破异说；遣使九路：僧伽罗、健馱罗、喜马拉雅、希腊人诸王等。", impact: "佛教由恒河流域邦际宗教转为跨帝国传播；其使团所至与法敕地名互证，为南亚与东南亚信史的最早锚点。", figures: ["目犍连子帝须", "阿育王", "摩哂陀"], place: "华氏城", state: "孔雀帝国", sources: ["《善见律毗婆沙》传译本", "《大史》第三章校释"], tags: ["结集", "遣使", "律藏"] }, related: [] },
  { id: "world--b250--s01", track: "world", year: -250, yearApprox: true, dim: "science", weight: 5, title: "阿基米德立静力学与穷竭法", summary: "证杠杆与浮体之律，以不可分量开积分之端。", detail: { background: "叙拉古希耶罗二世的宫廷需器物与工程之判，阿基米德受欧几里得学派训练，欲以几何证明施于重力与浮沉。", process: "《论平面图形的平衡》以公设推出杠杆之率，《论浮体》定排液等重之律并论浮体之稳态，《方法》以无穷不可分量比较面积与体积，求抛物线弓形与球、锥之比；《数沙者》造大数记法至亿亿级。", impact: "静力学与水静力学由此立学，穷竭与不可分量之法为十七世纪积分之先声；其文本经阿拉伯译本与拉丁印本传入近代欧洲。", figures: ["叙拉古的阿基米德", "多拉松", "希耶罗二世"], place: "叙拉古与亚历山大里亚", state: "叙拉古王国", sources: ["阿基米德传世七篇希文本校勘", "《剑桥古代史》第七卷论希腊化数理"], tags: ["杠杆", "浮体", "穷竭法"] }, related: [] },
  { id: "world--b249--m01", track: "world", year: -249, yearApprox: false, dim: "military", weight: 3, title: "德雷帕纳海战", summary: "罗马舰队冒雾夜袭失利，损失近百船。", detail: { background: "迦太基以哈米尔卡守赫拉克莱亚，罗马欲以奇袭夺港。", process: "前249年执政官普尔喀雾晨进逼，先锋过深，主力失序；敌乘其散，沉或夺船近百，仅一队因锚索断得免。", impact: "罗马海运与兵源受重创，此后七年不敢大举；史传其以圣鸡不食而投鸡入海的典故，反映军占与政治的紧张。", figures: ["普布利乌斯·克劳狄乌斯·普尔喀", "哈米尔卡·巴卡"], place: "西西里德雷帕纳", state: "罗马共和国与迦太基", sources: ["波利比乌斯《历史》第一卷二十四章", "西塞罗《论神性》引圣鸡事"], tags: ["夜袭", "船损", "军占"] }, related: [] },
  { id: "world--b247--c01", track: "world", year: -247, yearApprox: false, dim: "culture", weight: 3, title: "佛牙入斯里兰卡传说", summary: "以王室护送的舍利与圣树立岛国正统。", detail: { background: "摩哂陀传法后，其妹僧伽蜜多携菩提树枝分植于阿努拉德普勒。", process: "约前第三世纪中叶，传说王子与王女携佛牙自羯陵伽入岛，藏于发髻；大寺派逐代记其护持。", impact: "舍利与圣树成为斯里兰卡王权与僧团相互证成的中心符号，其节庆与寺产制度沿袭至今。", figures: ["摩哂陀", "僧伽蜜多", "天爱帝须王"], place: "阿努拉德普勒", state: "斯里兰卡与大寺派", sources: ["《大史》第十五至十九章", "《法界史灯》校释本"], tags: ["舍利", "圣树", "正统"] }, related: [] },
  { id: "world--b245--s01", track: "world", year: -245, yearApprox: true, dim: "science", weight: 4, title: "卡利马科斯编《书目表》", summary: "以一百二十卷为藏书分科立目并标真伪。", detail: { background: "缪斯宫藏书增至数万卷，复本、伪作与异文并陈，学者检索无门。", process: "约前245年前后卡利马科斯编《书目表》：按诗、演说、哲学、医学等分科，记作者、篇名与卷数并注考辨。", impact: "首创以著者—篇题为中心的学术书目与校勘符号，此后罗马与拜占庭的藏书目录、乃至近代学术索引皆循其例。", figures: ["卡利马科斯", "托勒密三世"], place: "亚历山大里亚", state: "托勒密埃及", sources: ["卡利马科斯《书目表》残辑", "普鲁塔克《托勒密诸王》残篇说部"], tags: ["书目", "校勘", "藏书"] }, related: [] },
  { id: "world--b241--m01", track: "world", year: -241, yearApprox: false, dim: "military", weight: 5, title: "埃加特斯群岛海战与西西里和议", summary: "断桨去塔以轻速破敌，迦太基弃西西里。", detail: { background: "罗马以公民募款新建两百余船，欲一举断迦太基的护航；敌船超载运粮。", process: "前241年三月在埃加特斯群岛西面会战，罗马舰去舰桥与塔楼以求速，敌船几尽被沉或获。", impact: "迦太基约十年赔三千二百塔兰同并撤西西里，罗马置为首个行省；其财政与海军经验直接引出撒丁尼亚之夺。", figures: ["盖乌斯·卢塔提乌斯·卡图鲁斯", "哈米尔卡之子汉诺（将领）"], place: "埃加特斯群岛", state: "罗马共和国与迦太基", sources: ["波利比乌斯《历史》第一卷六十二至六十四章", "李维《自建城以来》摘要卷十七"], tags: ["海战", "赔金", "行省"] }, related: [] },
  { id: "world--b240--s01", track: "world", year: -240, yearApprox: true, dim: "science", weight: 4, title: "埃拉托斯特尼测地球周长", summary: "以两城日影差算地周，误差不逾一成。", detail: { background: "亚历山大里亚与赛伊尼夏至日影不同，前者立竿有影，后者井底无景。", process: "约前240年测两地日影角差为周天之一五十分，以五百斯塔德之路程推得二十五万斯塔德（后定为约四十六万二百五十）。", impact: "首次以几何与实测结合给出可复算的地球尺寸，其《地理学》以经纬线分带法为后世制图学基础。", figures: ["埃拉托斯特尼", "克勒斯特法斯（前人所测黄赤交角）"], place: "亚历山大里亚、赛伊尼", state: "托勒密埃及", sources: ["克莱奥米季斯《天球论》第六卷所载其法", "斯特拉波《地理学》第一卷评论"], tags: ["实测", "地周", "制图"] }, related: [] },
  { id: "world--b238--p01", track: "world", year: -238, yearApprox: true, dim: "politics", weight: 4, title: "帕尼人据帕夫提亚自立", summary: "阿尔萨息乘塞琉古内乱起王朝，延续五百年。", detail: { background: "塞琉古二世东方战事失利，帕夫提亚与希尔卡尼亚总督安德拉戈拉斯先自立，游牧帕尼人被月氏压力西迁。", process: "约前238年阿尔萨息一世的部族据帕夫提亚，都于尼萨，以骑射与部落联盟立国，后世称阿尔萨息王朝。", impact: "帕提亚此后百年间取伊朗、两河，成为罗马东方唯一劲敌；其封建式王廷与双语钱币深刻影响中亚与犍陀罗。", figures: ["阿尔萨息一世", "安德拉戈拉斯", "塞琉古二世"], place: "帕夫提亚、尼萨", state: "帕提亚", sources: ["斯特拉波《地理学》第十一卷", "查士丁《腓力史》摘要卷四十一"], tags: ["王朝", "游牧", "独立"] }, related: [] },
  { id: "world--b237--m01", track: "world", year: -237, yearApprox: false, dim: "military", weight: 3, title: "巴卡家族渡海取西班牙", summary: "哈米尔卡以残兵征服部落，建银矿与兵源基地。", detail: { background: "佣兵战争后迦太基失撒丁尼亚，主战派需新财源偿罗马赔金并养兵。", process: "前237年哈米尔卡率军渡海峡，历年征讨塔尔泰索斯诸部，联姻地方豪族，据矿区与港口。", impact: "西班牙银矿与雇佣兵使巴卡家族成半独立势力，其子汉尼拔在西班牙长成，二十年后进攻意大利。", figures: ["哈米尔卡·巴卡", "汉尼拔（幼随军）", "哈斯德鲁巴"], place: "伊比利亚半岛南部", state: "迦太基与巴卡家族", sources: ["波利比乌斯《历史》第二卷", "李维《自建城以来》第二十一卷"], tags: ["银矿", "征服", "兵源"] }, related: [] },
  { id: "world--b229--p01", track: "world", year: -229, yearApprox: false, dim: "politics", weight: 3, title: "第一次伊利里亚战争", summary: "为禁海盗渡海用兵，罗马首次介入巴尔干。", detail: { background: "伊利里亚女王特乌塔死后，德米特里乌斯以船劫意大利与希腊商路，使节被杀。", process: "前229年罗马遣两使团约两百船渡海，取法罗斯与阿波罗尼亚，德米特里乌斯亡奔马其顿。", impact: "罗马在亚得里亚海东岸设保护地与贡赋区，被希腊诸邦书写作解放者请入；此后二十年内三度对马其顿用兵。", figures: ["德米特里乌斯（法罗斯）", "罗马使节科尔温"], place: "伊利里亚、法罗斯岛", state: "罗马共和国", sources: ["阿庇安《罗马史·伊利里亚战纪》首章", "狄奥多罗斯《历史丛书》摘要卷二十六"], tags: ["海盗", "渡海", "保护地"] }, related: [] },
  { id: "world--b227--i01", track: "world", year: -227, yearApprox: false, dim: "institution", weight: 3, title: "撒丁尼亚与科西嘉设省", summary: "以行省与十分之一谷物税统治海岛。", detail: { background: "迦太基佣兵据撒丁尼亚求降，罗马乘其内乱取岛，和约中逼其放弃并另付赔金。", process: "前227年罗马置治撒丁尼亚与科西嘉的裁判官二员，岛上行谷与畜牧之征，山区部族屡叛。", impact: "与西西里并列为二岛行省，确立以总督、包税人与固定贡率治海外领地的成例，罗马粮源与铅银得补。", figures: ["罗马裁判官（首任不可考）"], place: "撒丁尼亚", state: "罗马共和国", sources: ["李维《自建城以来》摘要卷二十", "波利比乌斯《历史》第一卷残段论撒丁事"], tags: ["行省", "谷物税", "海岛"] }, related: [] },
  { id: "world--b225--m01", track: "world", year: -225, yearApprox: false, dim: "military", weight: 3, title: "塔拉蒙战役", summary: "两执政官合击灭塞诺内斯，波河平原门户开。", detail: { background: "山南高卢诸部围阿雷提乌姆，罗马新征两军团并联合拉丁同盟军北上。", process: "前225年秋于塔拉蒙海湾两侧会战，一军正面拒敌，另一军自背后登山合击，据载高卢战死者过半。", impact: "塞诺内斯几乎被灭族，其地被宣布公有并放牧，罗马由此可筑道殖民至波河，百年后设山南高卢行省。", figures: ["盖乌斯·阿特利乌斯·雷古路斯", "卢基乌斯·埃米利乌斯·帕普斯"], place: "翁布里亚塔拉蒙", state: "罗马共和国与高卢诸部", sources: ["波利比乌斯《历史》第二卷二十至三十一章", "李维《自建城以来》摘要卷二十"], tags: ["合击", "灭族", "殖民"] }, related: [] },
  { id: "world--b220--s01", track: "world", year: -220, yearApprox: false, dim: "science", weight: 3, title: "弗拉米尼乌斯大道与波河殖民", summary: "以石道连亚得里亚与波河，设二城为桥头。", detail: { background: "塔拉蒙战后需向波河移民与运兵，旧道只到卡普亚。", process: "前220年监察官弗拉米尼乌斯筑道自阿里提乌姆至波河约一百六十罗马里；前218年设克雷莫纳与皮琴提亚二殖民城。", impact: "道路与殖民城配套，使波河平原成为可持久动员的兵源与粮区；二城在汉尼拔战争中成为必争据点。", figures: ["盖乌斯·弗拉米尼乌斯（监察官）"], place: "罗马至波河", state: "罗马共和国", sources: ["李维《自建城以来》第二十一卷", "弗龙蒂努斯《论殖民》摘述"], tags: ["道路", "殖民城", "兵源"] }, related: [] },
  { id: "world--b218--m01", track: "world", year: -218, yearApprox: false, dim: "military", weight: 5, title: "汉尼拔越阿尔卑斯", summary: "以象队逾山入高卢，初胜特雷比亚河。", detail: { background: "汉尼拔围萨贡图姆引罗马宣战，决计弃海路而由陆越山攻意大利背后。", process: "前218年春率约五万步兵逾比利牛斯，秋越阿尔卑斯，行军九日，山民袭与寒冷失员过半；冬于特雷比亚河以伏兵胜两执政官军。", impact: "高卢诸部倒向迦太基，罗马在波河以南失据；越山之战成为古代机动战的典范，亦令罗马军事思维转向持久。", figures: ["汉尼拔", "普布利乌斯·科尔涅利乌斯（执政官）", "塞姆普罗尼乌斯"], place: "阿尔卑斯山、特雷比亚河", state: "迦太基与罗马", sources: ["波利比乌斯《历史》第三卷", "李维《自建城以来》第二十一卷"], tags: ["逾山", "战象", "伏兵"] }, related: [] },
  { id: "world--b217--m01", track: "world", year: -217, yearApprox: false, dim: "military", weight: 3, title: "特拉西梅诺湖伏击", summary: "借晨雾依湖设伏，执政官与一万五千军团没。", detail: { background: "汉尼拔越亚平宁入伊特鲁里亚，择湖岸窄道诱敌，探知弗拉米尼乌斯急于求战。", process: "前217年六月晨雾中步兵伏于北坡，高卢与伊比利亚兵堵路口，信号一齐四面下击，罗马军大半溺湖。", impact: "罗马以法比乌斯任独裁官，行避战耗敌之术；同盟者动摇，卡普亚等意大利城暗通迦太基。", figures: ["盖乌斯·弗拉米尼乌斯（阵亡执政官）", "汉尼拔", "马哈巴尔"], place: "伊特鲁里亚特拉西梅诺湖", state: "罗马共和国与迦太基", sources: ["波利比乌斯《历史》第三卷七十七至八十四章", "李维《自建城以来》第二十二卷"], tags: ["伏击", "晨雾", "独裁官"] }, related: [] },
  { id: "world--b216--m01", track: "world", year: -216, yearApprox: false, dim: "military", weight: 5, title: "坎尼会战", summary: "两翼合围歼八万罗马军，成包围歼灭范本。", detail: { background: "罗马以两名执政官各率军合并，约八万余步兵与六千骑，求速战；汉尼拔约五万。", process: "前216年八月在奥菲杜斯河北岸列新月形阵，中央后退诱敌深入，骑兵破两翼后自后合围。", impact: "罗马死与被俘者以数万计，卡普亚、西西里与希腊诸邦倒戈；坎尼成为以少围多的教科书战例，罗马则以兵源与同盟韧性翻盘。", figures: ["汉尼拔", "卢基乌斯·埃米利乌斯·保卢斯（阵亡）", "盖乌斯·特雷恩提乌斯·瓦罗", "马哈巴尔"], place: "普利亚坎尼", state: "罗马共和国与迦太基", sources: ["波利比乌斯《历史》第三卷第一百零九至一百一十六章", "李维《自建城以来》第二十二卷"], tags: ["合围", "歼灭", "倒戈"] }, related: [] },
  { id: "world--b215--i01", track: "world", year: -215, yearApprox: false, dim: "institution", weight: 3, title: "奥皮亚战时限制法", summary: "禁妇女乘辇、穿彩衣与持半盎司以上金。", detail: { background: "坎尼战后国库与兵源俱匮，需抑私费以济军需，亦因妇女守丧逾制。", process: "前215年平民决议限妇女用金与彩衣，城内及千步内不得乘车，除宗教节庆；男子上诉受阻。", impact: "战时紧缩以等级特权为代价，前195年两护民官提案废止，加图斥其纵欲之议成拉丁政论名篇，反映战时法与消费政治。", figures: ["盖乌斯·奥皮乌斯", "马尔库斯·洪尼乌斯（护民官）"], place: "罗马", state: "罗马共和国", sources: ["李维《自建城以来》第三十四卷论废法辩论"], tags: ["禁奢", "战时法", "护民官"] }, related: [] },
  { id: "world--b212--m01", track: "world", year: -212, yearApprox: false, dim: "military", weight: 4, title: "叙拉古陷落与阿基米德之死", summary: "以器械守城两年，老匠人为罗马兵所杀。", detail: { background: "耶罗二世死后叙拉古倒向迦太基，罗马命马尔凯路斯围之，海陆并攻。", process: "前214至前212年围城，阿基米德所制起重机、投石与爪钩屡破攻势；前212年趁阿尔忒弥斯节夜入城。", impact: "据普鲁塔克与瓦勒里乌斯记，一罗马兵杀阿基米德于沙盘前；王库珍宝与机器图样入罗马，希腊力学随战利品西传。", figures: ["马尔库斯·克劳狄乌斯·马尔凯路斯", "阿基米德", "埃皮克得斯（叙拉古叛徒）"], place: "西西里叙拉古", state: "罗马共和国与叙拉古", sources: ["普鲁塔克《马尔凯路斯传》十九至二十一节", "李维《自建城以来》第二十五卷"], tags: ["围城", "器械", "战利"] }, related: [] },
  { id: "world--b211--s01", track: "world", year: -211, yearApprox: false, dim: "science", weight: 4, title: "罗马第纳里银币改制", summary: "定一银币重六十七分之一磅值十阿斯。", detail: { background: "汉尼拔战争使铸币含银量跌、物价乱，军饷与盟邦结算需标准币。", process: "前211年前后定第纳里银币约四点五克，值十阿斯，另铸半币与四分币，六座山神庙设铸币局，退役士兵管理。", impact: "此制行用近四百年，成为地中海东部的记账与结算标准；罗马得以军饷、粮购与赔金为杠杆支撑长期战争。", figures: ["罗马三名金属官（蒙内塔列斯）", "元老院财政委员会"], place: "罗马", state: "罗马共和国", sources: ["老普林尼《自然史》第三十三卷论银钱沿革", "共和末期第纳里币型谱研究"], tags: ["银币", "军饷", "本位"] }, related: [] },
  { id: "world--b211--m01", track: "world", year: -211, yearApprox: false, dim: "military", weight: 3, title: "卡普亚围降与惩戒", summary: "围之两年城中食尽，降后贵族被处死。", detail: { background: "前216年坎尼后卡普亚倒向汉尼拔，为意大利最大城与粮食仓。", process: "前212年起罗马围之，两年后城中饥毙，前211年开门降；元老院处死其议员多人，城失自治与部分领土。", impact: "以严罚止意大利同盟连锁倒戈，此后南意大利诸城不复敢叛；罗马亦显示其围久城的耐心与粮道控制力。", figures: ["克温图斯·富尔维乌斯·弗拉库斯", "卡普亚元老蒂图斯·马修斯（自尽）"], place: "坎帕尼亚卡普亚", state: "罗马共和国与卡普亚", sources: ["李维《自建城以来》第二十三至二十四卷", "瓦勒里乌斯·马克西姆斯《言行录》论惩戒"], tags: ["饥降", "惩戒", "同盟"] }, related: [] },
  { id: "world--b209--m01", track: "world", year: -209, yearApprox: false, dim: "military", weight: 3, title: "费边复取塔兰托", summary: "趁节庆夜借内应取上城，夺回意大利大港。", detail: { background: "塔兰托前213年叛罗马，迦太基驻军；费边任执政官时以缓兵制敌。", process: "前209年罗马军趁守军节庆，借盟友自外与内应自下门入，夺卫城；汉尼拔援军至而城已失。", impact: "罗马重掌他林敦港与对外海路，迦太基在意大利的补给线收缩；费边以迟滞与夺险并用的名声复振。", figures: ["昆图斯·费边·马克西姆斯", "法比乌斯之将（守将）"], place: "塔兰托", state: "罗马共和国", sources: ["李维《自建城以来》第二十七卷", "普鲁塔克《费边传》二十四至二十六节"], tags: ["内应", "海港", "迟滞"] }, related: [] },
  { id: "world--b207--m01", track: "world", year: -207, yearApprox: false, dim: "military", weight: 3, title: "梅陶鲁斯战役", summary: "哈斯德鲁巴携援军北意被歼，首级掷入汉营。", detail: { background: "哈斯德鲁巴自西班牙越阿尔卑斯与汉尼拔会合，罗马以两执政官分拒。", process: "前207年在梅陶鲁斯河畔，罗马前锋误敌为友，努米底亚骑兵败后，迦太基军溃，王弟阵亡，首级夜掷汉尼拔营。", impact: "汉尼拔知意大利战局不可为，叹罗马之势；南意大利转为罗马反攻，西班牙亦于次年尽入西庇阿之手。", figures: ["哈斯德鲁巴·巴卡", "盖乌斯·克劳狄乌斯·尼禄", "马尔库斯·李维乌斯"], place: "马尔凯梅陶鲁斯河", state: "罗马共和国与迦太基", sources: ["李维《自建城以来》第二十七卷", "波利比乌斯《历史》残篇第十一卷论其役"], tags: ["援军", "溃败", "心理战"] }, related: [] },
  { id: "world--b206--m01", track: "world", year: -206, yearApprox: false, dim: "military", weight: 3, title: "伊利帕战役与罗马取西班牙", summary: "反常列阵夺时辰，巴卡势力退出半岛。", detail: { background: "西庇阿在半岛以分化诸部与攻其必救，两迦太基统帅相持于伊利帕。", process: "前206年晨以罗马军居中、盟友守两翼之常式反易布阵，乘敌未食而进，火起敌营，两军溃。", impact: "迦太基撤出西班牙，罗马得银矿与兵源；西庇阿回罗马争得渡非洲之权，战争重心转向利比亚。", figures: ["普布利乌斯·科尔涅利乌斯·西庇阿", "哈米尔卡·吉斯贡", "马戈·巴卡"], place: "贝提卡伊利帕", state: "罗马共和国", sources: ["李维《自建城以来》第二十八卷", "波利比乌斯《历史》第十一卷残篇"], tags: ["变阵", "银矿", "反攻"] }, related: [] },
  { id: "world--b204--c01", track: "world", year: -204, yearApprox: false, dim: "culture", weight: 3, title: "弗里吉亚大母神入罗马", summary: "依预言迎黑石，国家接纳外来女神。", detail: { background: "汉尼拔战争久，罗马占书与预言称外邦之母可以驱敌；小亚帕辛斯的石像素为各方共奉。", process: "前204年使团请石，罗马择最贞洁者迎于台伯口；前191年帕拉丁庙成，行“母神节”赛会与祭司哀仪。", impact: "为罗马把外邦崇拜纳入城邦祭历的先例，亦开此后国家引进伊西斯、密特拉等东方宗教之门。", figures: ["罗马使团（十人）", "普布利乌斯·科尔涅利乌斯·西庇阿"], place: "帕辛斯、罗马帕拉丁", state: "罗马共和国", sources: ["奥维德《历日》卷四论母神", "李维《自建城以来》第二十九卷"], tags: ["外祀", "预言", "祭历"] }, related: [] },
  { id: "world--b202--m01", track: "world", year: -202, yearApprox: false, dim: "military", weight: 5, title: "扎马会战", summary: "以通道放象、三线合击，汉尼拔初败。", detail: { background: "西庇阿在利比亚连破迦太基野军与努米底亚王，汉尼拔应召回国。", process: "前202年秋扎马附近会战，罗马前排让出通道使八十头象冲过，骑兵驱散敌骑后自后合击。", impact: "迦太基主力尽失，被迫无条件请和；汉尼拔的政治生涯随之终结，西地中海霸权自此归罗马。", figures: ["普布利乌斯·科尔涅利乌斯·西庇阿", "汉尼拔", "马西尼萨"], place: "利比亚扎马", state: "罗马共和国与迦太基", sources: ["波利比乌斯《历史》第十五卷", "李维《自建城以来》第三十卷"], tags: ["战象", "合击", "霸权"] }, related: [] },
  { id: "world--b201--p01", track: "world", year: -201, yearApprox: false, dim: "politics", weight: 3, title: "第二次布匿和约", summary: "五十年的赔金、交舰队与不得擅战。", detail: { background: "扎马败后迦太基求和，罗马以限制其海陆军事力量为条件；努米底亚界约未定。", process: "前201年和约：五十赔金万塔兰同、交出船与象、留十艘、不获罗马许不得境外用兵，归还俘虏与牲畜。", impact: "迦太基由海权邦退为北非农商邦，以开垦与贸易复财，反成罗马再度开战之由；努米底亚因界石争议渐成附庸。", figures: ["普布利乌斯·科尔涅利乌斯·西庇阿", "迦太基和谈使团"], place: "利比亚", state: "罗马共和国与迦太基", sources: ["波利比乌斯《历史》第二十一卷和约条文", "李维《自建城以来》第三十卷"], tags: ["赔金", "裁军", "附庸"] }, related: [] },
  { id: "world--b200--i01", track: "world", year: -200, yearApprox: true, dim: "institution", weight: 3, title: "亚该亚同盟的联邦机构", summary: "以年选将军、共同会议与统一币量合邦。", detail: { background: "伯罗奔尼撒诸城久分，前255年后借民主运动与外邦金渐成同盟。", process: "约前第三世纪末定联邦制：年选将军一人统军与外交，共同会议按城派员，通用银币、度量与历法祭典。", impact: "希腊世界最成熟的联邦政体样本，波利比乌斯以其对比罗马；其自愿加入与投票机制亦因马其顿与罗马干涉而变质。", figures: ["阿拉托斯（前代建制者）", "菲洛皮门（后之将军）"], place: "伯罗奔尼撒、西基翁", state: "亚该亚同盟", sources: ["波利比乌斯《历史》第二卷、第四卷论同盟政制", "斯特拉波《地理学》第八卷"], tags: ["联邦", "将军", "币量"] }, related: [] },
  { id: "world--b197--m01", track: "world", year: -197, yearApprox: false, dim: "military", weight: 4, title: "库诺斯克法莱战役", summary: "军团分队趁地形裂阵，马其顿方阵败于侧后。", detail: { background: "腓力五世与罗马争希腊城邦，第二次马其顿战争已历三年。", process: "前197年色萨利山岗会战，方阵未及展开，罗马右翼四十个大队趁雾冲上敌阵右肩，刀锋自后入。", impact: "马其顿死与被俘数万，腓力交舰队、赔金千五百塔兰同并撤希腊驻军；方阵与军团的高下自此成军事史定论。", figures: ["提图斯·昆克提乌斯·弗拉米尼努斯", "腓力五世", "帕加马王欧迈尼斯"], place: "色萨利库诺斯克法莱", state: "罗马共和国与马其顿", sources: ["波利比乌斯《历史》第十八卷", "李维《自建城以来》第三十三卷"], tags: ["军团", "方阵", "侧后"] }, related: [] },
  { id: "world--b196--c01", track: "world", year: -196, yearApprox: false, dim: "culture", weight: 4, title: "罗塞塔三语诏书", summary: "祭司会议为王上尊号，三种文字刻同一令。", detail: { background: "托勒密五世平定上埃及叛乱，年十三，孟斐斯祭司为立尊号。", process: "前196年诏书以象形文、民书与希腊文同刻，减税、免驻军宿、追还寺产；石后砌入尼罗河口的堡墙。", impact: "因与希腊文对读，成为十九世纪释读埃及文字的钥匙（1822年商博良释读），埃及学由此立；诏书亦证希腊化王权依祭司合法化。", figures: ["托勒密五世", "孟斐斯祭司会议"], place: "拉希德（罗塞塔）", state: "托勒密埃及", sources: ["罗塞塔石碑铭刻校释本", "《剑桥古代史》第八卷"], tags: ["三语", "释读", "王权"] }, related: [] },
  { id: "world--b196--m01", track: "world", year: -196, yearApprox: false, dim: "military", weight: 3, title: "地峡宣布希腊自由", summary: "运动会上传令撤兵，诸城接收驻军撤除。", detail: { background: "库诺斯克法莱后罗马以解放者自居，腓力须退出希腊诸城与要塞。", process: "前196年地峡运动会上宣令：希腊人免纳贡、依祖法自治、罗马撤驻军；科林斯、哈尔基斯等城先后接收。", impact: "罗马以名义自由换取仲裁与征兵之实，希腊城邦的独立从此取决于罗马内部政治；此模式为后世东方诸省沿用。", figures: ["提图斯·昆克提乌斯·弗拉米尼努斯", "科林斯与卡尔基斯使节"], place: "科林斯地峡", state: "罗马共和国与希腊诸邦", sources: ["波利比乌斯《历史》第十八卷末至十八卷续", "普鲁塔克《弗拉米尼努斯传》十至十一章"], tags: ["自由宣言", "撤军", "仲裁"] }, related: [] },
  { id: "world--b191--m01", track: "world", year: -191, yearApprox: false, dim: "military", weight: 3, title: "安条克三世被逐出希腊", summary: "以不足万人守温泉关，败后退入小亚。", detail: { background: "埃托利亚同盟召塞琉古王为将军抗罗马，王携象与四万军渡海。", process: "前191年执政官加图绕山道上，王军惊溃于温泉关；同年罗马舰队在海弗斯与迈昂尼苏斯屡胜。", impact: "希腊失最后的东方靠山，埃托利亚城邦相继请和；罗马海军进入爱琴海，帕加马与罗得借势扩张。", figures: ["安条克三世", "马尔库斯·波尔基乌斯·加图", "汉尼拔（为王谋）"], place: "温泉关、爱琴海", state: "罗马共和国与塞琉古王国", sources: ["李维《自建城以来》第三十六至三十七章", "波利比乌斯《历史》残篇论埃托利亚"], tags: ["隘口", "绕后", "海军"] }, related: [] },
  { id: "world--b190--m01", track: "world", year: -190, yearApprox: false, dim: "military", weight: 3, title: "马格涅西亚战役", summary: "骑兵破其刀轮车，塞琉古军在小亚崩解。", detail: { background: "安条克三世在小亚集结象、刀轮车与重装骑兵，与罗马—帕加马联军相持。", process: "前190年在西皮洛斯山麓会战，帕加马骑兵以标枪与箭扰象，敌刀轮车反蹈己阵，步兵方阵被分割。", impact: "塞琉古损失数万，放弃托罗斯山以西；小亚诸城与加拉太地区转入帕加马与罗得影响圈，罗马成为东方裁判。", figures: ["卢基乌斯·科尔涅利乌斯·西庇阿", "欧迈尼斯二世", "安条克三世"], place: "小亚马格涅西亚", state: "罗马与塞琉古王国", sources: ["波利比乌斯《历史》二十一至二十二卷摘要", "李维《自建城以来》第三十七至三十八卷"], tags: ["刀轮车", "象队", "会战"] }, related: [] },
  { id: "world--b188--p01", track: "world", year: -188, yearApprox: false, dim: "politics", weight: 4, title: "阿帕梅亚和约", summary: "以山为界、赔金交舰队，罗马定东方版图。", detail: { background: "马格涅西亚败后塞琉古请和，罗马以盟约形式裁断小亚归属。", process: "前188年约成：塞琉古退至托罗斯山以东，赔金一千五百塔兰同，交船象，引渡汉尼拔等；地予帕加马与罗得。", impact: "罗马未设一行省却划定制约边界，开创以条约与仲裁管东方的方式；帕加马得希腊学术与税源，塞琉古内乱加速。", figures: ["卢基乌斯·科尔涅利乌斯·西庇阿", "普布利乌斯·科尔涅利乌斯·西庇阿（在场）", "欧迈尼斯二世"], place: "阿帕梅亚", state: "罗马共和国与塞琉古王国", sources: ["波利比乌斯《历史》第二十一卷和约摘文", "李维《自建城以来》第三十八卷"], tags: ["和约", "仲裁", "赔金"] }, related: [] },
  { id: "world--b186--i01", track: "world", year: -186, yearApprox: false, dim: "institution", weight: 4, title: "元老院禁酒神祭", summary: "以紧急决议查办秘密祭会，死者数千。", detail: { background: "酒神密祭由希腊祭司传入意大利，男女混杂、夜聚无监，债权人以之索财。", process: "前186年执政官据告发奏请，元老院决议限祭：不得超五人、不得男子同、须经城市裁判官准；铜版令文刻于布鲁提乌姆出土。", impact: "古代记载称处死数千，实际数字或有夸饰；此事确立元老院以紧急决议干预结社与宗教的先例，亦开罗马以治安法管秘密教团的传统。", figures: ["斯帕里乌斯·波斯图米乌斯（执政官）", "希斯帕拉（告发者，获释女奴）"], place: "罗马、南意大利", state: "罗马共和国", sources: ["李维《自建城以来》第三十九卷", "《酒神祭禁令》铜版铭文辑录"], tags: ["密祭", "紧急决议", "结社"] }, related: [] },
  { id: "world--b185--p01", track: "world", year: -185, yearApprox: false, dim: "politics", weight: 3, title: "孔雀王朝亡与巽伽起", summary: "将军弑主立巽伽，行马祭复旧礼。", detail: { background: "阿育王后王朝分崩，末王婆利赫德拉提斯受制于军中统帅。", process: "约前185年将军普沙密多罗在阅兵时弑主，都华氏城，复行马祭与吠陀祭祀；往世书与佛教传说记其迫害僧团，然碑铭所见供养未绝。", impact: "波罗提默与巴尔胡特窣堵波在此朝扩建，佛教艺术开始以本生故事浮雕叙事；西北希腊人乘虚入印度。", figures: ["普沙密多罗·尸友", "婆利赫德拉提斯"], place: "华氏城、巴尔胡特", state: "巽伽王朝", sources: ["往世书王统表校勘", "《剑桥印度史》第一卷"], tags: ["弑主", "马祭", "窣堵波"] }, related: [] },
  { id: "world--b180--p01", track: "world", year: -180, yearApprox: true, dim: "politics", weight: 2, title: "托勒密五世死与幼主再立", summary: "王崩于内乱余波，摄政争权启外患。", detail: { background: "上埃及叛事未平，宫廷派系与叙利亚王觊觎柯里叙利亚。", process: "约前180年托勒密五世死，其六岁子托勒密六世立，两位摄政相攻，前170年安条克四世遂第五次叙利亚战争起。", impact: "托勒密埃及由盛转衰，靠罗马一纸斡旋复国；希腊化诸王的内政自此常由罗马元老院裁决。", figures: ["托勒密五世", "托勒密六世", "安条克四世"], place: "亚历山大里亚", state: "托勒密埃及", sources: ["波利比乌斯《历史》第十五卷末至第二十六卷", "李维《自建城以来》第四十二卷"], tags: ["幼主", "摄政", "外患"] }, related: [] },
  { id: "world--b175--p01", track: "world", year: -175, yearApprox: false, dim: "politics", weight: 3, title: "安条克四世夺位", summary: "自埃及归而杀侄，塞琉古王权转于铁腕。", detail: { background: "塞琉古四世被弑，其幼子安条克在罗马为质，王弟自雅典返。", process: "前175年安条克以代理人除幼主，自立为四世，娶外甥女劳迪丝；旋偿罗马赔金尾款，行铸币与建城。", impact: "其集财与希腊化新政（建奥林匹亚宙斯庙、设竞技）耗尽寺库，激起耶路撒冷希腊化派与正统派相攻，为前167年禁令之前因。", figures: ["安条克四世", "塞琉古四世（被弑）", "罗马使节"], place: "安条克", state: "塞琉古王国", sources: ["波利比乌斯《历史》第二十六卷", "第二马加比书第四章"], tags: ["夺位", "寺库", "希腊化"] }, related: [] },
  { id: "world--b172--p01", track: "world", year: -172, yearApprox: false, dim: "politics", weight: 2, title: "帕加马王陈词与罗马宣战", summary: "欧迈尼斯在元老院数马其顿备战之罪。", detail: { background: "珀尔修斯联希腊邦与部落，修道路、聚兵器，罗马粮价与同盟恐慌。", process: "前172年冬欧迈尼斯入罗马陈词，归途遇刺，遂以其伤为罗马出兵的凭据；前171年宣战。", impact: "第三次马其顿战争起，希腊诸邦被迫选边，亚该亚内部亲罗马派以送质（含波利比乌斯）自保，十年后科林斯被毁。", figures: ["欧迈尼斯二世", "珀尔修斯", "元老院主战派"], place: "罗马", state: "罗马共和国与马其顿", sources: ["李维《自建城以来》第四十二卷", "波利比乌斯《历史》残篇第二十八卷"], tags: ["陈词", "宣战", "选边"] }, related: [] },
  { id: "world--b170--p01", track: "world", year: -170, yearApprox: true, dim: "politics", weight: 3, title: "上埃及祭司政权分立", summary: "本土贵族据底比斯，与希腊化宫廷相抗百年。", detail: { background: "外邦征税与神庙经济受损，托勒密幼主摄政内讧，南部贵族得僧团支持。", process: "约前208年起胡甘弗与夏阿那先后称王于底比斯一带，铸币、修寺；前186年罗马史料称叛定。", impact: "托勒密六世不得不大赦并请罗马仲裁，神庙经济与本土精英自此分享政权；罗塞塔诏书的减税令即其背景。", figures: ["胡甘弗", "夏阿那", "托勒密六世"], place: "底比斯、上埃及", state: "托勒密埃及与本土政权", sources: ["《剑桥古代史》第八卷", "底比斯神庙铭刻纪年辑录"], tags: ["分立", "僧团", "税制"] }, related: [] },
  { id: "world--b170--a01", track: "world", year: -170, yearApprox: true, dim: "art", weight: 3, title: "帕加马大祭坛的巨人之战", summary: "以高浮雕记战胜蛮族，成希腊化巴洛克样板。", detail: { background: "阿塔罗斯王朝以战胜加拉太人与高卢自诩希腊守护者，需神学化的纪念物。", process: "约前180至前160年建卫城大祭坛，基座高浮雕百丈余，写诸神与巨人之战，垂死的高卢人题材入青铜与大理石。", impact: "以痛苦与动势表现异族的悲壮，成为希腊化造型的极端风格；其残件十九世纪移入柏林，引发近代文物流属争议。", figures: ["菲洛斯科罗斯（匠师名刻）", "欧迈尼斯二世"], place: "帕加马卫城", state: "帕加马邦", sources: ["帕加马祭坛发掘报告综述", "老普林尼《自然史》第三十四卷论匠师"], tags: ["浮雕", "巨人", "纪念"] }, related: [] },
  { id: "world--b168--m01", track: "world", year: -168, yearApprox: false, dim: "military", weight: 4, title: "皮德纳战役与马其顿亡国", summary: "两时会合破方阵，安提柯王朝终。", detail: { background: "珀尔修斯拒和并求援诸邦，罗马以两执政官之军合于保卢斯。", process: "前168年六月末两日会战，月蚀后次日进攻，敌阵因地石与骑兵楔入而裂；据古载马其顿死两万。", impact: "马其顿废王、析为四自治区且不得互通婚姻与买卖，矿山岁入半归罗马；希腊化王国第一次被整建制拆除。", figures: ["卢基乌斯·埃米利乌斯·保卢斯", "珀尔修斯", "马其顿将领根提阿斯"], place: "皮埃里亚皮德纳", state: "罗马共和国与马其顿", sources: ["普鲁塔克《埃米利乌斯·保卢斯传》十八至二十一节", "李维《自建城以来》第四十四至四十五卷"], tags: ["会战", "月蚀", "废王"] }, related: [] },
  { id: "world--b168--p01", track: "world", year: -168, yearApprox: false, dim: "politics", weight: 4, title: "罗马一日通牒逼退塞琉古军", summary: "以圈沙之问拒安条克再占埃及。", detail: { background: "安条克四世两征埃及、围亚历山大里亚，罗马忙于马其顿而先遣使。", process: "前168年七月保卢斯在厄琉西斯城外会王，传达元老院令其即撤；王求数日，画地一圈，限答于圈内。", impact: "王退兵，柯里叙利亚仍归埃及，希腊化大国首次被一共和国以文书逼退；此后东方争端皆上诉罗马。", figures: ["盖乌斯·波皮利乌斯·拉埃纳斯", "安条克四世"], place: "厄琉西斯城郊", state: "罗马共和国与塞琉古王国", sources: ["波利比乌斯《历史》第二十九卷", "李维《自建城以来》第四十五卷"], tags: ["最后通牒", "仲裁", "退兵"] }, related: [] },
  { id: "world--b167--p01", track: "world", year: -167, yearApprox: false, dim: "politics", weight: 3, title: "马其顿析为四共和国", summary: "去王权、禁互通，以岁贡半额归罗马。", detail: { background: "皮德纳后保卢斯在安菲波利斯召集民众大会，宣布处置方案。", process: "前167年将马其顿分四个互不统属的自治体，矿山与造船限制，税定为王国旧额之半，各不得跨区买地与通婚。", impact: "罗马以分而治之取代占领，减少戍费而收其利；此策成为其处置王国与同盟的通例，十年后因伪王再起设行省。", figures: ["卢基乌斯·埃米利乌斯·保卢斯", "马其顿各邑代表"], place: "安菲波利斯", state: "罗马共和国", sources: ["李维《自建城以来》第四十五卷", "波利比乌斯《历史》第三十一卷残篇"], tags: ["分治", "免税半", "矿禁"] }, related: [] },
  { id: "world--b167--e01", track: "world", year: -167, yearApprox: false, dim: "economy", weight: 3, title: "提洛岛开自由港", summary: "以免税夺拜占庭与科林斯商税之源。", detail: { background: "皮德纳后罗马惩罗得亲马其顿，罗得税源与商队为其目标。", process: "前167年罗马宣布提洛为自由港，免征进出口税，岛民以祭司金库与商馆招揽亚细亚货物转口。", impact: "东地中海转口枢纽自罗得移至提洛，商人、奴隶市场与币流并聚；罗马以税制为外交工具的手法首次定型。", figures: ["罗马驻亚细亚使节", "提洛岛执政官"], place: "提洛岛", state: "罗马共和国与提洛", sources: ["斯特拉波《地理学》第十四卷论罗得失势", "提洛岛商会铭刻辑录"], tags: ["自由港", "转口", "税制"] }, related: [] },
  { id: "world--b167--p02", track: "world", year: -167, yearApprox: false, dim: "politics", weight: 4, title: "安条克四世禁犹太礼", summary: "圣殿立异教像，行割礼与守安息日处死。", detail: { background: "耶路撒冷希腊化祭司派争位，圣殿金银与税入国库，玛塔提亚等保守氏族怨。", process: "前167年基斯流月十五日起，祭坛上立“荒凉可憎之物”，屠猪于坛，禁割礼、安息日与经卷诵读，违者处死。", impact: "犹大·玛加比起兵，历经二十年得独立；古代史料以两卷马加比书互校，此事成宗教迫害与反抗传统的经典个案。", figures: ["安条克四世", "玛他提亚", "雅松（大祭司争位者）"], place: "耶路撒冷圣殿", state: "塞琉古王国与犹地亚", sources: ["但以理书第十一章与马加比二书第五章互校", "《剑桥犹太史》第二卷"], tags: ["禁礼", "圣殿", "反抗"] }, related: [] },
  { id: "world--b164--c01", track: "world", year: -164, yearApprox: false, dim: "culture", weight: 3, title: "圣殿重献与光明节起源", summary: "净化圣殿重立祭坛，定八日之节。", detail: { background: "玛加比军夺伯和仑等隘，前165年围耶路撒冷卫城，外邦驻军与背教祭司被困。", process: "前164年基斯流月二十五日重献祭坛，制新器、定节期八日记灯油奇迹；其节沿用至罗马时期。", impact: "宗教历法与民族记忆绑定，哈斯蒙尼家以祭司兼王统立国，百年内为罗马所灭；重献之事见于死海古卷与新约。", figures: ["犹大·玛加比", "俄尼阿家族诸祭司"], place: "耶路撒冷", state: "犹地亚", sources: ["马加比上书第四章", "约瑟夫斯《犹太古史》第十二卷"], tags: ["重献", "灯节", "历法"] }, related: [] },
  { id: "world--b160--s01", track: "world", year: -160, yearApprox: true, dim: "science", weight: 3, title: "加图《农业志》与意大利庄园", summary: "以手册定葡萄橄榄经营与奴隶配给。", detail: { background: "布匿战后意大利出现大地产，需可传授的经营与用工规则。", process: "约前160年代成书四十五章：分地力、播种、园圃、庄屋与契约，列农具、奴隶口粮与榨酒器数。", impact: "为拉丁散文与农书之祖，瓦罗与科鲁迈拉续其例；书中以二十奴隶为单位的庄园模型，成为近代研究意大利农业的定量入口。", figures: ["马尔库斯·波尔基乌斯·加图", "马尔库斯（其子）"], place: "罗马", state: "罗马共和国", sources: ["加图《农业志》校注本", "瓦罗《农业论》引其说"], tags: ["农书", "庄园", "定量"] }, related: [] },
  { id: "world--b160--a01", track: "world", year: -160, yearApprox: true, dim: "art", weight: 2, title: "特伦斯喜剧与拉丁语改良", summary: "以非洲解放奴写人本剧，双线与雅语并进。", detail: { background: "罗马新喜剧仿米南德，贵族沙龙（西庇阿圈）助其改希腊布景为拉丁言。", process: "前170至前160年代演六剧，《两兄弟》言“人之于我皆我所关”，双线情节与口语纯净并重。", impact: "其本成为共和末期拉丁文法教学范本，词汇与句式定型影响西塞罗与后世喜剧；亦显希腊化剧本在罗马的再创造。", figures: ["特伦斯", "小西庇阿圈的门客"], place: "罗马", state: "罗马共和国", sources: ["特伦斯剧本古代题解与献辞", "多纳图斯《特伦斯传》"], tags: ["新喜剧", "拉丁语", "校本"] }, related: [] },
  { id: "world--b155--c01", track: "world", year: -155, yearApprox: false, dim: "culture", weight: 3, title: "学园派使团在罗马讲学", summary: "卡尔尼亚底斯两日论正义相反，加图斥之。", detail: { background: "雅典因橄榄地产罚款遣三哲人使团求免，雅典之学园、斯多亚、漫步三派各遣代表。", process: "前155年卡尔尼亚底斯先论正义依自然、次日论依约定，罗马青年竞听；加图借机促其速离。", impact: "希腊怀疑论与论辩术传入罗马上层，罗马以驱逐与限定讲学回应；此后拉丁哲学与修辞学在张力中成形。", figures: ["卡尔尼亚底斯", "马尔库斯·波尔基乌斯·加图", "克里斯托劳斯（斯多亚代表）"], place: "罗马", state: "罗马共和国与雅典", sources: ["普鲁塔克《加图传》二十三至二十四节", "奥卢斯·革利乌斯《阿提卡之夜》卷六"], tags: ["怀疑论", "讲学", "驱逐"] }, related: [] },
  { id: "world--b150--c01", track: "world", year: -150, yearApprox: true, dim: "culture", weight: 4, title: "波利比乌斯《历史》论混合政体", summary: "以四十卷解罗马何以十九年得天下。", detail: { background: "作为亚该亚人质寓罗马，随小西庇阿，得以阅档与访老将。", process: "约前150年代起成四十卷，自前220至前146；以政体循环论释罗马执政官、元老院、公民三会相制。", impact: "其制度比较与亲历考信之法为史学典范，混合政体说经西塞罗、孟德斯鸠直至近代宪政论；书多佚，仅前六卷完整。", figures: ["波利比乌斯", "小西庇阿", "老加图（曾为其庇护）"], place: "罗马", state: "罗马共和国与希腊史学", sources: ["波利比乌斯《历史》第一、第六卷", "《剑桥古代史》第八卷"], tags: ["政体循环", "亲历", "宪政"] }, related: [] },
  { id: "world--b149--f01", track: "world", year: -149, yearApprox: false, dim: "figure", weight: 3, title: "老加图逝世", summary: "以农书、《起源》与反希腊文风定拉丁散文。", detail: { background: "起于马尔凯农户，历军职与监察官（前184），以节刑名与控奢著称。", process: "晚年著《起源》记意大利与罗马传说，首用拉丁文写史并免希腊文；前149年卒，其子与孙续其门。", impact: "其“迦太基必须毁灭”之语成政治口号；农书、演说与史著确立拉丁散文的实用风格，为共和末期西塞罗之先声。", figures: ["马尔库斯·波尔基乌斯·加图", "马尔库斯·波尔基乌斯·加图（子）"], place: "罗马", state: "罗马共和国", sources: ["普鲁塔克《加图传》序述", "加图《起源》残篇辑"], tags: ["散文", "监察官", "口号"] }, related: [] },
  { id: "world--b146--m01", track: "world", year: -146, yearApprox: false, dim: "military", weight: 5, title: "迦太基城陷与毁废", summary: "围三年巷战六日，城焚十七日，五万人被卖。", detail: { background: "努米底亚界争与偿金纠纷中，迦太基自卫逾约，罗马以宣战应之（第三次布匿）。", process: "前148至前146年围城，断其地峡，最后三日据埃什蒙纳布尔神庙巷战；城破后按十使臣令焚毁，居民五万余被卖为奴。", impact: "其地置阿非利加行省，按十分之一与八分之一课谷；此城废为古代以毁灭解决商业竞争之著名案例，措辞须据史料而不渲染。", figures: ["普布利乌斯·科尔涅利乌斯·西庇阿·埃米利亚努斯", "迦太基末代统帅哈斯德鲁巴（投降）", "十使臣"], place: "迦太基", state: "罗马共和国与迦太基", sources: ["阿庇安《罗马史·布匿战纪》末章", "李维《自建城以来》摘要卷四十九"], tags: ["围城", "巷战", "毁城"] }, related: [] },
  { id: "world--b146--m02", track: "world", year: -146, yearApprox: false, dim: "military", weight: 4, title: "科林斯夷平", summary: "破城一日屠掠，艺术珍宝入罗马。", detail: { background: "亚该亚同盟拒罗马分区令，围斯巴达属城，罗马遣莫米乌斯进兵。", process: "前146年围科林斯六日破城，据古载男子多被杀、妇孺入奴，城垣与公建筑拆平，画塑掠运罗马。", impact: "希腊古典时代最后的大城废为无人地六十余年；亚该亚诸城失盟、纳贡，罗马以毁灭惩罚联邦政治，史家多以此为希腊化时代下限。", figures: ["卢基乌斯·穆米乌斯", "亚该亚将军迪埃奥斯"], place: "科林斯", state: "罗马共和国与亚该亚同盟", sources: ["波利比乌斯《历史》残篇第三十九卷（其亲见）", "帕乌萨尼亚斯《希腊志》第七卷"], tags: ["破城", "掠艺", "行省"] }, related: [] },
  { id: "world--b146--e01", track: "world", year: -146, yearApprox: false, dim: "economy", weight: 3, title: "马戈农书译拉丁与阿非利加税", summary: "城毁而其农学二十卷归公库并译。", detail: { background: "迦太基自腓尼基时代积农艺，马戈之著为地中海农学之冠。", process: "前146年城破后元老院令分其库书，命译马戈农书为拉丁，唯其余诸书散佚；新行省按田收什一或八分一谷。", impact: "布匿农法经此入意大利庄园传统，科鲁迈拉与普林尼屡引；北非自此渐成罗马谷仓，其税制为后世帝政粮运之基。", figures: ["马戈（原著作人）", "译书委员会（元老院所命）"], place: "迦太基、罗马", state: "罗马共和国与阿非利加行省", sources: ["老普林尼《自然史》第十八卷论马戈", "科鲁迈拉《论农事》序引"], tags: ["农书", "翻译", "谷物税"] }, related: [] },
  { id: "world--b146--a01", track: "world", year: -146, yearApprox: true, dim: "art", weight: 2, title: "萨莫色雷斯胜利女神像", summary: "以船首与迎风衣纹立爱琴海圣域。", detail: { background: "为纪念海战献于卡比罗斯圣域，希腊化海权祭仪盛行以舰形与鸟兽入像。", process: "约前二世纪中叶作，头像与手臂佚，高约三点二米立于船首形基座，衣褶逆风贴体。", impact: "以动势与湿衣法表现神迹降临，成为希腊化雕塑的标识；1863年出土后入卢浮宫，引发关于海战归属的断代之争。", figures: ["萨莫色雷斯匠派（名不详）"], place: "萨莫色雷斯岛圣域", state: "希腊化爱琴海", sources: ["《希腊雕塑》专题研究综述", "圣域发掘报告第一编"], tags: ["雕塑", "衣纹", "圣域"] }, related: [] },
  { id: "world--b141--m01", track: "world", year: -141, yearApprox: false, dim: "military", weight: 3, title: "米特拉达梯一世取两河", summary: "占塞琉西亚与巴比伦，帕提亚成西亚大国。", detail: { background: "塞琉古内部篡位与游牧压力并起，帕提亚王米特拉达梯一世东西扩张。", process: "前141年冬入巴比伦尼亚，取塞琉西亚与巴比伦城，止于苏萨以东；自铸双语德拉克马，称“万王之王”。", impact: "两河税源与商路归帕提亚，塞琉古仅存叙利亚；罗马与帕提亚的接壤与仲裁由此成为此后七百年东方主轴。", figures: ["米特拉达梯一世", "塞琉古七世", "巴比伦神庙书记"], place: "巴比伦尼亚", state: "帕提亚与塞琉古", sources: ["巴比伦编年史残篇", "斯特拉波《地理学》第十一卷"], tags: ["扩张", "王号", "税源"] }, related: [] },
  { id: "world--b140--s01", track: "world", year: -140, yearApprox: true, dim: "science", weight: 4, title: "喜帕恰斯定岁差与星表", summary: "以古今星位相较，得二分点西移之数。", detail: { background: "罗得岛观测条件佳，前人记录与巴比伦周期表已可资比对。", process: "约前140至前120年间测恒星位置，编千余星之六等星表；比较前二百六十五年之记录，得岁差每百年一度。", impact: "创立以实测推长期天象变化的方法，其弦表为三角函数之前身；托勒密《天文学大成》全承其数据，十九世纪前无人逾其精度。", figures: ["喜帕恰斯", "阿利斯塔恰斯（前人所测）"], place: "罗得岛、尼西亚", state: "希腊天文学", sources: ["托勒密《天文学大成》第七卷引其星表", "普洛克洛斯《论球运动》述岁差"], tags: ["岁差", "星表", "三角"] }, related: [] },
  { id: "world--b137--x01", track: "world", year: -137, yearApprox: false, dim: "explore", weight: 2, title: "罗马与帕提亚首次通使", summary: "以执政官衔使其廷，定幼发拉底为界。", detail: { background: "帕提亚取两河后罗马东方省界需定，安条克七世西迁复国亦须照会。", process: "前138至前137年盖乌斯·马利乌斯·马克西姆斯使于帕提亚廷，见米特拉达梯一世，议以幼发拉底河为势力分界。", impact: "两大共和国—王国体系的首次正式接触，此后使节礼仪与界河成为罗马—帕提亚外交的固定议程。", figures: ["盖乌斯·马利乌斯·马克西姆斯", "米特拉达梯一世"], place: "帕提亚廷（赫卡托姆皮洛斯）", state: "罗马共和国与帕提亚", sources: ["普林尼《自然史》第三十卷记使节所见术士", "阿庇安《罗马史·米特拉达提战纪》首章"], tags: ["通使", "界河", "礼仪"] }, related: [] },
  { id: "world--b133--p01", track: "world", year: -133, yearApprox: false, dim: "politics", weight: 5, title: "提比略·格拉古土地法与被杀", summary: "护民官以公地重分于贫民，遭元老院击杀。", detail: { background: "公地被豪族占逾法定限额，意大利自由农衰而兵源减，格拉古以护民官提案。", process: "前133年《塞姆普罗尼亚土地法》限占五百尤盖拉、余部分配贫民，且绕元老院交公民大会；连任时被以僭主罪击杀，死者数百，尸投台伯。", impact: "共和史上第一次以暴力清除民选护民官，从此党争以会场上杀人；阿庇安称此后百年内战由此始。", figures: ["提比略·格拉古", "普布利乌斯·西庇阿·纳西卡", "格拉古之母科尔涅利娅"], place: "罗马卡皮托林", state: "罗马共和国", sources: ["普鲁塔克《提比略·格拉古传》", "阿庇安《罗马史·内战史》卷一"], tags: ["土地法", "政治暴力", "护民官"] }, related: [] },
  { id: "world--b133--p02", track: "world", year: -133, yearApprox: false, dim: "politics", weight: 3, title: "帕加马遗赠与亚细亚行省", summary: "王以遗嘱让国，罗马得东方第一个税区。", detail: { background: "阿塔罗斯三世惧罗马上行权威而仇罗马贵族，病中书遗命。", process: "前133年阿塔罗斯三世卒，遗嘱以其国与库藏遗罗马；前130至前129年平阿里斯东尼克之乱，前129年设亚细亚行省。", impact: "罗马不战得巨库与城邦网，行省包税人自此坐大，成为共和国财政与腐败的双引擎。", figures: ["阿塔罗斯三世", "马尼乌斯·阿基利乌斯（平乱者）", "阿里斯东尼克"], place: "帕加马", state: "罗马共和国与亚细亚行省", sources: ["阿庇安《罗马史·米特拉达提战纪》首章", "斯特拉波《地理学》第十三卷"], tags: ["遗赠", "行省", "包税"] }, related: [] },
  { id: "world--b132--m01", track: "world", year: -132, yearApprox: false, dim: "military", weight: 2, title: "阿里斯东尼克起义", summary: "王庶子聚奴与贫民建城，三年后被平。", detail: { background: "遗赠不得人心，帕加马诸城惧罗马税吏，王弟据内陆起事。", process: "前132年起事者建“太阳城”式团体，吸收逃亡奴隶；前129年罗马以阿基利乌斯与以弗所等盟军破之。", impact: "起义失败后帕加马等地并入行省，罗马以盟邦海军助战成例，此后东方海权依赖罗得与卡里亚诸港。", figures: ["阿里斯东尼克", "马尼乌斯·阿基利乌斯", "以弗所使节"], place: "小亚内陆与帕加马", state: "罗马共和国", sources: ["斯特拉波《地理学》第十三卷", "查士丁《腓力史》摘要卷三十六"], tags: ["起义", "盟军", "行省"] }, related: [] },
  { id: "world--b131--p01", track: "world", year: -131, yearApprox: false, dim: "politics", weight: 2, title: "阿里斯托尼库斯余部与罗马入小亚", summary: "本都王借机取锡诺普，罗马被迫东顾。", detail: { background: "行省未固，帕加马余党求援于本都，罗马在意大利又起乱。", process: "前131年起事者围卡斯塔巴，罗马将军克拉苏被杀；前129年援军至而平之，同时设行省税目。", impact: "罗马确认以小亚为常制税区而非临时保护地，本都与亚美尼亚自此成为东方缓冲与敌手。", figures: ["阿里斯东尼克", "普布利乌斯·李锡尼·克拉苏", "法尔纳凯斯一世"], place: "弗里吉亚、本都", state: "罗马共和国与本都", sources: ["斯特拉波《地理学》第十二卷", "查士丁《腓力史》摘要卷三十六"], tags: ["余乱", "缓冲", "税区"] }, related: [] },
  { id: "world--b129--c01", track: "world", year: -129, yearApprox: true, dim: "culture", weight: 3, title: "斯多亚学者入罗马讲学", summary: "帕奈提乌斯等以西塞罗圈的道德论传罗马。", detail: { background: "阿塔罗斯遗赠后学者随使团往来，罗马贵族需一套可实践的伦理与修辞。", process: "约前130年代帕奈提乌斯与小西庇阿、莱利乌斯游，著《论责任》体例与天文历算讲章，重实德而轻玄辩。", impact: "斯多亚学说由希腊派入罗马士族，成为共和末期至帝政初期的主流道德语汇；《论义务》即其后裔。", figures: ["帕奈提乌斯", "小西庇阿", "盖乌斯·莱利乌斯"], place: "罗马、帕加马", state: "罗马共和国与斯多亚派", sources: ["西塞罗《论义务》序述师承", "第欧根尼·拉尔修《名哲言行录》第七卷"], tags: ["斯多亚", "责任", "士族"] }, related: [] },
  { id: "world--b125--p01", track: "world", year: -125, yearApprox: false, dim: "politics", weight: 3, title: "公民权法案被否与费格莱叛", summary: "执政官提案与拉丁人共享公民权，元老院斥之。", detail: { background: "意大利同盟者服役多而权利少，盖约·格拉古曾欲分权未果。", process: "前125年执政官弗尔维乌斯·弗拉库斯提案，费格莱城先发叛，事泄而破，罗马军毁其城。", impact: "和平扩权的门径被关，三十年后同盟战争以十万级死伤重提此问；此城之毁亦示意大利内部的高压。", figures: ["卢基乌斯·弗尔维乌斯·弗拉库斯", "费格莱起义者"], place: "拉丁姆费格莱", state: "罗马共和国", sources: ["李维《自建城以来》摘要卷六十", "阿庇安《罗马史·内战史》卷一"], tags: ["公民权", "否决", "毁城"] }, related: [] },
  { id: "world--b123--p01", track: "world", year: -123, yearApprox: false, dim: "politics", weight: 4, title: "盖约·格拉古的粮食与审判法", summary: "以平价售粮并移审判权于骑士。", detail: { background: "其兄法案虽存而分配不力，罗马无产者渐成常设问题，贵族法庭包庇自犯。", process: "前123年护民官任上立《森布洛尼亚粮食法》按低于市价售粮，又定行省贪赃案由骑士任陪审员审理，另拟殖民地与道路法。", impact: "国家首次以常设平价粮养城市贫民，骑士阶层取得司法与包税的独立地位，罗马政治自此三分：贵族、骑士、城市民。", figures: ["盖约·格拉古", "马尔库斯·费伊乌斯（副手）", "玛尔库斯·富尔维乌斯（执政官）"], place: "罗马", state: "罗马共和国", sources: ["普鲁塔克《盖约·格拉古传》", "阿庇安《罗马史·内战史》卷一"], tags: ["粮食法", "骑士", "审判"] }, related: [] },
  { id: "world--b122--p01", track: "world", year: -122, yearApprox: false, dim: "politics", weight: 3, title: "盖约·格拉古败死", summary: "以暴力阻其选举，元老院表决后杀三千人。", detail: { background: "其公民权法案为罗马平民亦不谅，罗马山神庙祭祀之乱被利用。", process: "前122年任保民官连任失败，前121年元老院通过“最终劝告”决议，以执政官统兵攻其党众，死与被杀者约三千。", impact: "首次以合法形式授权大规模杀戮公民，格拉古派瓦解但粮法与骑士法庭保留，为马略与苏拉的党争提供模式。", figures: ["盖约·格拉古（自尽）", "卢基乌斯·奥皮米乌斯（执政官）", "马尔库斯·富尔维乌斯"], place: "罗马阿芬丁山", state: "罗马共和国", sources: ["普鲁塔克《盖约·格拉古传》第十四至十七章", "阿庇安《罗马史·内战史》卷一"], tags: ["最终劝告", "屠杀", "党争"] }, related: [] },
  { id: "world--b120--s01", track: "world", year: -120, yearApprox: true, dim: "science", weight: 4, title: "安提基特拉齿轮机", summary: "以卅余青铜齿轮运历法与行星指针。", detail: { background: "希腊化亚历山大里亚的齿轮与天文模型已有传述，需便携演示器。", process: "约前150至前100年制成，船难沉于安提基特拉附近；1901年潜水员得残块，齿轮二百余齿、十八至二十二级嵌套。", impact: "以十七片残件证明古代已有差动与周期齿轮，可推默冬章、奥林匹克周期与行星位置，重写古代机械史。", figures: ["罗得岛波西多尼奥斯学派（推测设计源）", "潜水采集者（1900年）"], place: "安提基特拉海", state: "希腊化世界", sources: ["安提基特拉机械研究组影像断层报告", "老普林尼《自然史》论阿基米德天球仪"], tags: ["齿轮", "天文仪", "船货"] }, related: [] },
  { id: "world--b120--x01", track: "world", year: -120, yearApprox: true, dim: "explore", weight: 2, title: "欧多克斯拟绕利比亚", summary: "自埃及或加迪尔出发的环球试航说。", detail: { background: "托勒密八世遗命以昔兰尼加予罗马，埃及与利比亚航路渐为希腊人所知。", process: "约前一百二十年代居齐库斯的欧多克斯试绕非洲，其说见于波西多尼奥斯转述，或言至大西洋彼岸见大陆。", impact: "其记虽可疑，却把非洲可绕、印度洋通大西洋的判断带入希腊地理学，斯特拉波据此讨论，后世地图沿革有据。", figures: ["欧多克斯（居齐库斯）", "波西多尼奥斯（转述者）"], place: "加迪尔或红海", state: "希腊航海界", sources: ["斯特拉波《地理学》第一、二卷引其说", "老普林尼《自然史》第二卷"], tags: ["环球", "转述", "质疑"] }, related: [] },
  { id: "world--b120--e01", track: "world", year: -120, yearApprox: true, dim: "economy", weight: 3, title: "托勒密朝红海港与猎象航线", summary: "以贝勒尼基通印度洋，象队与税站并起。", detail: { background: "塞琉古失两河、罗得掌中转，托勒密急需战象与东方货物直达。", process: "前三世纪末至前二世纪开红海诸港（阿尔西诺、米奥斯霍尔莫斯、贝勒尼基），陆道设水站与象猎队，运丁香与胡椒。", impact: "印度洋季风顺逆相乘成为年度航期，希腊—印度直航常态化，为罗马时代《厄立特里亚海航行记》所记商网之前身。", figures: ["托勒密三世（象猎总监）", "阿尔西诺（命名女王）"], place: "红海与贝勒尼基", state: "托勒密埃及", sources: ["《厄立特里亚海航行记》第二六至二八章回溯", "斯特拉波《地理学》第十六、十七卷"], tags: ["红海", "季风", "香料"] }, related: [] },
  { id: "world--b118--p01", track: "world", year: -118, yearApprox: false, dim: "politics", weight: 3, title: "罗马仲裁三分努米底亚", summary: "以监护人之名拆一国，朱古达得肥壤。", detail: { background: "努米底亚王米基普萨卒于前118年，遗命以国分与二子与养子朱古达，并请罗马为见证；三人争立，兵革不息。", process: "罗马遣大西庇阿为使仲裁，按其军功与亲谊分国：阿德尔巴得东境，希姆萨尔得西境，朱古达得中部沃土与两处税源之城。旋以罗马上层金贿闻。", impact: "北非的谷仓与商路自此入罗马政争之内事，一王之废立在元老院与骑士包税人之间交易；朱古达并国之乱由此伏线。", figures: ["普布利乌斯·科尔涅利乌斯·西庇阿·埃米利阿努斯", "阿德尔巴", "朱古达"], place: "基尔塔（今阿尔及利亚君士坦丁）", state: "努米底亚王国与罗马共和国", sources: ["萨卢斯特《朱古达战争纪》第十至一四章", "《剑桥古代史》第九卷论努米底亚"], tags: ["仲裁", "分国", "金贿"] }, related: [] },
  { id: "world--b118--i01", track: "world", year: -118, yearApprox: false, dim: "institution", weight: 3, title: "纳滂高卢行省成型", summary: "以纳博为殖民城，设山南以外第一省。", detail: { background: "前121年罗马击破阿尔韦尼与阿洛布罗格，占罗讷河下游与地中海北岸，需常设之治。", process: "前118年纳博·马尔提乌斯成罗马公民殖民地，为行省之名所自；同年道米提亚大道通意大利至西班牙，遣执政官年一人为总督，辖诸希腊与土著城。", impact: "这是阿尔卑斯山外的第一个常设行省，罗马的省制、税额定则与殖民城网始成定制；纳博亦成高卢内陆与地中海的转口枢纽。", figures: ["格涅乌斯·道米提乌斯·阿赫诺巴尔布斯", "马尔库斯·埃米利乌斯·雷必达"], place: "纳博（今法国纳博讷）", state: "罗马共和国与纳滂高卢行省", sources: ["斯特拉波《地理学》第四卷论纳博", "《剑桥古代史》第九卷论行省之始"], tags: ["行省", "殖民城", "大道"] }, related: [] },
  { id: "world--b113--m01", track: "world", year: -113, yearApprox: true, dim: "military", weight: 3, title: "辛布里战争起", summary: "日耳曼诸族南逼诺莱亚，罗马诱而击之。", detail: { background: "辛布里、条顿与安布龙等族自北海沿岸南徙，前113年入诺里库姆，攻罗马盟邦提里斯提尼人。", process: "执政官卡波率军至诺莱亚，闻敌众而许和退兵；其向导引辛布里人入阿尔卑斯山东口，罗马军中途掩击，反为所破，营垒辎重尽失。", impact: "此败开启十二年罗马屡北之局，山外两省与高卢皆受兵；罗马的征兵额与统帅体制之弊暴露，为马略改制提供口实。", figures: ["盖乌斯·帕皮里乌斯·卡波", "辛布里诸族首领"], place: "诺莱亚（今奥地利东蒂罗尔阿古姆）", state: "罗马共和国与辛布里人", sources: ["普鲁塔克《马略传》第十五至一七章", "弗洛鲁斯《罗马史纲要》卷三"], tags: ["族迁", "边省", "覆军"] }, related: [] },
  { id: "world--b112--p01", track: "world", year: -112, yearApprox: false, dim: "politics", weight: 3, title: "朱古达围基尔塔", summary: "杀弟并国，城陷并诛寓居罗马人。", detail: { background: "前118年分国后，朱古达以贿通罗马贵人，屡侵东邻阿德尔巴；阿德尔巴求援于在努米底亚的罗马商人与包税人。", process: "前112年围基尔塔，城陷杀阿德尔巴及城内曾助其守战的意大利与罗马商人；罗马前111年宣战，执政官贝斯提亚受赂而许朱古达降，其养子马西瓦在罗马被刺杀，公愤始成。", impact: "一桩外邦王位之争变成罗马公庭与法庭的丑闻，勒索常庭审办多名元老；骑士与元老在陪审权上的争角由此明朗。", figures: ["朱古达", "阿德尔巴", "马西瓦"], place: "基尔塔、罗马", state: "努米底亚王国与罗马共和国", sources: ["萨卢斯特《朱古达战争纪》第十六至二九章", "阿庇安《罗马史·努米底亚战纪》残篇"], tags: ["并国", "宣战", "公庭"] }, related: [] },
  { id: "world--b107--m01", track: "world", year: -107, yearApprox: true, dim: "military", weight: 4, title: "马略募无产者改制", summary: "破财产格募兵，队制与鹰旗始定。", detail: { background: "非洲与辛布里两线并用，按财产册定兵役已召不满；前二世纪末意大利小农破产，无产者日众。", process: "前107年马略任执政官赴非洲，破格收无地平民入伍，器甲给于公库；军中行三个大队为一群的营组制，鹰旗为一队之徽，工兵与辎重自随，士官久任。", impact: "兵役由公民财产义务变为取饷之业，士兵的饷、赏与退役置地系于其统帅；共和国的武装忠诚由此转向个人，内战之形已具。", figures: ["盖乌斯·马略"], place: "罗马与非洲努米底亚", state: "罗马共和国", sources: ["萨卢斯特《朱古达战争纪》第六三至八六章", "普鲁塔克《马略传》第四至九章"], tags: ["募兵", "营制", "鹰旗"] }, related: [] },
  { id: "world--b105--m01", track: "world", year: -105, yearApprox: false, dim: "military", weight: 3, title: "阿劳西奥惨败", summary: "两帅不相下，八万众溃于罗讷河。", detail: { background: "辛布里与条顿等族由罗讷上游西下，与罗马两路军隔河相持；罗马使臣傲拒其迁地之请，战端复起。", process: "前105年十月，执政官马克西穆斯与前执政官阿劳奥互争首功，分营两处、地隘水乏；辛布里先击其偏营，两军俱溃，渡河者多溺，据古载连随营之人死八万，图卢兹神庙的金库亦被夺。", impact: "为罗马史上奇败，元老院行摄事之制、禁公民向俘虏探问敌情；高卢与西班牙门户洞开，马略由此独握兵权至前100年。", figures: ["格涅乌斯·马利乌斯·马克西穆斯", "昆图斯·塞尔维利乌斯·阿劳奥", "盖乌斯·马略"], place: "阿劳西奥（今法国奥朗日）", state: "罗马共和国", sources: ["普鲁塔克《马略传》第十七至二一章", "奥罗修斯《反异教史纲》卷五"], tags: ["惨败", "双帅", "禁问"] }, related: [] },
  { id: "world--b103--i01", track: "world", year: -103, yearApprox: false, dim: "institution", weight: 3, title: "拉巴利乌斯法设叛逆常庭", summary: "以骑士与老兵陪审，罪及逆罗马人民。", detail: { background: "格拉古之后两党以法庭相攻；马略与保民官萨图尔尼努斯合作，需一常设之刑庭以处权贵。", process: "前103年保民官拉巴利乌斯立法，设“逆罗马人民之罪”常庭，所诉者或由元老院或由公民会定之，陪审名额归骑士与马略老兵，罪得流刑，另以低价粮法与殖民地法相济。", impact: "罗马把政争常规化为刑事审判，元首时代的大逆罪法实由此出；骑士陪审之制亦使苏拉与马略两党围绕法庭反复立法。", figures: ["卢基乌斯·阿普列乌斯·萨图尔尼努斯", "盖乌斯·马略", "昆图斯·塞尔维利乌斯·阿劳奥（被审者）"], place: "罗马", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷一", "特罗古斯《腓力史》译本残篇"], tags: ["常庭", "陪审", "大逆"] }, related: [] },
  { id: "world--b101--m01", track: "world", year: -101, yearApprox: false, dim: "military", weight: 4, title: "维尔切莱会战灭辛布里", summary: "骑兵抄背，一族之众覆于波河谷。", detail: { background: "辛布里人由高卢入意大利北，求地而不得；马略第六次任执政官，与前执政官卡图卢斯合军相拒。", process: "前101年七月在维尔切莱平原会战，罗马骑兵绕击其侧背，辛布里军溃入营垒；据普鲁塔克载死者数万、被虏近二万，妇人多自尽。条顿一族前一年已败于塞纳河畔，其王自经。", impact: "阿尔卑斯山外的侵扰一时扫清，罗马在北意的殖民与征兵恢复；马略功名比于坎尼之复，职业老兵遂以胜军自重。", figures: ["盖乌斯·马略", "昆图斯·卢图卢斯·卡图卢斯"], place: "维尔切莱（今皮埃蒙特韦尔切利）", state: "罗马共和国", sources: ["普鲁塔克《马略传》第二一至二三章", "弗洛鲁斯《罗马史纲要》卷三"], tags: ["会战", "灭族", "军功"] }, related: [] },
  { id: "world--b100--p01", track: "world", year: -100, yearApprox: false, dim: "politics", weight: 3, title: "萨图尔尼努斯法与罗马巷战", summary: "以武装阻选举，元老院命执政官出兵。", detail: { background: "马略欲酬老兵而不得地，与保民官萨图尔尼努斯、格劳提亚结为三人为政之局；反对派以征兆与阻会相抗。", process: "前100年三人提非洲殖民地法与低价粮法，并以立法责元老宣誓奉行；选举日两党斗殴，一人被杀，元老院首次通过“最终劝告”；执政官马略断水道、攻阿芬丁山神庙，焚杀数千人。", impact: "罗马第一次以城内武装了结公民表决，非常手段成党争通例；马略由平民派魁首转为体面秩序之守，两方皆失其信。", figures: ["卢基乌斯·阿普列乌斯·萨图尔尼努斯", "盖乌斯·马略", "盖乌斯·塞尔维利乌斯·格劳提亚"], place: "罗马阿芬丁山", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷一", "特罗古斯《腓力史》译本残篇第六五章"], tags: ["粮法", "巷战", "最终劝告"] }, related: [] },
  { id: "world--b96--p01", track: "world", year: -96, yearApprox: false, dim: "politics", weight: 3, title: "昔兰尼加依遗归罗马", summary: "王无嗣以国遗罗马，五城受其监护。", detail: { background: "托勒密家在昔兰尼加的分支王托勒密·阿皮翁前96年卒，无后；其国自前322年起历为托勒密分支采邑。", process: "遗嘱将其国与昔兰尼、巴尔刻、欧斯佩拉、欧埃斯佩里迪斯、安提巴尔卡五希腊城遗与罗马人民；罗马受而不即设省，令诸城自治、遣吏理其赋与讼，海盗与犹太侨民之争入其公堂。", impact: "罗马以遗嘱取得北非沿海与商路，此后“遗赠”成其东方扩省之常法；其特产细麻与阿魏入地中海市场，粮区亦渐隶罗马。", figures: ["托勒密·阿皮翁"], place: "昔兰尼加（今利比亚东部绿山区）", state: "昔兰尼加与罗马共和国", sources: ["斯特拉波《地理学》第十七卷论昔兰尼", "昔兰尼城里奥塔铭文辑录"], tags: ["遗赠", "五城", "监护"] }, related: [] },
  { id: "world--b91--p01", track: "world", year: -91, yearApprox: false, dim: "politics", weight: 4, title: "同盟者战争起", summary: "公民权不成，意大利诸邦脱罗马另立国会。", detail: { background: "意大利同盟者为罗马供大半兵员而无公民权与公有地之份；格拉古以来屡议不果，前122年之败为前例。", process: "前91年保民官德鲁苏斯以公民权法案联意大利人，未行而被刺；马尔西人与马鲁基尼等举兵，联盟都科尔菲尼乌姆而改名“意大利”，铸牛踏狼之银币，得兵十万，陷贝内文图姆等地，两名执政官一死一败。", impact: "罗马两线受兵（另有本都与色雷斯），以公民权换统一；前89至前82年间意大利诸邦依次入籍，拉丁制度与罗马籍遂遍于半岛。", figures: ["马尔库斯·路斯基乌斯·德鲁苏斯", "潘皮戴乌斯（马尔西人统帅）", "拉维尼乌斯（马鲁基尼人首领）", "韦提乌斯·斯卡托"], place: "科尔菲尼乌姆（今阿布鲁佐科尔菲尼奥）", state: "罗马共和国与意大利同盟", sources: ["阿庇安《罗马史·同盟者战争》残篇", "狄奥多罗斯《历史丛书》第三七卷摘"], tags: ["同盟者", "内战", "另立国会"] }, related: [] },
  { id: "world--b89--i01", track: "world", year: -89, yearApprox: false, dim: "institution", weight: 5, title: "两法定意大利公民权", summary: "以入籍拆起义联盟，山南高卢亦得籍。", detail: { background: "同盟者战争不能速决，罗马需分化起义者与仍效忠之邦；统帅者亦须定兵源与税基。", process: "前90年尤利乌斯法许效忠及两月内归顺的意大利同盟者以罗马公民权；前89年巴皮里亚法许阿尔卑斯山南高卢人及定居意大利者，于六十日内向城市裁判官呈籍。", impact: "罗马由一城之邦化为多城共籍之体，兵源、赋役与市政制度统一于半岛；此例开后世渐次扩籍之途，至二一二年遂及全帝国。", figures: ["卢基乌斯·尤利乌斯·凯撒（前90年执政官）", "普布利乌斯·巴皮里乌斯·卡尔博（保民官）"], place: "罗马与意大利诸邦", state: "罗马共和国", sources: ["阿庇安《罗马史·同盟者战争》残篇", "西塞罗《为巴尔布斯辩》第九至一三节"], tags: ["公民权", "呈籍", "扩籍"] }, related: [] },
  { id: "world--b88--p01", track: "world", year: -88, yearApprox: false, dim: "politics", weight: 3, title: "亚细亚一日诛罗马寓户", summary: "本都王令诸城同日杀意大利籍人。", detail: { background: "米特拉达梯六世取小亚细亚西部，罗马的包税人、债主与移民广占田宅、勒征船役，东方积怨已久。", process: "前88年五月七日，王以书令各城同日杀“意大利籍人”，据阿庇安载死者八万，另有四万之说；以弗所、佩加蒙等城皆行，债契与税册被焚，曼尼乌斯统其军入色雷斯。", impact: "罗马自此以“为死者复仇”为东征之名，米特拉达梯两度败亡后小亚细亚诸城罚赋废币；此案亦照出行省债与船役之重。", figures: ["米特拉达梯六世尤帕托", "曼尼乌斯（罗马将领）"], place: "以弗所、佩加蒙等亚细亚诸城", state: "本都王国与罗马共和国", sources: ["普鲁塔克《苏拉传》第二三至二四章", "阿庇安《罗马史·米特拉达提战纪》第二三至二五章"], tags: ["同日诛", "债契", "复仇之名"] }, related: [] },
  { id: "world--b87--m01", track: "world", year: -87, yearApprox: false, dim: "military", weight: 3, title: "苏拉围雅典与比港", summary: "围城断粮，破希腊城邦之反。", detail: { background: "雅典迎本都所立之王而杀亲罗马者，罗马命苏拉东征；苏拉先定贝奥提亚与雅典之盟，前87年冬入阿提卡。", process: "前87年冬围雅典与比雷埃夫斯，断水道与粮路，城内以皮带草木为食；前86年三月由埃吉提俄斯内应登墙，纵兵入城，旋即止杀，掠公库与城中库房以赏军。", impact: "希腊城邦以拥立王侯抗拒罗马之策终败，雅典政治独立尽失；罗马将领以东方为功名之场，兵随将走的格局自此定型。", figures: ["卢基乌斯·科尔涅利乌斯·苏拉", "阿里斯提翁（雅典使者）", "阿尔凯劳斯（本都将领）"], place: "雅典、比雷埃夫斯", state: "罗马共和国与雅典", sources: ["普鲁塔克《苏拉传》第一二至一四章", "阿庇安《罗马史·米特拉达提战纪》第三一至三八章"], tags: ["围城", "断粮", "内应"] }, related: [] },
  { id: "world--b86--e01", track: "world", year: -86, yearApprox: true, dim: "economy", weight: 3, title: "公民普查册数跃增", summary: "入籍者众，普查得册卅七万余。", detail: { background: "同盟者战争与公民权法使数十万意大利人入籍；监察官需重定部落、征兵与粮册。", process: "前86年监察官宣称公民册数三七六、六三一人，较前131年约卅一万七千为大增；呈籍须向城市裁判官陈报，伪籍与代籍之讼频起，山南高卢诸城之籍累年不决。", impact: "公民共同体一时扩大，罗马城的粮、救济与部落表决秩序受压；行省上层竞求罗马籍，籍贯与等级成为帝国行政的骨架。", figures: ["卢基乌斯·马尔基乌斯·卡尔苏拉（前86年监察官）", "马尔库斯·埃米利乌斯·雷必达"], place: "罗马与意大利诸邦", state: "罗马共和国", sources: ["布林特《意大利人力》所辑普查表", "阿庇安《罗马史·内战史》卷一"], tags: ["普查", "入籍", "伪籍"] }, related: [] },
  { id: "world--b82--i01", track: "world", year: -82, yearApprox: false, dim: "institution", weight: 4, title: "苏拉的独裁立法", summary: "以法复位元老院，削保民官与行省兵权。", detail: { background: "马略党前87年据罗马，反行公敌宣告；苏拉前83年自希腊返意，前82年十一月内战终，前82至前81年任独裁官以立定章。", process: "马略党数百元老与骑士被杀或放逐，其子孙不得任官；元老额增至六百，勒索庭与诸常庭陪审归元老，保民官提案先经元老院议，前任长官不得再求连任，统兵者不得离省。", impact: "权力天平自公民大会移回元老院，共和之名复位而实已凭兵；其恩主—老兵网络反而养出后继之内战，制度三十年而坏。", figures: ["卢基乌斯·科尔涅利乌斯·苏拉·费利克斯"], place: "罗马", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷一第49至104节", "西塞罗《为塞亚斯辩》论苏拉诸法"], tags: ["独裁官", "复位", "削保民官"] }, related: [] },
  { id: "world--b82--e01", track: "world", year: -82, yearApprox: false, dim: "economy", weight: 3, title: "公敌宣告与意大利夺田", summary: "列名者赏格可杀，其地分给老兵。", detail: { background: "苏拉须酬从征之二十余军团，亦须永除敌党之资；意大利公有地与没收地为其财源。", process: "前82年列名宣告公敌，据阿庇安载列元老三百、骑士二千，被杀四千余；赏格取首，没其产与子之继承权；以没收地与公有地在二十余区分老兵，坎帕尼亚与伊特鲁利亚良田大半易主。", impact: "意大利的小农与公有地制度被终结式地清扫，大地产与奴隶庄园加速；退伍置地成此后罗马军政的恒久题目，直至共和国之亡。", figures: ["卢基乌斯·科尔涅利乌斯·苏拉", "马尔库斯·李锡尼·克拉苏（因宣告而致富）"], place: "罗马、坎帕尼亚、伊特鲁利亚", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷一第96至104节", "普鲁塔克《苏拉传》第二七至三二章"], tags: ["没收", "老兵地", "大地产"] }, related: [] },
  { id: "world--b81--i01", track: "world", year: -81, yearApprox: false, dim: "institution", weight: 3, title: "苏拉的刑名与省法", summary: "常庭分罪定章，总督限期出省。", detail: { background: "内战之后罗马需固定的刑名与行政规条，替代历年以“最终劝告”从事之便。", process: "前81年前后以柯尔涅利亚诸法分定凶杀投毒、伪造印章、行省勒索、侵夺公物等常庭与刑程，法务官额增为八；另定总督不得携军离省、须按期交防，行省诉讼有定格。", impact: "罗马刑法第一次成为分目的常庭体系，行省治理有可援之条；此制延入帝政，仍是后世欧洲大陆刑法分目的底本。", figures: ["卢基乌斯·科尔涅利乌斯·苏拉"], place: "罗马与各属省", state: "罗马共和国", sources: ["苏拉致希腊诸城书铭刻（德尔斐所出）", "西塞罗《为罗西安努斯辩》所引省法"], tags: ["常庭", "刑法", "交防"] }, related: [] },
  { id: "world--b78--f01", track: "world", year: -78, yearApprox: false, dim: "figure", weight: 3, title: "苏拉退位与死", summary: "自解独裁之权，翌岁病卒于坎帕尼亚。", detail: { background: "苏拉前80年与梅特路斯同任执政官，行省与法庭之制已定，党人多盼其久任。", process: "前79年入公民大会自陈解权之故，无人应声而笑其迂；退隐普图奥利撰自传，前78年病卒，雷必达举兵时元老院请其复出，不许；国葬于马尔提乌斯场。", impact: "罗马史上唯一自解非常权力而全身者，成后世评议权与制的例证；其制度在其死后卅五年崩，兵与将的私属问题未解。", figures: ["卢基乌斯·科尔涅利乌斯·苏拉", "马尔库斯·埃米利乌斯·雷必达（前78年起事者）"], place: "普图奥利（今波佐利一带）", state: "罗马共和国", sources: ["普鲁塔克《苏拉传》第三六至三八章", "苏拉自传残篇辑"], tags: ["解权", "自传", "国葬"] }, related: [] },
  { id: "world--b73--m01", track: "world", year: -73, yearApprox: false, dim: "military", weight: 3, title: "卡普阿角斗士逸走", summary: "七十余武奴破库上山，义军两岁成六万。", detail: { background: "本都战争需兵，意大利角斗业方盛；卡普阿的武奴训所蓄人数百，多以色雷斯、高卢、日耳曼战俘充之。", process: "前73年约七十名角斗士破武库逸上维苏威山，立斯帕塔库斯（曾入罗马辅助军的意大利人）、克利克索斯与甘尼克斯为首；破前哨取械，意大利牧奴与贫民来归，得牛马与罗马兵器。", impact: "罗马后方暴露奴隶制之本伤，两年内众至数万，两执政官军屡败；克拉苏得专任之命，罗马此后不敢以少兵置意大利于不顾。", figures: ["斯帕塔库斯", "甘尼克斯", "克利克索斯", "普布利乌斯·瓦尔吉尼乌斯（训头）"], place: "卡普阿、维苏威山", state: "罗马共和国", sources: ["普鲁塔克《克拉苏传》第八至九章", "弗洛鲁斯《罗马史纲要》卷二论奴隶战争"], tags: ["角斗士", "武库", "义军"] }, related: [] },
  { id: "world--b71--m01", track: "world", year: -71, yearApprox: false, dim: "military", weight: 4, title: "斯帕塔库斯军覆灭", summary: "阿普利亚决战，六千人钉于阿庇亚道。", detail: { background: "义军两度欲渡海入西西里不果，前72年北上阿尔卑斯而复南还，罗马以克拉苏专任，召庞培自西班牙北来合围。", process: "前71年在布鲁提乌姆断垒北走，破克拉苏两部将及其副；最后在塞里斯河（今布拉达诺河）一带三面合击，义军主力覆，据古载死者六万，斯帕塔库斯尸莫获；沿阿庇亚道立十字架六千。", impact: "意大利再无十万级奴隶战争，克拉苏以“最后者”自名而拥重兵与庞培并立；罗马上层对奴隶之惧入其立法与家防之制。", figures: ["斯帕塔库斯", "马尔库斯·李锡尼·克拉苏", "格涅乌斯·庞培"], place: "阿普利亚，塞里斯河畔", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷一第116至120节", "普鲁塔克《克拉苏传》第九至一一章"], tags: ["决战", "十字架", "两将并立"] }, related: [] },
  { id: "world--b70--f01", track: "world", year: -70, yearApprox: false, dim: "figure", weight: 3, title: "西塞罗控维雷", summary: "无军功的新人以讼辞倾行省总督。", detail: { background: "西西里总督维雷在任三年，掠雕像、库金与粮额；省民依勒索常庭控之，辩护人欲拖至次年以图免。", process: "前70年九月初开庭，控方三日呈证并自叙证于叙拉古，庭前宣读第一讼辞，证人云集；维雷未判而自流放马赛利亚，携财巨万；西塞罗旋刊五篇讼辞，并自赴其地核账。", impact: "行省勒索有了公开的叙事与量刑参照，西西里粮额与雕像得归；一“新人”以辩才取罗马声望，成其执政官之路的起点。", figures: ["马尔库斯·图利乌斯·西塞罗", "盖乌斯·维雷", "盖乌斯·凯基利乌斯（主审法官）"], place: "罗马、叙拉古", state: "罗马共和国", sources: ["西塞罗《反维雷》五篇讼辞", "阿斯孔尼乌斯《演说注》维雷案条"], tags: ["勒索庭", "讼辞", "新人"] }, related: [] },
  { id: "world--b66--m01", track: "world", year: -66, yearApprox: false, dim: "military", weight: 3, title: "米特拉达梯末败", summary: "吕库斯河一败，本都王统六百年而绝。", detail: { background: "第三次米特拉达梯战争自前73年起；前67年以马尼利亚法尽授庞培海上与东方指挥权，罗马重整舰队。", process: "前66年在吕库斯河（今克尔勒河）畔破其军，王退亚美尼亚、再走科尔基斯，前63年在塞巴斯托波里（今索呼姆一带）自尽；其长子马哈尔斯献国，本都西境并入比提尼亚行省。", impact: "罗马东界推至黑海南岸，锡诺帕斯等希腊港与粮道入其商网；小亚细亚行省、附庸王与自由城三重体制并行之局自此定。", figures: ["米特拉达梯六世尤帕托", "格涅乌斯·庞培·马格努斯", "马哈尔斯"], place: "吕库斯河、阿马斯特拉", state: "罗马共和国与本都王国", sources: ["阿庇安《罗马史·米特拉达提战纪》第九二至一一五章", "斯特拉波《地理学》第十二卷论本都"], tags: ["末代", "黑海", "献国"] }, related: [] },
  { id: "world--b64--p01", track: "world", year: -64, yearApprox: false, dim: "politics", weight: 3, title: "叙利亚设为罗马行省", summary: "废塞琉古末王，东地中海王国体系终。", detail: { background: "塞琉古家自安条克四世后内乱不绝，腓尼基与柯里叙利亚诸城请罗马为断；庞培在东定其秩序。", process: "前64年庞培入安条克，废末王腓力二世及其子，以其地为行省；划奇里乞亚、腓尼基与十城联盟隶之，犹地亚、以土买与纳巴泰诸族王、族长各为其附庸。", impact: "希腊化大国之局自此收束，罗马以城邦网、驻防与附庸三线而治东方；此后犹太与帕提亚之事端皆在行省界线上发生。", figures: ["格涅乌斯·庞培·马格努斯", "腓力二世（塞琉古末王）", "许尔干二世"], place: "安条克（今土耳其安塔基亚）", state: "罗马共和国与叙利亚行省", sources: ["约瑟夫斯《犹太古史》第十四卷", "阿庇安《罗马史·叙战纪》残篇"], tags: ["设省", "附庸", "废王"] }, related: [] },
  { id: "world--b63--p01", track: "world", year: -63, yearApprox: false, dim: "politics", weight: 4, title: "喀提林案与处决五党", summary: "以最终劝告绞公民，未经人民审判。", detail: { background: "苏拉老兵失地、意大利负债者与失势贵族相纠；喀提林前63年再竞执政官不遂，被人告于新任执政官西塞罗。", process: "前63年秋喀提林北走埃特鲁利亚募兵，罗马城内五同党图焚城劫粮船，事发后分寄于多名元老之家；十二月五日元老院议处死，恺撒主终身监禁，加图主即刑，议从加图；十二月十二日绞杀，喀提林旋败死于皮斯托利亚附近。", impact: "公民可否不经人民裁判处死成罗马百年之辩，前58年克洛狄乌斯立法逐西塞罗以复其冤；共和的法制底线第一次被公开跨越。", figures: ["马尔库斯·图利乌斯·西塞罗", "卢基乌斯·塞尔吉乌斯·喀提林", "小马尔库斯·波尔基乌斯·加图", "盖乌斯·尤利乌斯·恺撒"], place: "罗马、皮斯托利亚（今菲耶索莱附近）", state: "罗马共和国", sources: ["萨卢斯特《喀提林战争纪》第四六至六一章", "西塞罗《反喀提林》四篇演说"], tags: ["最终劝告", "处决", "放逐之报"] }, related: [] },
  { id: "world--b63--p02", track: "world", year: -63, yearApprox: false, dim: "politics", weight: 3, title: "庞培入耶路撒冷", summary: "围圣殿三月，犹地亚降为附庸。", detail: { background: "犹地亚许尔干二世与阿里斯托布鲁斯二世兄弟争大祭司位，各请罗马主持；庞培定叙利亚后东来。", process: "前63年罗马军围圣殿山三月，填壕破外郭；内城陷，据约瑟夫斯与塔西佗载士兵入圣所，庞培独自入至圣所而不取器物；许尔干称族长而不称王，加巴拉等外邦城归十城联盟管辖。", impact: "犹地亚自哈斯蒙尼独立之局转为罗马附庸，祭政权与民政合一于族长；圣殿山受外兵之辱入其集体记忆，为日后两次大起义远因。", figures: ["格涅乌斯·庞培·马格努斯", "许尔干二世", "阿里斯托布鲁斯二世"], place: "耶路撒冷", state: "罗马共和国与犹地亚", sources: ["约瑟夫斯《犹太古史》第十四卷", "塔西佗《历史》第五卷论庞培入至圣所"], tags: ["圣殿", "附庸", "围三月"] }, related: [] },
  { id: "world--b60--p01", track: "world", year: -60, yearApprox: true, dim: "politics", weight: 3, title: "前三头私约", summary: "三人互援分公职，共和铨政入私门。", detail: { background: "庞培须安置东方老兵与批其处置，克拉苏握东方包税人之财，恺撒求执政官与前高卢指挥；元老院对三人皆不肯尽信。", process: "前60年恺撒自近西班牙回罗马竞选，三人在会外相约为援；前59年恺撒任执政官，以土地法成老兵安置，并使庞培东方安排生效，另以法律护克拉苏之税约。", impact: "公职分配落入私盟之手，元老院的决议须在三人间取道；恺撒得五年高卢指挥，罗马扩张之锋由东方移向西北森林。", figures: ["盖乌斯·尤利乌斯·恺撒", "格涅乌斯·庞培", "马尔库斯·李锡尼·克拉苏"], place: "罗马", state: "罗马共和国", sources: ["普鲁塔克《恺撒传》第一三至一四章", "阿庇安《罗马史·内战史》卷一第四二至四七节"], tags: ["私盟", "公职", "高卢"] }, related: [] },
  { id: "world--b59--i01", track: "world", year: -59, yearApprox: false, dim: "institution", weight: 3, title: "恺撒土地法与宣誓案", summary: "以公民大会越元老，立法必宣誓奉行。", detail: { background: "前60年代罗马的公职、法庭与征地皆成僵局；保民官与贵族的街头相搏已数见。", process: "前59年恺撒提坎帕尼亚公有地与外省殖民地安置案，设二十人委员会督行；另以法使元老于五日内宣誓奉行其法，拒誓者加图被送出塞浦路斯理其王事；反暴力法使护民官不可侵成为刑条。", impact: "公民大会以兵与誓为具，立法之程序被制度化地绕过元老院；此法的老兵安置与殖民网成为帝政时代意大利与行省市政的蓝本。", figures: ["盖乌斯·尤利乌斯·恺撒", "马尔库斯·卡尔普尔尼乌斯·比布鲁斯（同执政官）", "小加图"], place: "罗马", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷一第四三至四六节", "西塞罗《阿提卡通信》卷一论宣誓法"], tags: ["土地法", "宣誓", "殖民委"] }, related: [] },
  { id: "world--b55--c01", track: "world", year: -55, yearApprox: true, dim: "culture", weight: 3, title: "《物性论》刊行", summary: "以拉丁长诗六卷写原子与文明渐进。", detail: { background: "伊壁鸠鲁学在罗马已有讲习与译述，士人读希腊文本；以韵文写哲理为罗马未见之业。", process: "全诗六卷：论自然之理与原子虚空，论感觉与心灵必死，论天地万象与星、云、雷、地震，论万物之种，论感官与性，论文明器物之渐积与宗教之惧；据古代记述其抄本经恺撒与西塞罗去取。", impact: "此为保存最完整的希腊化哲理长诗，亦拉丁哲理词汇之开端；其技艺由日用之需渐积之说，为古代少见之无神论文明史观。", figures: ["卢克莱修", "伊壁鸠鲁（所宗）", "梅米乌斯（献诗者）"], place: "罗马", state: "罗马共和国", sources: ["卢克莱修《物性论》六卷校勘本", "哲罗姆《编年史》前96与前54年条"], tags: ["原子论", "长诗", "文明渐进"] }, related: [] },
  { id: "world--b55--a01", track: "world", year: -55, yearApprox: false, dim: "art", weight: 3, title: "庞培石剧场落成", summary: "罗马第一座全石剧场，座位按等级。", detail: { background: "罗马旧只有木造看台，屡以火与拥挤为患；元老院前100至前50年代议拆私立看台而不能禁。", process: "前55年庞培以东方战利品建永久性石剧场于马尔提乌斯场，台后有高墙与神庙柱廊，据维特鲁威载其设机位与回声铜瓮之制；古载其可容万人以上，附游廊可避雨。", impact: "观众分区依身份等级被固定为空间秩序，帝国剧场之制由是定型；希腊化的柱厅、花园与神庙组合成罗马公共建筑的原型。", figures: ["格涅乌斯·庞培·马格努斯"], place: "罗马马尔提乌斯场", state: "罗马共和国", sources: ["维特鲁威《建筑十书》第五卷论剧场", "普鲁塔克《庞培传》第五五章论石剧场"], tags: ["石剧场", "等级座", "战利品"] }, related: [] },
  { id: "world--b55--s01", track: "world", year: -55, yearApprox: false, dim: "science", weight: 3, title: "十日内跨莱茵架桥", summary: "双排斜桩相撑，军团工程越日耳曼河。", detail: { background: "乌西佩特与藤克特里两族游动于莱茵左岸，前56年冬袭罗马营；恺撒欲以渡河示威，而河深水急、筏渡不能久。", process: "前55年春在下游处以去皮木桩斜打下双排，迎水与背水两侧以横木相撑，上置梁板；两岸筑垒封锁，据恺撒自述十日内成桥，渡河十八日，深入日耳曼境而还。", impact: "罗马第一次以工程在莱茵下游渡河，河界自此成军事与心理的分线；其桩法见于战记，为后世军用桥与墩台工程之成式。", figures: ["盖乌斯·尤利乌斯·恺撒"], place: "莱茵河中下游（今科隆—波恩一带）", state: "罗马共和国", sources: ["恺撒《高卢战记》第四卷第一六至一九章", "《剑桥古代史》第九卷论莱茵防务"], tags: ["军用桥", "斜桩", "十日程"] }, related: [] },
  { id: "world--b54--x01", track: "world", year: -54, yearApprox: false, dim: "explore", weight: 3, title: "罗马军再入不列颠", summary: "五百船渡海，泰晤士河后得质与贡。", detail: { background: "前55年恺撒首次以八十船渡海仅立滩头；不列颠的锡、牛皮与商业传闻在罗马已久而无人能至其内陆。", process: "前54年以五百艘运兵船载五军团与二千骑，自莫尔凯海峡登陆，东进泰晤士河，破卡图维劳尼首领卡西维劳努斯的河岸木栅；其以车战与骚扰持久，诸王请和，纳质与所定岁贡后罗马北还。", impact: "罗马第一次取得不列颠东南的臣属与地理情报，锡与谷物的商路入其账目；此后近百年不列颠以贡物与货物存于罗马之议，至四三年再入。", figures: ["盖乌斯·尤利乌斯·恺撒", "卡西维劳努斯", "曼杜布拉库斯"], place: "肯特、泰晤士河北岸", state: "罗马共和国", sources: ["恺撒《高卢战记》第五卷第十二至二三章", "《剑桥古代史》第九卷论早期不列颠"], tags: ["渡海", "锡路", "纳质"] }, related: [] },
  { id: "world--b53--m01", track: "world", year: -53, yearApprox: false, dim: "military", weight: 4, title: "卡莱之败与鹰旗失落", summary: "弓骑续射断方阵，三头之一覆于美索不达米亚。", detail: { background: "卢卡续约后克拉苏求对帕提亚军功；帕提亚王奥罗德斯二世已定两河，遣苏雷纳斯拒之。", process: "前53年五月克拉苏渡幼发拉底而入无水的美索不达米亚，拒亚美尼亚王由山道入米底之议；在卡莱（今哈兰附近）遇万余弓骑以骆驼运箭续射、重甲骑兵冲击，十个军团结方阵不得展，据古载死者二万，被虏数千，鹰旗数枚与王首级送泰西丰。", impact: "罗马东界止于幼发拉底，帕提亚成与罗马对等之大邦，和约以河为线；鹰旗之辱成前20年奥古斯都外交胜事之题，三头均衡亦随克拉苏之死而解。", figures: ["马尔库斯·李锡尼·克拉苏", "苏雷纳斯（帕提亚统帅）", "奥罗德斯二世", "阿尔塔瓦兹德斯（亚美尼亚王）"], place: "卡莱（今土耳其哈兰附近）", state: "罗马共和国与帕提亚", sources: ["普鲁塔克《克拉苏传》第二三至三三章", "卡西乌斯·狄奥《罗马史》卷三九残篇"], tags: ["弓骑", "方阵", "鹰旗"] }, related: [] },
  { id: "world--b52--p01", track: "world", year: -52, yearApprox: false, dim: "politics", weight: 3, title: "克罗狄乌斯被杀于阿庇亚道", summary: "街头帮派杀保民官，元老院会场被焚。", detail: { background: "前50年代罗马的竞选以两帮青年团相袭，保民官制已为暴力所挟；克洛狄乌斯前58年立法逐西塞罗，与米洛世仇。", process: "前52年一月十八日米洛在波维莱附近杀克洛狄乌斯，其党以尸入罗马，焚库里亚会场与邻屋；罗马数月无长官，前52年秋庞培任独任执政官，以兵卫场。", impact: "选举与审判首次在士兵环列下举行，共和的公共空间被帮派与军队先后占据；恺撒在高卢闻之，双方摊牌开始计时。", figures: ["普布利乌斯·克罗狄乌斯·普克尔", "提图斯·安尼乌斯·米洛", "格涅乌斯·庞培"], place: "罗马与阿庇亚道", state: "罗马共和国", sources: ["阿斯孔尼乌斯《演说注》论米洛案", "阿庇安《罗马史·内战史》卷一第一一至一二节"], tags: ["帮派", "焚会场", "独任执政官"] }, related: [] },
  { id: "world--b52--m01", track: "world", year: -52, yearApprox: false, dim: "military", weight: 4, title: "阿莱西亚围破与高卢平定", summary: "两道围线十六公里，援军二十余万不解围。", detail: { background: "前52年罗马人在森农斯（今法国桑斯）的屠杀激起全高卢反，各邦在阿莱西亚推维辛热托里克斯为帅，共取粮与骑。", process: "前52年九月恺撒以约五万兵围阿莱西亚（今勃艮第阿尔萨），筑内围线十一罗马里（约十六公里）与外围线以拒援，壕、栅与五重陷阱俱备；外围援军据其自述号二十五万，两度合击不克，城降，其帅缚送罗马。", impact: "独立的高卢自此终结，罗马设省征税征兵，城镇、隶农与酒、陶之业随之而入；据古载其十年之战中高卢死与被虏者各百万，为古代征服之役损失最重者之一。", figures: ["盖乌斯·尤利乌斯·恺撒", "维辛热托里克斯", "哥班尼图（阿维尔尼老首领）"], place: "阿莱西亚（今勃艮第阿尔萨-圣兰）", state: "罗马共和国与高卢诸邦", sources: ["恺撒《高卢战记》第七卷第六六至八九章", "阿庇安《凯尔特战记》残篇（校订本）"], tags: ["围线", "援军", "设省"] }, related: [] },
  { id: "world--b50--s01", track: "world", year: -50, yearApprox: true, dim: "science", weight: 4, title: "吹管玻璃法之始", summary: "以铁管挑料吹泡，薄壁器自此可量产。", detail: { background: "此前玻璃以模铸与芯绕成形，器壁厚而费工贵；东地中海作坊久习熔融、退火与截管。", process: "约前一世纪中叶，叙利亚与腓尼基沿海的匠师以铁管挑取熔料吹泡成形，辅以钳夹、木模与印纹；安条克、西顿与后来的罗马作坊得一次成形薄壁之器，炉工与燃料大减。", impact: "玻璃由奢侈品变为日常储器，酒、油、膏药与香料皆有可封口之廉器；其法经拜占庭与伊斯兰工匠东传，罗马墓葬随葬品亦为之改观。", figures: ["西顿与安条克的无名匠师"], place: "叙利亚与腓尼基沿海", state: "罗马共和国东地中海", sources: ["老普林尼《自然史》第三六卷论玻璃成形", "大都会博物馆《玻璃史》卷一"], tags: ["吹管", "薄壁器", "量产"] }, related: [] },
  { id: "world--b49--p01", track: "world", year: -49, yearApprox: false, dim: "politics", weight: 4, title: "渡卢比孔河与内战起", summary: "一军团越界河，意大利不战而开门。", detail: { background: "恺撒的高卢指挥与竞执政官需在共和法下两全；元老院要求先散军，庞培一方备以“最终劝告”相逼。", process: "前49年一月七日谈判绝，保民官安托尼乌斯与库里奥夜奔恺撒营；十六日恺撒率第十三军团一列纵队渡卢比孔河（今鲁比孔内河），据苏埃托尼乌斯载其语“骰已掷下”；罗马长官与庞培党东渡海。", impact: "不设防的意大利诸邦依次开门，内战的形态由城内巷战变为跨海大决战；共和的最后二十六年自此始。", figures: ["盖乌斯·尤利乌斯·恺撒", "卢基乌斯·安托尼乌斯（保民官）", "格涅乌斯·庞培"], place: "卢比孔河（今鲁比孔内河）", state: "罗马共和国", sources: ["苏埃托尼乌斯《恺撒传》第三二章论渡河", "恺撒《内战记》卷一第一至五章"], tags: ["界河", "十三军团", "内战"] }, related: [] },
  { id: "world--b48--m01", track: "world", year: -48, yearApprox: false, dim: "military", weight: 4, title: "法萨卢斯会战", summary: "伏兵持矛侧击，庞培兵权一役而尽。", detail: { background: "前49年恺撒取西班牙与国库，前48年渡海至都拉基乌姆受困，旋弃辎重东入色萨利；庞培据粮道与舰势，不欲决战而为部将所促。", process: "前48年八月九日在法萨卢斯列阵，据恺撒自述以二万二敌六万；庞培以骑薄其左翼，恺撒预置第四列六千步兵持矛斜出，破骑后反击军团左后，庞培军溃入营，古载死万五千、降者众而多释；庞培走埃及。", impact: "兵权落于战胜之将，贵族党众不复能振；其宽释俘虏与元老子弟之策成“仁慈”的宣传，亦为其后被弑埋下怨。", figures: ["盖乌斯·尤利乌斯·恺撒", "格涅乌斯·庞培", "马尔库斯·安东尼"], place: "法萨卢斯（色萨利）", state: "罗马共和国", sources: ["恺撒《内战记》卷二第五一至五九章", "普鲁塔克《庞培传》第六一至七三章"], tags: ["伏兵", "以寡", "宽释"] }, related: [] },
  { id: "world--b48--p01", track: "world", year: -48, yearApprox: false, dim: "politics", weight: 3, title: "亚历山大里亚托勒密终局", summary: "追敌入埃及，王兄妹之战起。", detail: { background: "庞培败后求庇于埃及，廷臣杀之以献恺撒；埃及又拒付恺撒所索之款，兄妹共王者争位于尼罗河两岸。", process: "前48年秋恺撒入亚历山大里亚理其讼，克娄巴特拉七世夜入宫见；前47年三月亚历山大里亚之战，港区船坞与库房失火，部分藏书与货栈被及，托勒密十三世溺死于尼罗河；恺撒令克娄巴特拉与其幼弟共王。", impact: "罗马与托勒密家成庇护—婚姻之局，粮道之权入罗马内战的账目；港区火灾所及藏书之程度，史料异说，学界至今未有定论。", figures: ["盖乌斯·尤利乌斯·恺撒", "克娄巴特拉七世", "托勒密十三世", "波提努斯（摄政宦官）"], place: "亚历山大里亚", state: "托勒密埃及与罗马共和国", sources: ["普鲁塔克《恺撒传》第四九至五一章", "阿庇安《罗马史·内战史》卷二第一五三至一五九节"], tags: ["失火争议", "共王", "粮道"] }, related: [] },
  { id: "world--b46--s01", track: "world", year: -46, yearApprox: false, dim: "science", weight: 5, title: "儒略历颁行", summary: "以三百六十五日四年一闰定罗马之年。", detail: { background: "罗马旧历由祭司置闰，积乱已甚，节期、市集与农时错位；恺撒取埃及太阳历之法参以新制。", process: "前46年将该年展长为四百四十五日（据马克罗比乌斯载），以补前积之差；自前45年一月一日起行三百六十五日之年、四年益一日，月之分长短依新表，并以公法颁历日与市集历。", impact: "此历行于拉丁西方一千六百余年，为1582年格列高利改历之底本；罗马的民政、军饷与账目自此有统一之年表，与埃及尼罗河历并行。", figures: ["盖乌斯·尤利乌斯·恺撒", "索西革涅斯（亚历山大里亚算家）"], place: "罗马", state: "罗马共和国", sources: ["马克罗比乌斯《农神节》卷一第一三章论改历", "苏埃托尼乌斯《恺撒传》第40章论历"], tags: ["置闰", "太阳历", "年表统一"] }, related: [] },
  { id: "world--b46--i01", track: "world", year: -46, yearApprox: false, dim: "institution", weight: 3, title: "恺撒的公民与殖民立法", summary: "扩籍、复港、定省额，为共和末通盘之改。", detail: { background: "内战之后须安置老兵、整饬赋税与行省之治，而包税制与省额皆旧规。", process: "前46至前44年间立法：予山南高卢、西西里与西班牙诸城公民权或拉丁权；据苏埃托尼乌斯载移殖民众八万至科林斯、迦太基等旧墟；限现金与地产之偿债比例，裁并部分包税会社，行省定额定征。", impact: "罗马籍与拉丁籍的梯度成帝政地方制的骨架，西部两港在百年内复兴；行省负担有定数，是共和末期为数不多的全盘整饬。", figures: ["盖乌斯·尤利乌斯·恺撒"], place: "罗马、科林斯、迦太基", state: "罗马共和国", sources: ["苏埃托尼乌斯《恺撒传》第四二至四四章", "老普林尼《自然史》第三、五卷论殖民"], tags: ["扩籍", "移殖", "定赋"] }, related: [] },
  { id: "world--b44--p01", track: "world", year: -44, yearApprox: false, dim: "politics", weight: 4, title: "三月十五日弑恺撒", summary: "会堂二十余创，共和派无继之策。", detail: { background: "恺撒前44年任终身独裁官、拟亲征帕提亚；失位贵族、对其王号之惧与“解放者”之名相结于同僚之间。", process: "前44年三月十五日在庞贝会堂行刺，据古载预谋者约六十人，创二十余处，布鲁图斯与卡西乌斯为其名；同日公民大会通过其一切法令并许以和解，安东尼主持葬礼演说，民心转。", impact: "弑者既不能建政亦不能自制其党，罗马舆论归于为恺撒复仇；此后三年内战与共和体制之亡，皆起于此日留下的权力真空。", figures: ["盖乌斯·尤利乌斯·恺撒", "马尔库斯·尤尼乌斯·布鲁图斯", "盖乌斯·卡西乌斯·朗基努斯", "马尔库斯·安东尼"], place: "罗马庞贝会堂", state: "罗马共和国", sources: ["普鲁塔克《布鲁图斯传》第五至九章", "阿庇安《罗马史·内战史》卷二第113至120节"], tags: ["会堂", "葬礼演说", "真空"] }, related: [] },
  { id: "world--b44--c01", track: "world", year: -44, yearApprox: false, dim: "culture", weight: 4, title: "西塞罗的拉丁哲学著述", summary: "以译文造术语，希腊之学遂有拉丁之形。", detail: { background: "罗马士人多径读希腊文本，抽象概念无定译；恺撒死后西塞罗去职，转以著述应世。", process: "前46至前43年成《霍尔滕修斯》《学园题问》《图斯卡论辩》《论神性》《论卜筮》《论老年》《论友谊》与《论义务》（前44年冬）诸书，以拉丁语重铸希腊哲学术语，兼采学园、斯多亚与伊壁鸠鲁之说而断以己意。", impact: "拉丁自此可作哲学与神学语言，中世纪学校以之为课本；其论吏治与义务的伦理为近代欧洲政治教育所沿，术语沿用至今。", figures: ["马尔库斯·图利乌斯·西塞罗", "阿提库斯（出版与通信者）"], place: "罗马与图斯库姆别墅", state: "罗马共和国", sources: ["西塞罗《图斯卡论辩》《论义务》校勘本", "西塞罗《阿提卡通信》卷一三论著述之劳"], tags: ["译名", "对话体", "吏治伦理"] }, related: [] },
  { id: "world--b43--i01", track: "world", year: -43, yearApprox: false, dim: "institution", weight: 3, title: "第二次公敌宣告", summary: "三头列名二千余，十八城田土充军赏。", detail: { background: "前44年末屋大维入罗马结安东尼、雷必达；前43年十一月三人在博洛尼亚会订，旋以法律追认其权。", process: "前43年冬重行公敌宣告，据阿庇安载列元老三百、骑士二千，赏格取首、没其产、禁其子任官；以西塞罗为首被杀，首手钉于演说台；以十八座意大利城之田分给老兵。", impact: "意大利的土地与城市效忠一次翻定，老兵与征地的怨成为下一场内战的兵源；罗马再一次把非法之事付与合法之形。", figures: ["马尔库斯·安东尼", "屋大维", "马尔库斯·埃米利乌斯·雷必达", "马尔库斯·图利乌斯·西塞罗（被杀者）"], place: "罗马与意大利诸邑", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷四第1至21节", "苏埃托尼乌斯《奥古斯都传》第二七章论征地"], tags: ["宣告", "没产", "老兵征地"] }, related: [] },
  { id: "world--b43--e01", track: "world", year: -43, yearApprox: false, dim: "economy", weight: 3, title: "内战的捐税与随军铸币", summary: "什取一岁产，银匠营随军铸第纳尔。", detail: { background: "两方各拥三十余军团，国库在金库被夺后空虚；东方的城邑与王侯、意大利的地主皆为其财源。", process: "前43至前42年，三头向东亚细亚与叙利亚征两年之物产十一税并富人之捐，另勒城邑纳舟与质；屋大维在意大利以没收地给老兵；双方在移动中铸银第纳尔，加“军团”与将名之题铭，成色渐降。", impact: "军费由国库转入战胜者与城邑之口，东地中海之财西流；随军铸币成共和末期之特色，内战币的题铭与成色为后世考军团编制之据。", figures: ["马尔库斯·安东尼", "屋大维", "普布利乌斯·文提狄乌斯（东方筹饷者）"], place: "亚细亚行省、意大利", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷四、卷五论东方捐", "克劳福德《共和罗马币》卷一论随军铸币"], tags: ["十一税", "军铸币", "成色"] }, related: [] },
  { id: "world--b42--m01", track: "world", year: -42, yearApprox: false, dim: "military", weight: 3, title: "腓立比会战与共和终", summary: "两度会战，解放者军覆而共和派兵尽。", detail: { background: "布鲁图斯与卡西乌斯在东马其顿握十余军团，控海岸与金矿；三头两度渡海，第一次受阻于山地粮道。", process: "前42年十月两次会战于腓立比附近：第一次安东尼破卡西乌斯营，卡西乌斯误闻布鲁图斯败而自杀；二十日后第二次会战，布鲁图斯军溃自尽；据古载多名元老与二千骑士战死，腓立比遂为退役老兵殖民城。", impact: "共和派武装消灭，恺撒复仇之叙事闭合；战胜者在马其顿与亚细亚分地而治，屋大维与安东尼的东西分立已在事实之中。", figures: ["马尔库斯·尤尼乌斯·布鲁图斯", "盖乌斯·卡西乌斯·朗基努斯", "马尔库斯·安东尼", "屋大维"], place: "腓立比（马其顿）", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷四第118至137节", "普鲁塔克《布鲁图斯传》第三六至四六章"], tags: ["两度会战", "自尽", "殖民城"] }, related: [] },
  { id: "world--b36--m01", track: "world", year: -36, yearApprox: false, dim: "military", weight: 3, title: "纳劳库斯海战与粮道复", summary: "阿格里巴破塞克斯图斯于西西里，粮道复通。", detail: { background: "塞克斯图斯·庞培据西西里与撒丁，以其舰队断谷道，罗马斗米腾贵。", process: "前36年秋，阿格里巴在墨西拿海峡北口之纳劳库斯以三百五十船当其三百船；新制铁锚钩住敌船，继以撞角与接舷，一战沉其十四船、获三百船，塞克斯图斯与十余船逃本都。", impact: "西西里归屋大维辖境，据阿庇安载六千俘虏被处死；粮道既复，罗马海军自是常置船将。", figures: ["马尔库斯·维普萨尼乌斯·阿格里巴", "塞克斯图斯·庞培", "卢基乌斯·斯塔提乌斯·陶鲁斯"], place: "纳劳库斯（西西里北端，今墨西拿附近）", state: "罗马共和国", sources: ["阿庇安《罗马史·内战史》卷5第119至122节", "卡西乌斯·狄奥《罗马史》卷四九第19节"], tags: ["海战", "断粮", "船队"] }, related: [] },
  { id: "world--b31--m01", track: "world", year: -31, yearApprox: false, dim: "military", weight: 4, title: "亚克兴海战", summary: "屋大维与阿格里巴破安东尼与克娄巴特拉于希腊西岸。", detail: { background: "安东尼与屋大维决裂，前32年其遗嘱被夺而宣之于众；安东尼偕埃及王后屯希腊西岸，战舰三百余、步骑十万，意大利诸市则盟于屋大维。", process: "前31年9月2日两军遇于亚克兴前之海湾。阿格里巴建议引敌深入、断其粮道，安东尼不从；及战南风忽起，王后以六十船先出，安东尼随之，余众次日降。", impact: "明年亚历山大里亚陷，托勒密终；东地海不复有与罗马相抗之国，国政归于一人。", figures: ["盖乌斯·屋大维", "马尔库斯·安东尼", "克娄巴特拉七世", "马尔库斯·维普萨尼乌斯·阿格里巴"], place: "亚克兴（希腊西北阿克提昂岬，今普雷韦扎附近）", state: "罗马共和国", sources: ["普鲁塔克《安东尼传》第65至68章", "卡西乌斯·狄奥《罗马史》卷50至51"], tags: ["海战", "内战", "王后"] }, related: [] },
  { id: "world--b30--p01", track: "world", year: -30, yearApprox: false, dim: "politics", weight: 4, title: "埃及并入与托勒密终", summary: "屋大维取亚历山大里亚，埃及为元首私产之省。", detail: { background: "亚克兴后安东尼逃回京城，前30年春屋大维跟进；帕提亚与亚美尼亚之援俱不至，其势不复支。", process: "前30年7至8月，屋大维不攻而受降，亚历山大里亚开城；安东尼闻王后死讯自刎，克娄巴特拉七世寻亦自尽，托勒密王统（前305至前30年）于是终。", impact: "埃及划归元首私产，元老非诏不入；罗马谷米仰给尼罗河，东方诸城以是年为纪元之首。", figures: ["盖乌斯·屋大维", "克娄巴特拉七世", "托勒密十五世凯撒里昂"], place: "亚历山大里亚（埃及）", state: "罗马（埃及行省）", sources: ["普鲁塔克《安东尼传》第70至83章", "卡西乌斯·狄奥《罗马史》卷五一"], tags: ["王朝终", "私产省", "粮道"] }, related: [] },
  { id: "world--b27--p01", track: "world", year: -27, yearApprox: false, dim: "politics", weight: 5, title: "奥古斯都尊号与第一次让权", summary: "屋大维交还共和国之名，而受行省军权与尊号。", detail: { background: "内战既平，屋大维拥数十万之兵、领诸行省，而共和之名器犹存；前28年与阿格里巴同任监察，削元老之籍，造功业之录。", process: "前27年1月13日，屋大维于元老院前自陈让还国事于元老与罗马人民；元老院辞其所让，反以边省与驻兵之省尽委之，又加尊号“奥古斯都”。", impact: "名为共和之复，实为元首之立；后世以前27年为罗马帝代之始，兵权、护民权与行省统辖渐萃于一人。", figures: ["盖乌斯·屋大维", "马尔库斯·维普萨尼乌斯·阿格里巴"], place: "罗马（元老院）", state: "罗马", sources: ["《奥古斯都功德录》第34节", "卡西乌斯·狄奥《罗马史》卷五三第2至3节"], tags: ["尊号", "让权", "元首制"] }, related: [] },
  { id: "world--b25--s01", track: "world", year: -25, yearApprox: true, dim: "science", weight: 3, title: "维特鲁威《建筑十书》", summary: "献于元首之营造全典，并论火山灰胶与机械。", detail: { background: "屋大维崇于营造，玛尔库斯·维特鲁威·波利奥以前代阿基米德、克特西比乌斯诸家之工学会为一书，献于元首。", process: "十书分论制度与材料、神庙与市肆、住宅与铺地、粉刷、水权、日晷与机械；第九、十卷纪水车、螺旋提水器、起重车与弩机之制，又言火山灰调石灰可以水中硬结。", impact: "为中古以前唯一完整之建筑术书，文艺复兴后为欧洲营造之典；罗马之混凝土拱券与水道之法赖以传。", figures: ["玛尔库斯·维特鲁威·波利奥", "盖乌斯·屋大维"], place: "罗马", state: "罗马", sources: ["维特鲁威《建筑十书》卷二论材料、卷十论机械", "老普林尼《自然史》卷七论发明者"], tags: ["建筑术", "混凝土", "机械"] }, related: [] },
  { id: "world--b25--x01", track: "world", year: -25, yearApprox: true, dim: "explore", weight: 3, title: "阿格里巴舆图与国家刊布世界图", summary: "由国势测量而成的世界图，绘于罗马廊壁。", detail: { background: "前27至前25年，阿格里巴奉命巡察高卢、西班牙与东方诸省，测道里、录山川。", process: "以步测与航程定诸省相距之里数，辑为舆地之记三卷；其图后绘于罗马城北“大道之廊”壁上，以海、湖、山脉分区，旁注诸族之名与行旅之日程。", impact: "为罗马首次由国家刊布之世界图，老普林尼犹据以纪诸族；后世之行省籍册与驿路里程表皆沿其例。", figures: ["马尔库斯·维普萨尼乌斯·阿格里巴"], place: "罗马（城北大道廊壁画）", state: "罗马", sources: ["老普林尼《自然史》卷三第3至5节论阿格里巴之图", "斯特拉波《地理学》卷一首章论测绘"], tags: ["测绘", "舆图", "道里"] }, related: [] },
  { id: "world--b24--x01", track: "world", year: -24, yearApprox: true, dim: "explore", weight: 2, title: "加卢斯远征阿拉伯福地", summary: "两万罗马军越沙漠征也门，疫作而败还。", detail: { background: "罗马欲通红海与乳香之利，前26年前后命近卫长官埃琉斯·加卢斯统军二万，水陆并举，南征“福地阿拉伯”。", process: "自尼罗河上游之缪斯港出航，越沙漠而入西奈以南，围萨巴故地之城（今也门马里卜一带）；六十日不克，军中疫作，粮尽而退，归途循海道与陆道两路相会。", impact: "据斯特拉波载，是役死者万计，罗马终不得阿拉伯之谷；然红海航路与纳巴泰之要自此为罗马所知。", figures: ["埃琉斯·加卢斯", "盖乌斯·屋大维"], place: "阿拉伯福地（今也门马里卜一带）", state: "罗马", sources: ["斯特拉波《地理学》卷16第4章第23至25节", "老普林尼《自然史》卷12第77至80节论阿拉伯"], tags: ["远征", "红海", "乳香"] }, related: [] },
  { id: "world--b23--d01", track: "world", year: -23, yearApprox: false, dim: "disaster", weight: 3, title: "前23年罗马饥荒与元首重病", summary: "谷贵断粮，屋大维病中再让权，出帑购粮。", detail: { background: "前23年春，罗马谷价腾涌，市肆至无粟可粜；屋大维时方大病，几不起，都中流言以为天谴。", process: "病中复行让权之礼以安众心，遣亲信元老抚循民户，又出家财与国库之钱，就非洲、埃及购粮以粜；会秋雨至而饥解，疫亦渐平。", impact: "元首以一身当谷政之责，公粜与惠给遂为后世之常制；罗马粮政自是别置专官。", figures: ["盖乌斯·屋大维", "马尔库斯·维普萨尼乌斯·阿格里巴"], place: "罗马与意大利", state: "罗马", sources: ["卡西乌斯·狄奥《罗马史》卷五三第22节", "《奥古斯都功德录》第5节论购粮济民"], tags: ["饥荒", "谷价", "公粜"] }, related: [] },
  { id: "world--b23--i01", track: "world", year: -23, yearApprox: false, dim: "institution", weight: 4, title: "第二次权分之定与保民官权终身", summary: "元老院定元首之越常统领权与终身否决权。", detail: { background: "前23年病中，屋大维交还行省与军符；前次三年之约定满，实际兵权不可复失。", process: "元老院授其“越常统领权”，辖一切驻兵之省，位在诸巡抚之上；又定其保民官权终身，得否决诸官之令、召集元老院与民会；行省遂分为元首之省与公共之省，税与军、民各归有司。", impact: "罗马政制自是定形：元首不居王号而有军权、否决权与提案权，此后二百年之更替只在兵与元老之间。", figures: ["盖乌斯·屋大维", "马尔库斯·维普萨尼乌斯·阿格里巴"], place: "罗马（元老院）", state: "罗马", sources: ["卡西乌斯·狄奥《罗马史》卷五三第32至33节", "《奥古斯都功德录》第6至10节论权授"], tags: ["权授", "保民官权", "行省分治"] }, related: [] },
  { id: "world--b21--p01", track: "world", year: -21, yearApprox: true, dim: "politics", weight: 3, title: "麦罗埃女王之役与不贡和约", summary: "努比亚女王北掠上埃及，罗马许其不贡而和。", detail: { background: "上埃及与努比亚之地久为罗马税区；前29年麦罗埃（今苏丹北部舒姆一带）女王阿玛尼·雷尼斯率众北入埃及，毁底比斯诸像，杀所置长官。", process: "前22至前21年，埃及长官马尔库斯·佩特洛尼乌斯反攻，夺普提斯与托米斯，据斯特拉波载屠掠甚重；麦罗埃再遣使请和，屋大维许其不纳岁贡，边备寄于三瀑布诸屯。", impact: "麦罗埃之金、象牙与铁由此入罗马；南界以不贡之国为屏，二百年间无大战。", figures: ["阿玛尼·雷尼斯（麦罗埃女王）", "马尔库斯·佩特洛尼乌斯", "盖乌斯·屋大维"], place: "上埃及与麦罗埃（今苏丹默维附近）", state: "麦罗埃王国／罗马埃及", sources: ["斯特拉波《地理学》卷17第2章第45节", "塔西佗《编年史》卷12第55节论麦罗埃之使"], tags: ["南疆", "和约", "不贡"] }, related: [] },
  { id: "world--b20--p01", track: "world", year: -20, yearApprox: false, dim: "politics", weight: 3, title: "帕提亚归还鹰旗", summary: "弗拉特肆斯还克拉苏所失军器，东方划界。", detail: { background: "前53年卡莱之败，克拉苏军四万覆没，鹰旗与军器入帕提亚；前36年安东尼东征亦无功而还。", process: "前20年屋大维在叙利亚遣使复议，帕提亚王弗拉特肆斯四世以所获鹰旗与存活之俘虏归还；罗马以其还告于四方，铸币纪之，而不费一矢。", impact: "东方之界以幼发拉底河为定，罗马与帕提亚自此五十余年无大战；鹰旗之还被立为元首外交之极盛。", figures: ["盖乌斯·屋大维", "弗拉特肆斯四世"], place: "叙利亚与幼发拉底河界", state: "罗马／帕提亚", sources: ["《奥古斯都功德录》第4节论还鹰旗", "苏埃托尼乌斯《神圣奥古斯都传》第21章"], tags: ["归还", "和议", "铸币"] }, related: [] },
  { id: "world--b20--e01", track: "world", year: -20, yearApprox: true, dim: "economy", weight: 4, title: "印度洋直航与红海诸关税", summary: "依季风直渡阿拉伯海，出海商船百二十艘。", detail: { background: "托勒密世已通红海，而未敢横渡阿拉伯海；前2世纪末有人察季风之节，商路为之一变。", process: "前1世纪末，希腊系船长依相传“希帕鲁斯所识”之西南风，六月出红海之缪斯港与贝勒尼刻，冬初抵印度西北之巴里加札与穆齐利斯；斯特拉波同时见自缪斯港出海之商船犹百二十艘，屋大维定其港税，其率为货值四分之一。", impact: "胡椒、细布与宝石岁入罗马，老普林尼谓岁输印度、赛里斯与阿拉伯者共一亿塞斯特斯；东方之钱荒与罗马之侈用俱起。", figures: ["希帕鲁斯（传为识季风之船长）", "斯特拉波", "老普林尼"], place: "红海缪斯港至印度西北岸", state: "罗马／印度诸港", sources: ["斯特拉波《地理学》卷2第5章第11至12节", "老普林尼《自然史》卷12第41节论印度之市"], tags: ["季风", "直航", "关税"] }, related: [] },
  { id: "world--b19--a01", track: "world", year: -19, yearApprox: true, dim: "art", weight: 3, title: "希律重修耶路撒冷圣殿", summary: "垒石扩基、增廊与院，历八十载未毕。", detail: { background: "犹大王希律以外族临犹太之众，欲以崇构安民心且夸功于后世，乃谋广前代圣殿之制。", process: "前19年（一说前20年冬）始大作：展圣殿之山，垒巨石为台，建廊、院与门；虑旧器之惊动，先备新构而后徙，以祭司千五百人兼为工役；至公元70年焚而未毕。", impact: "其制为第二圣殿之极，坛之西墙为后世犹太祈祷之所；然科役繁重，民怨亦积于此。", figures: ["希律大王", "撒督系大祭司"], place: "耶路撒冷（圣殿山）", state: "犹大（希律王朝）", sources: ["约瑟夫斯《犹太战史》卷1第21章第1至6节", "约瑟夫斯《犹太古史》卷15第11节"], tags: ["圣殿", "垒台", "重役"] }, related: [] },
  { id: "world--b19--f01", track: "world", year: -19, yearApprox: false, dim: "figure", weight: 3, title: "维吉尔卒与埃涅阿斯纪遗刊", summary: "史诗十二卷，遗命焚之而元首不许。", detail: { background: "玛洛之维吉尔少作《牧歌》与《农事诗》，晚奉命写罗马建国之史诗，历十一年未定稿。", process: "前19年随屋大维自希腊还，病卒于布鲁迪萨姆（今布林迪西），年五十一；遗命尽焚《埃涅阿斯纪》，元首不许，命特路阿与鲁弗斯理其残次，定为十二卷、九千八百九十余行。", impact: "拉丁六音步史诗自是定体，罗马之天命与屋大维之家世以诗篇著于后世；其书为欧洲课读之本。", figures: ["普布利乌斯·维吉尔·玛洛", "盖乌斯·屋大维", "普布利乌斯·特路阿"], place: "布鲁迪萨姆（今布林迪西）", state: "罗马", sources: ["多纳图斯《维吉尔传》", "苏埃托尼乌斯《诗人传》论维吉尔"], tags: ["史诗", "遗稿", "诗律"] }, related: [] },
  { id: "world--b18--i01", track: "world", year: -18, yearApprox: false, dim: "institution", weight: 4, title: "尤利亚婚姻法", summary: "以国法课元老与平民婚育，罚无子与通奸。", detail: { background: "屋大维以风化复兴为务，贵族多不婚、无后，公民籍之数日减。", process: "前18年以保民官尤利乌斯·鲁福斯之提议通过：元老之子年二十五至六十、他民二十至五十当婚，无子者不得受非亲属之遗赠；父得杀行奸之女，夫得休之，并没其嫁资与产之三。", impact: "罗马首次以国法课婚育之责，其文累经增删，行六百年，后入于查士丁尼之汇编。", figures: ["盖乌斯·屋大维", "尤利乌斯·鲁福斯（保民官）"], place: "罗马（公民大会）", state: "罗马", sources: ["苏埃托尼乌斯《神圣奥古斯都传》第34章", "塔西佗《编年史》卷3论婚姻法之增删"], tags: ["婚姻", "继承", "风化"] }, related: [] },
  { id: "world--b15--e01", track: "world", year: -15, yearApprox: false, dim: "economy", weight: 3, title: "里昂铸币所与阿尔卑斯山道税", summary: "金银币移铸于卢格杜努姆，山道税二百取一。", detail: { background: "卢格杜努姆（今里昂）当罗讷与索恩之口，四道通阿尔卑斯诸谷，为高卢商旅之汇。", process: "前15年起，罗马之金银币移于该城铸造，面为元首之像、背为凯旋与祭祀之像，匠号署于币；同城设山道之税关，其率二百取一，商队过所给券，石刻所经诸部之名。", impact: "里昂遂为西土铸币与商路之枢；所刻山道名邑之表，今为研究阿尔卑斯诸部族之本。", figures: ["盖乌斯·屋大维", "德路苏斯", "提比略"], place: "卢格杜努姆（今法国里昂）", state: "罗马（高卢纳尔波南西斯）", sources: ["苏埃托尼乌斯《神圣奥古斯都传》第21章论移铸", "老普林尼《自然史》卷三论阿尔卑斯诸部"], tags: ["铸币", "关税", "山道"] }, related: [] },
  { id: "world--b12--i01", track: "world", year: -12, yearApprox: false, dim: "institution", weight: 3, title: "元首兼大祭司长与儒略历定闰", summary: "就大祭司长，停闰三十七以补祭司之误。", detail: { background: "前13年大祭司长雷必杜斯死；罗马历自凯撒改定以来，祭司误以三年一闰，节候已前差三日有余。", process: "前12年屋大维不以投票而以其权就大祭司长之任，祭政之权遂与元首合；又下令自今三十七年停闰以补前差，闰法归有司之册，不复出祭司之手。", impact: "儒略之历自是始定；据宏罗比乌斯所载，后以二月之日益八月，故二月见削而八月得全。", figures: ["盖乌斯·屋大维", "玛尔库斯·埃米利乌斯·雷必杜斯"], place: "罗马", state: "罗马", sources: ["宏罗比乌斯《农坛节谈》卷1第14章论误闰", "苏埃托尼乌斯《神圣奥古斯都传》第31章"], tags: ["闰法", "祭司权", "历制"] }, related: [] },
  { id: "world--b9--a01", track: "world", year: -9, yearApprox: false, dim: "art", weight: 3, title: "和平祭坛成于战神原", summary: "元老院为元首归来立坛，垣刻仪仗与地母。", detail: { background: "前16至前13年屋大维巡高卢与西班牙，还京，元老院为其“归来之幸”立坛于城北战神原。", process: "前9年坛成：坛垣外刻祭司仪仗、怀孕之地母与双牛之像，内刻船喙与三足鼎；岁有定祭，百年之会则陈乐与竞技。", impact: "元首之图像自此并行于币、像与盟誓之文，官仪与艺术相连；坛之残垣为罗马写实浮雕之范本。", figures: ["盖乌斯·屋大维"], place: "罗马城北战神原（今和平祭坛博物馆一带）", state: "罗马", sources: ["《奥古斯都功德录》第12节论和平祭坛与誓祭", "卡西乌斯·狄奥《罗马史》卷五一第20节论百年之会"], tags: ["浮雕", "仪仗", "誓祭"] }, related: [] },
  { id: "world--b8--f01", track: "world", year: -8, yearApprox: false, dim: "figure", weight: 2, title: "贺拉斯卒于罗马", summary: "颂歌四卷定拉丁诗律，与梅塞纳斯同年殁。", detail: { background: "昆图斯·贺拉西乌斯·弗拉库斯起于田家而受良师，内战中曾为共和军执盾，后得梅塞纳斯之助，入其文士之林。", process: "前8年11月卒，年四十五，同年梅塞纳斯亦殁；遗嘱以所服银盘留于元首之席，称其与元首为一日之友，葬于埃斯奎林门外。", impact: "其《颂歌集》四卷以爱奥利亚诸格写拉丁，为奥古斯都之世之辞；《诗艺》遂为古典批评之祖。", figures: ["昆图斯·贺拉西乌斯·弗拉库斯", "盖乌斯·梅塞纳斯"], place: "罗马", state: "罗马", sources: ["苏埃托尼乌斯《贺拉斯传》（载于古注本卷首）", "贺拉斯《书札》卷2第2首自述"], tags: ["颂歌", "诗论", "遗嘱"] }, related: [] },
  { id: "world--b7--i01", track: "world", year: -7, yearApprox: true, dim: "institution", weight: 3, title: "罗马城分十四区与置街区长", summary: "废旧界，定区号与街官，掌火警与小讼。", detail: { background: "罗马城累世因七山与村社之旧界，火警、盗贼与粮给无所统辖。", process: "约前7年分城为十四区，以编号为名，废旧之乡社；每区分街，置“街区长”以抽签补之，得司小讼、火警与市集之序；又增执法官四人任城事，巡夜之役隶焉。", impact: "罗马始有常设之市政与警政；其区号入于后世户籍与教会之界，今罗马之城区犹沿其地。", figures: ["盖乌斯·屋大维"], place: "罗马城", state: "罗马", sources: ["苏埃托尼乌斯《神圣奥古斯都传》第30章论分十四区与置街区长", "卡西乌斯·狄奥《罗马史》卷五五第8节"], tags: ["分区", "街政", "城官"] }, related: [] },
  { id: "world--6--p01", track: "world", year: 6, yearApprox: false, dim: "politics", weight: 3, title: "犹太废王为行省与户口之籍", summary: "亚基老被废，犹太归罗马巡抚与税籍。", detail: { background: "前4年希律王死，国分其三子；亚基老在犹大政刑苛暴，民两度遣使至罗马请废。", process: "公元6年，屋大维废亚基老而徙之于高卢之维埃纳，取其国三分之二为“犹太行省”，巡抚治所设于撒玛利亚之凯撒里亚；叙利亚巡抚居里尼乌斯行文造户口之籍，定岁赋之额。", impact: "犹太自此不复有王，赋役与祭政皆决于罗马之巡抚；籍户之令激成地方之怨，后世起义之讼端起于此。", figures: ["亚基老（希律之子）", "普布利乌斯·苏尔皮基乌斯·居里尼乌斯", "盖乌斯·屋大维"], place: "犹太（行辕在凯撒里亚）", state: "罗马（犹太行省）", sources: ["约瑟夫斯《犹太古史》卷17第10至11章", "约瑟夫斯《犹太战史》卷2第1章第1节"], tags: ["废王", "籍户", "行省"] }, related: [] },
  { id: "world--8--a01", track: "world", year: 8, yearApprox: false, dim: "art", weight: 3, title: "奥维德流放托弥", summary: "诗人以不明之罪放于黑海，写哀歌与变形记。", detail: { background: "普布利乌斯·奥维德·纳索以写情之诗名动京邑，入梅塞纳斯之后的文士之林；晚年忽得罪。", process: "公元8年，元首不宣其罪状，止称“诗与行之失”，放之于黑海西岸之托弥（今罗马尼亚康斯坦察）；其在戍写《哀歌》五卷与《书信集》四卷，又定《变形记》十五卷、一万一千九百余行。", impact: "拉丁哀歌与神话叙事诗集其书而一；中古以来欧洲之神话图说多出其手，“诗人见逐”亦成后世之典。", figures: ["普布利乌斯·奥维德·纳索", "盖乌斯·屋大维"], place: "托弥（今罗马尼亚康斯坦察）", state: "罗马", sources: ["奥维德《哀歌》卷1第1至10首自叙放逐", "塔西佗《编年史》卷1第10节论奥维德之见废"], tags: ["流放", "神话诗", "哀歌"] }, related: [] },
  { id: "world--9--m01", track: "world", year: 9, yearApprox: false, dim: "military", weight: 4, title: "条顿堡林三军团覆没", summary: "阿米尼乌斯伏击，瓦路斯与三军团尽。", detail: { background: "罗马之界自屋大维时推至易北，巡抚瓦路斯在日耳曼征赋行法、不习军情，诸部怨之。", process: "公元9年秋，凯路斯奇族长阿米尼乌斯导瓦路斯入条顿堡林之狭道，三日伏击；据塔西佗与狄奥所载，十七、十八、十九三军团与辅兵、随军之民二万余没，瓦路斯自杀，鹰旗入于敌手。", impact: "罗马自此不复图易北，以莱茵与多瑙为界；屋大维闻耗，数月不栉。其战场遗物今出于卡尔克尔里瑟山。", figures: ["普布利乌斯·昆克提利乌斯·瓦路斯", "阿米尼乌斯（凯路斯奇族长）", "盖乌斯·屋大维"], place: "条顿堡林（今德国奥斯纳布吕克附近卡尔克尔里瑟山）", state: "罗马／日耳曼诸部", sources: ["塔西佗《编年史》卷1第61至63节", "卡西乌斯·狄奥《罗马史》卷56第18至22节", "卡尔克尔里瑟山考古发掘报告（1980至21世纪）"], tags: ["伏击", "军团", "边界"] }, related: [] },
  { id: "world--14--p01", track: "world", year: 14, yearApprox: false, dim: "politics", weight: 4, title: "屋大维死与兵权移于新君", summary: "元首殁于诺拉，提比略得军誓与禁卫饷。", detail: { background: "屋大维晚年多病，13年与提比略同任监察官，明定其继；京中流言与粮政之扰未息。", process: "14年8月19日死于努拉（今诺拉），年七十有五；遗命陈尸于门前而葬于战神原。提比略即日受军团之誓与禁卫军之赏，然元老院之授权迟数月乃下，莱茵与多瑙两军先后要赏。", impact: "一君之替而不致内战，为元首制可以世袭之第一次验证；“凯撒”自此由族名转为君号。", figures: ["盖乌斯·屋大维", "提比略", "普布利乌斯·昆克提利乌斯·鲁弗斯（禁卫军长）"], place: "努拉与罗马（今诺拉、罗马）", state: "罗马", sources: ["塔西佗《编年史》卷1第1至18节", "苏埃托尼乌斯《神圣奥古斯都传》第97至101章"], tags: ["承替", "军誓", "世袭"] }, related: [] },
  { id: "world--30--c01", track: "world", year: 30, yearApprox: true, dim: "culture", weight: 5, title: "耶稣被钉与门徒之信", summary: "逾越节前钉于城外，空墓之闻起信众团契。", detail: { background: "加利利之耶稣约在27至29年间继施洗者约翰传道，以比喻说“上帝之国”，从者众，门徒十二。", process: "约30年（一说33年）逾越节前，在耶路撒冷被捕；巡抚本丢·彼拉多以“自称犹太人之王”之控钉之于十字架，同钉者二人。数日后妇女见墓石已滚，门徒自称复活后屡见之。", impact: "由是有一时之信众团契，自耶路撒冷散于叙利亚与小亚细亚；塔西佗记其名起于“基督”，其时彼拉多治犹太。", figures: ["耶稣", "本丢·彼拉多", "使徒彼得", "抹大拉之玛利亚"], place: "耶路撒冷城外各各他", state: "罗马（犹太行省）", sources: ["塔西佗《编年史》卷15第44章论基督之死", "约瑟夫斯《犹太古史》卷18第63至64节（后世传本或有增改）", "《新约·马可福音》第15章"], tags: ["受难", "逾越节", "团契"] }, related: [] },
  { id: "world--40--p01", track: "world", year: 40, yearApprox: false, dim: "politics", weight: 3, title: "征氏起于交趾", summary: "征侧征贰取六十五城，自立为王。", detail: { background: "汉之交趾、九真诸郡以郡中大姓承俗，太守苏定以汉法绳其豪右，众不相服。", process: "40年，麊泠县之征侧与其妹征贰起兵，诸蛮夷郡响应，取六十五城，征侧自立为王，都麊泠；汉遣将发兵，43年冬兵败被杀（一说徙于中原）。", impact: "征氏在越南史学中为立国之象，《大越史记全书》立“征王”之纪；其役亦为汉在南方用兵之费。", figures: ["征侧", "征贰", "苏定（交趾太守）"], place: "交趾（今越南北宁、河内一带）", state: "交趾郡（越北）", sources: ["《后汉书·马援传》《南蛮列传》", "《大越史记全书》外纪纪征王"], tags: ["越北", "自立", "郡政"] }, related: ["cn--43--x01"] },
  { id: "world--43--m01", track: "world", year: 43, yearApprox: false, dim: "military", weight: 4, title: "不列颠内属为行省", summary: "四军团渡海，克劳狄亲至受降。", detail: { background: "不列颠诸王内乱，流亡者至罗马请援；克劳狄欲立不世之功以安军心与元老之疑。", process: "43年，普劳提乌斯统四军团约二万五千人自布洛涅渡海，泰晤士河之战胜后迎元首亲至，携攻城之具与战象；诸部王降，南与中部之地内属为“不列颠行省”，都卡姆罗敦努姆（今科尔切斯特）。", impact: "不列颠自是入罗马之币、城与道路网，其谷、铅、银与奴隶出罗马；北境屯戍累世不息，八十年后始筑北墙。", figures: ["奥路斯·普劳提乌斯", "克劳狄乌斯皇帝", "托哥杜姆努斯（阿特雷巴特王）"], place: "不列颠东南（今肯特至科尔切斯特）", state: "罗马（不列颠行省）", sources: ["卡西乌斯·狄奥《罗马史》卷60第19至23节", "塔西佗《阿古利可拉传》第13章"], tags: ["渡海", "内属", "战象"] }, related: [] },
  { id: "world--49--c01", track: "world", year: 49, yearApprox: true, dim: "culture", weight: 3, title: "耶路撒冷会议与割礼之辩", summary: "使徒定外邦不责割礼，唯禁数事。", detail: { background: "信者中外邦人日众，有自法利赛派者谓非割礼不能得救，安提阿之会众遂遣巴拿巴与保罗上耶路撒冷质之。", process: "约49年（一说48年），使徒与长老大会于耶路撒冷，彼得、雅各与保罗各言所见；议定不加难外邦，只禁偶像之污、奸淫、勒死之牲与血，又分其任：保罗、巴拿巴往未受割礼者，彼得往受割礼者。", impact: "一束之界自犹太礼俗中分出，外邦之信始有凭据；后世教会会议之立法取其例。", figures: ["雅各（耶路撒冷之雅各）", "使徒彼得", "保罗", "巴拿巴"], place: "耶路撒冷", state: "犹太（早期信众团契）", sources: ["《新约·使徒行传》第15章第1至29节", "保罗《加拉太书》第2章第1至10节"], tags: ["会议", "割礼", "外邦"] }, related: [] },
  { id: "world--55--c01", track: "world", year: 55, yearApprox: true, dim: "culture", weight: 4, title: "保罗的外邦传教与书信", summary: "三度旅行立会诸港，书信定其说。", detail: { background: "大数之保罗少从迦玛列之门奉律法，后自谓见复活者，遂为外邦之使；以安提阿为出发之地。", process: "约50至57年间三度旅行，循爱琴海立会于非立比、帖撒罗尼迦、哥林多与以弗所；在哥林多十八月，以织帐自给；其与诸会书问往复，后辑入新约。", impact: "因信称义与“不分犹太、希利尼”之论由书信而定其说；东地海诸港之会众自此自立于犹太会堂之外。", figures: ["保罗（大数之扫罗）", "西拉", "提摩太", "亚居拉与百基拉"], place: "小亚细亚、马其顿与亚该亚诸城", state: "罗马（东地海行省）", sources: ["《新约·使徒行传》第16至20章", "保罗《罗马书》《加拉太书》"], tags: ["传教", "书信", "会众"] }, related: [] },
  { id: "world--60--s01", track: "world", year: 60, yearApprox: true, dim: "science", weight: 3, title: "希罗的气力机与自动器", summary: "以蒸汽转球、以气与水相推为戏器。", detail: { background: "亚历山大里亚之匠希罗承克特西比乌斯之气学，集前人之机而广之。", process: "其《气力论》载风箱、唧筒、以汽开寺门之器与以蒸汽转悬球之具；《测地术》述以镜定距、测不可到之远；《自动机》以凸轮、四连杆与垂重使偶像自作步骤。", impact: "蒸汽与气压之用于戏具与寺仪，未入产业，然其图解与齿轮之制为中古与近代欧洲机械学之所本。", figures: ["亚历山大里亚之希罗"], place: "亚历山大里亚（埃及）", state: "罗马（埃及行省）", sources: ["希罗《气力论》卷1第30至40章（传本）", "希罗《测地术》论镜测定距"], tags: ["气动", "自动机", "图解"] }, related: [] },
  { id: "world--60--x01", track: "world", year: 60, yearApprox: true, dim: "explore", weight: 4, title: "厄立特里亚海航行记与印度洋商表", summary: "一世纪商人之航务手册，列港程二百余。", detail: { background: "罗马商人在红海至印度之航岁以为常，前人所记航法、港程与货名渐集为一编。", process: "约60至70年（一说1世纪末），一旅埃及之希腊商以问答之体记自缪斯港与贝勒尼刻出发，历阿拉伯、波斯湾、印度西岸至恒河口之泊、水、市、货，并记丝料自“薄里古”溯河而上；所列港口二百有余。", impact: "为现存最早之印度洋航务手册，其货目即1世纪之贸易表：胡椒、细布、象牙、玛瑙、丝与葡萄酒、金币之出入俱在。", figures: ["佚名之埃及行商", "老普林尼（同时引其航说）"], place: "红海至印度与恒河诸港", state: "罗马（东地海行商）", sources: ["《厄立特里亚海航行记》第1至66章（传本）", "老普林尼《自然史》卷6论印度之市与港"], tags: ["航路", "港程", "货目"] }, related: [] },
  { id: "world--64--d01", track: "world", year: 64, yearApprox: false, dim: "disaster", weight: 4, title: "罗马大火与诿罪信众", summary: "火延六日七夜，尼禄以基督徒当怨。", detail: { background: "14区之中四区尽毁、七区半残，前一年谷价已贵；六月十九夜火起于战神原旁之商店。", process: "64年7月，火起于战神原旁之商店，延六日七夜；尼禄发帑、辟廊与田庄以徙民，减价粜谷，然都人相传火为帝所使，以辟其“巨室”之基。", impact: "火后刑“俗称为基督徒者”，以火人、犬噬与钉之示众；塔西佗斥其出于“一时之愤”，此为朝廷以信众当灾之始见。", figures: ["尼禄", "塞涅卡（时在朝）", "盖乌斯·彼得罗尼乌斯（朝臣）"], place: "罗马", state: "罗马", sources: ["塔西佗《编年史》卷15第38至44章", "苏埃托尼乌斯《尼禄传》第38章", "卡西乌斯·狄奥《罗马史》卷62第16至18节"], tags: ["火灾", "诿罪", "刑讯"] }, related: [] },
  { id: "world--64--e01", track: "world", year: 64, yearApprox: false, dim: "economy", weight: 3, title: "银币减质与军饷加额", summary: "尼禄减银币之重与成色，以济军费宫用。", detail: { background: "尼禄即位从塞涅卡之议，加禁卫军之赐以安其心；二年而国用不给，火后又大起宫室。", process: "64年令银币自八十四分之一磅改九十之一磅（约三克九减至三克三），含银自九成八削至九成三五，铜币含锌自九成五减至八成，金币亦减其重，而军饷之额自是加定。", impact: "以减质济军费，为后世累代递减之始；三世纪银币含银不足半成，物价之变与军饷之索相为表里。", figures: ["尼禄", "塞涅卡"], place: "罗马与里昂之铸币所", state: "罗马", sources: ["老普林尼《自然史》卷33第134节论尼禄之减银", "塔西佗《编年史》卷3第28节论减重之议", "现存尼禄银币系列之成分测定报告"], tags: ["减质", "军饷", "物价"] }, related: [] },
  { id: "world--65--f01", track: "world", year: 65, yearApprox: false, dim: "figure", weight: 3, title: "塞涅卡奉诏自尽", summary: "党狱无据而赐死，斯多亚之节死成典。", detail: { background: "科尔多瓦之塞涅卡为尼禄之傅，五年间与近臣同当国政，退身后著《道德书》与《自然问题》。", process: "65年皮索之谋泄，虽无据于塞涅卡，尼禄遣使赐死；其以腕脉、足脉出血而缓，又入温汤熏蒸而绝，遗言与口述皆由书记录之。", impact: "斯多亚之“择死”自是成为后世之文典；其悲剧十二种与哲理书信为拉丁散文之骨，千年间为欧洲学校之课。", figures: ["吕基乌斯·安内乌斯·塞涅卡", "尼禄"], place: "罗马", state: "罗马", sources: ["塔西佗《编年史》卷15第60至64章", "塞涅卡《道德书》第63、70、77篇论处死"], tags: ["党狱", "斯多亚", "自尽"] }, related: [] },
  { id: "world--66--m01", track: "world", year: 66, yearApprox: false, dim: "military", weight: 3, title: "犹太起义起", summary: "夺圣殿之堡，逐罗马驻军，四年之乱始。", detail: { background: "巡抚弗拉路斯在耶路撒冷纵兵取圣殿之库，祭司长与民相攻；税使克雷斯提乌斯在伯和仑遭劫而死，省乱已成。", process: "66年五月，圣殿卫戍夺罗马之堡，祭司长以利亚撒·本·亚拿理众，逐驻军；尼禄遣韦斯巴先统四军团下之，67至69年取加利利与犹大诸城，约瑟夫斯在约塔帕塔被围而降。", impact: "犹太之乱延四年，罗马一将军因之以得天下；城内诸派不相下，围城之时遂无可为守。", figures: ["韦斯巴先", "约瑟夫斯", "以利亚撒·本·亚拿（祭司长）"], place: "耶路撒冷与加利利诸城", state: "罗马（犹太行省）", sources: ["约瑟夫斯《犹太战史》卷2第17至19章、卷3第1至8章", "约瑟夫斯《自传》第1至16节"], tags: ["起义", "圣库", "围城"] }, related: [] },
  { id: "world--68--c01", track: "world", year: 68, yearApprox: true, dim: "culture", weight: 3, title: "马可福音写定", summary: "十六章之记事，为现存最早之福音书。", detail: { background: "信众之口传言说与使徒之记，须写定为书；罗马之会众方当尼禄之难，北方之传教正兴。", process: "约66至70年间（传统谓60年代末），一称玛尔古斯（约翰·马可）者辑成十六章、六百余节，以“上帝之子耶稣基督福音之起”为首句，终以空墓与遣使之命。", impact: "为现存最早之福音书，马太与路加皆据以增广；其“渐进之默示”与“隐秘之差事”二题自是定其体段。", figures: ["玛尔古斯（约翰·马可，传统之作者）", "使徒彼得（传统之所据）"], place: "罗马或叙利亚安提阿", state: "罗马（早期信众）", sources: ["《新约·马可福音》第1章第1节及其全书文例", "爱任纽《驳异端》卷3第1章论玛尔古斯之写"], tags: ["福音书", "写定", "口传"] }, related: [] },
  { id: "world--69--p01", track: "world", year: 69, yearApprox: false, dim: "politics", weight: 3, title: "一年四帝", summary: "加尔巴、奥托、维特里乌斯、韦斯巴先相代。", detail: { background: "尼禄死而无嗣，加尔巴以元老院所立，年七十有三，不能制军中之赏。", process: "69年1月加尔巴为禁卫军所杀，奥托称帝于罗马；4月贝特利亚库姆之役奥托败而自尽，维特里乌斯得意大利；7月韦斯巴先之军取埃及以绝粮道，12月二度会战于贝特利亚库姆，维氏死，元老院授韦氏。", impact: "一年而四帝相代，明元首之位在军中不在罗马；行省驻军自此得议废立，内战之例开于后此百年。", figures: ["加尔巴", "奥托", "维特里乌斯", "韦斯巴先"], place: "罗马与意大利北之贝特利亚库姆", state: "罗马", sources: ["塔西佗《历史》卷1至卷2", "苏埃托尼乌斯《加尔巴传》《奥托传》《维特里乌斯传》", "卡西乌斯·狄奥《罗马史》卷65至66（撮要）"], tags: ["内战", "禁卫军", "四帝"] }, related: [] },
  { id: "world--70--m01", track: "world", year: 70, yearApprox: false, dim: "military", weight: 4, title: "圣殿焚毁与犹太岁税", summary: "城陷殿焚，犹太丁男岁输半舍客勒。", detail: { background: "韦斯巴先遣子提图斯围耶路撒冷，城内三派互攻，粮储先焚而众犹不解。", process: "70年8月圣殿灾，九月城陷：罗马军纵火，金与器皿北运，旋以其地立“和平之寺”；又令犹太丁男岁输半舍客勒于罗马之最高神庙，是籍谓之“犹太之库”。", impact: "祭祀之制既绝，拉比之学移于加利利，会堂代祭；行省与散居之民自此以诵读与律议守其教。", figures: ["提图斯", "韦斯巴先", "约翰·基斯科鲁斯（城守之长）"], place: "耶路撒冷", state: "罗马（犹太行省）", sources: ["约瑟夫斯《犹太战史》卷6第4章、卷7第1至3章", "塔西佗《历史》卷5论圣殿之制与焚", "犹太税铜币之省铸（70年后）"], tags: ["围城", "殿毁", "岁税"] }, related: [] },
  { id: "world--77--s01", track: "world", year: 77, yearApprox: false, dim: "science", weight: 3, title: "老普林尼《自然史》", summary: "三十七卷之博物汇编，采书二千有余。", detail: { background: "普林尼历仕西班牙、高卢与不列颠之军政，又以舰队之任驻米塞诺，日课抄书。", process: "77年献《自然史》于提图斯，全书三十七卷，自谓采书二千有余、辑其要二万节；分宇宙与地理、人类与动物、植物与药、矿与金工、画塑之史，卷33以下论金、银、铜、铁与陶。", impact: "为中古拉丁世界最大之博物汇编，其纪火山灰、玻璃、水泥、漆与诸药之名物多赖出土之验；近代矿物学与工艺史每引其文。", figures: ["盖乌斯·普林尼乌斯·塞孔都斯", "提图斯"], place: "罗马", state: "罗马", sources: ["普林尼《自然史》卷30第13至20节自述采书之数", "普林尼《自然史》卷37卷目与序言"], tags: ["博物", "辑抄", "矿冶"] }, related: [] },
  { id: "world--79--d01", track: "world", year: 79, yearApprox: true, dim: "disaster", weight: 5, title: "维苏威覆庞贝与赫库兰尼姆", summary: "浮石与热云埋二城，火山学自此有纪。", detail: { background: "维苏威前山累世以腴田著名，山下有庞贝、赫库兰尼姆、斯塔比亚诸邑，水道与浴坊俱备；64年庞贝曾大震。", process: "约79年8月24日（近据出土之炭、币与季节之证推在10月下旬），先落浮石与灰砾十余时，赫库兰尼姆继以热云与泥流，庞贝积石与灰二至六米；老普林尼率船出海救难而死于斯塔比亚。", impact: "小普林尼两书纪其变，为火山学之第一手；二城之室、肆、画、榜与食余为罗马日用之镜，其人遗灰之空今以铸像存之。", figures: ["盖乌斯·普林尼乌斯·塞孔都斯", "小普林尼（记述者）", "提图斯"], place: "维苏威山下（庞贝、赫库兰尼姆、斯塔比亚）", state: "罗马（坎帕尼亚）", sources: ["小普林尼《书信集》卷6第16、20两篇", "塔西佗《历史》卷2第82节论其年之灾（残）", "庞贝与赫库兰尼姆发掘报告（18至21世纪）"], tags: ["火山", "埋城", "浮石"] }, related: [] },
  { id: "world--80--a01", track: "world", year: 80, yearApprox: false, dim: "art", weight: 3, title: "科洛塞姆开幕", summary: "百日之戏起于弗拉维环形斗兽场。", detail: { background: "尼禄“巨室”前有人工之池，韦斯巴先填池为基，起可容数万之环形斗兽场，未成而死。", process: "80年提图斯成之，行百日之戏：首日诛罪者，继以猎兽与角士之斗，又于场中作拟海战（灌水之制，学者或有疑）；马尔提亚利斯有诗纪其台与像。", impact: "斗兽之会与“面包与戏”之供自是为罗马之定制；其拱券叠柱、看口编号与地下之机械为后世体育场之式。", figures: ["提图斯", "韦斯巴先", "马尔提亚利斯（同时诗人）"], place: "罗马（尼禄巨室之地）", state: "罗马", sources: ["卡西乌斯·狄奥《罗马史》卷66第25节论开幕之戏", "马尔提亚利斯《赠言集》卷1第4至11首论其像与台"], tags: ["竞技场", "百日之戏", "拱券"] }, related: [] },
  { id: "world--90--c01", track: "world", year: 90, yearApprox: true, dim: "culture", weight: 3, title: "雅姆尼亚学院与口传之学", summary: "殿毁后以学代祭，定日课与经目。", detail: { background: "圣殿既毁，祭司之任无所施；法利赛之门以“学”代“祭”，师席东移。", process: "约70年代末至90年代，约哈难·本·扎凯与门人立于雅姆尼亚（今以色列亚夫内）之席，议定日课之序、祷文之式与著作之目；其学称“口传之律”，至2世纪末写定于塞佛里斯。", impact: "犹太教由祭祀之教转为诵读与律议之教，密释纳与革玛拉之根在此；撒都该与诸党自是俱息。", figures: ["约哈难·本·扎凯", "以利以谢·本·许尔坎努斯", "迦玛列（雅姆尼亚之长）"], place: "雅姆尼亚（今以色列亚夫内）", state: "犹太（罗马治下）", sources: ["《密释纳·先祖论》第2至4章记雅姆尼亚诸师", "《塔木德·卖地门》第14叶论经目"], tags: ["口传律", "经目", "会堂"] }, related: [] },
  { id: "world--96--p01", track: "world", year: 96, yearApprox: false, dim: "politics", weight: 4, title: "涅尔瓦养图拉真为嗣", summary: "禁卫军胁君之后，以在外统兵者为子。", detail: { background: "多米善在军中失人心，96年9月为近臣所弑，元老院即日举涅尔瓦，年六十有六。", process: "在位不及一年，禁卫军围宫胁杀倡弑之从臣，涅尔瓦几不自安；96年10月于民众前收养时在上日耳曼统兵之图拉真为子，同任执政官，以军权付之。", impact: "以贤为嗣之例自是定，后四帝皆以养子相承，为百年之安；元老院与军团共立一君之说亦形于此。", figures: ["涅尔瓦", "图拉真"], place: "罗马与上日耳曼（今科隆）", state: "罗马", sources: ["苏埃托尼乌斯《涅尔瓦传》第7章论收养", "卡西乌斯·狄奥《罗马史》卷68第3至5节"], tags: ["收养", "继统", "军权"] }, related: [] },
  { id: "world--97--i01", track: "world", year: 97, yearApprox: false, dim: "institution", weight: 3, title: "水务总监署与《论水道》", summary: "专官量水，定公水之额与私接之禁。", detail: { background: "罗马诸水道岁久，私接与盗用者众，公水反不足；前此无专司之官。", process: "96至97年涅尔瓦以弗龙蒂努斯为“水务总监”，与属员巡行量测；弗龙蒂努斯上《论水道》三卷，列诸水道之名、所出、长度、支管尺寸与每口之水量，并以铅管之径为度量之率。", impact: "官定水权与量水之制始有其书，行省城市之给水取其式；书中“日入几何”之数今犹为考古与修复之凭。", figures: ["赛克斯图斯·尤利乌斯·弗龙蒂努斯", "涅尔瓦"], place: "罗马与坎帕尼亚诸水道上原", state: "罗马", sources: ["弗龙蒂努斯《论水道》卷1第1至3章自叙其任", "弗龙蒂努斯《论水道》第65至68节所引旧法"], tags: ["水道", "水权", "量测"] }, related: [] },
  { id: "world--100--a01", track: "world", year: 100, yearApprox: true, dim: "art", weight: 3, title: "太阳金字塔与特奥蒂瓦坎格网城", summary: "五层巨台成于大道之东，全城定位以格网。", detail: { background: "特奥蒂瓦坎（今墨西哥城东北）自前2世纪起为中美洲之都会，南北大道贯其中，诸族杂居。", process: "约100年（学界推定）太阳金字塔成其现存之形：底约二百二十五米见方，高约六十五米，五层台体包旧塔而覆以石灰之壁；大道宽四十余米，两侧为寺、院与氏族之居邸。", impact: "全城以格网与轴定位，中美洲之都市规划、历坛与市集之制自此出；后之图拉与阿兹台克诸都沿其式。", figures: ["佚名之营造师（特奥蒂瓦坎）"], place: "特奥蒂瓦坎（今墨西哥州）", state: "特奥蒂瓦坎文明", sources: ["特奥蒂瓦坎太阳金字塔与大道之考古报告（20至21世纪）", "《剑桥拉丁美洲古代史》中册论其建城年代"], tags: ["金字塔", "格网", "都会"] }, related: [] },
  { id: "world--101--m01", track: "world", year: 101, yearApprox: false, dim: "military", weight: 4, title: "达契亚初战与塔帕伊之胜", summary: "图拉真渡多瑙，破得凯巴利乌斯于塔帕伊。", detail: { background: "达契亚王得凯巴利乌斯自内乱起，据喀尔巴阡山中之诸堡，控多瑙河北之金、盐与马；前87年曾败罗马之军。", process: "101年春图拉真渡多瑙，秋与得凯巴利乌斯战于塔帕伊，破之；冬还意大利，102年复北，迫其王请和，输军器、平山堡，罗马监其界。", impact: "和约未固，105年再战；达契亚之金、银后入罗马库，图拉真广场与纪功柱皆以是役之获成之。", figures: ["图拉真", "得凯巴利乌斯（达契亚王）", "卢基乌斯·李锡尼·苏拉（小，将）"], place: "塔帕伊（今罗马尼亚卡罗塞贝什附近）", state: "罗马／达契亚", sources: ["卡西乌斯·狄奥《罗马史》卷68第6至14节（撮要）", "图拉真纪功柱浮雕（113年成，纪两战之役）"], tags: ["两战", "山堡", "金矿"] }, related: [] },
  { id: "world--105--s01", track: "world", year: 105, yearApprox: false, dim: "science", weight: 3, title: "多瑙河石桥与铁墩", summary: "二十墩之木石大桥，跨多瑙而通北征。", detail: { background: "图拉真再征达契亚，渡多瑙为患：浮桥不可久守，冬冰与春汛皆能坏之。", process: "大马士革之阿波罗多洛斯作桥于铁淀一带：桥墩二十，以石与铁沈筑，深者入河床数十米、高十余米，全长千一百余米，两端立堡与桥头之庙。", impact: "为千余年间多瑙河上最大之石桥，罗马之兵、道与银随之北；其形铸于币上，残墩今在河南岸犹存。", figures: ["大马士革之阿波罗多洛斯", "图拉真"], place: "多瑙河（今塞尔维亚特拉亚诺夫布里奇一带）", state: "罗马", sources: ["普罗柯比《建筑》卷4第5章论其桥墩之数与度", "卡西乌斯·狄奥《罗马史》卷68第13节论渡河之役"], tags: ["石桥", "桥墩", "军路"] }, related: [] },
  { id: "world--106--i01", track: "world", year: 106, yearApprox: false, dim: "institution", weight: 3, title: "阿拉比亚行省与王道", summary: "纳巴泰国除为省，重修大马色至红海道。", detail: { background: "纳巴泰王国以佩特拉与黑格拉之商税为业，罗马在东之商路与之为竞。", process: "106年纳巴泰王拉贝路二世死，罗马自叙利亚与埃及两道人，并其国为“阿拉比亚行省”，不改村社与纳巴泰之文字；重修自大马色至红海之“王道”，立里程之表，又通博斯特拉与格拉萨之道。", impact: "罗马之币、营与道入于半岛，纳巴泰之塔墓与铭刻渐废；后之霍兰与哈夫兰诸村社即沿其旧。", figures: ["图拉真", "拉贝路二世（纳巴泰末王）"], place: "阿拉比亚行省（今约旦南部与沙特西北）", state: "罗马（阿拉比亚行省）", sources: ["阿拉比亚诸城之纪年铭与里程表（106年起）", "尤比乌斯《编年史》106年条论阿拉比亚之并"], tags: ["并省", "王道", "里程表"] }, related: [] },
  { id: "world--110--i01", track: "world", year: 110, yearApprox: false, dim: "institution", weight: 3, title: "比提尼亚基督徒案与朝廷批复", summary: "巡抚请示于元首，定不物色、不受匿名告。", detail: { background: "小普林尼为比提尼亚与本都巡抚（约110至112年），省中信者日众，庙祀与市集之业为之衰。", process: "凡被告者三讯之：令呼罗马诸神、向帝像献香与酒，能者释之；匿名之籍所出者不受理。乃以可否请于图拉真，帝报曰：不当物色，被告而执迷者当刑，勿用无名之告。", impact: "此为罗马朝廷第一次以文书定信者之罪与讼之界；“不物色、不受匿名告”之例为后世所引，亦见省官依权而断之行。", figures: ["小普林尼", "图拉真"], place: "尼科米底亚（比提尼亚）", state: "罗马", sources: ["小普林尼《书信集》卷10第96至97篇（案与批复）", "小普林尼《书信集》卷10第33篇论会堂与晨诵"], tags: ["讯问", "批复", "省政"] }, related: [] },
  { id: "world--113--a01", track: "world", year: 113, yearApprox: false, dim: "art", weight: 3, title: "图拉真纪功柱与广场", summary: "螺旋浮雕三十米，百五十景纪达契亚之役。", detail: { background: "达契亚之获既入国库，图拉真以其地起广场、大库与纪功之柱。", process: "113年5月柱成，基铭载其高；柱身连基高约三十米，螺旋浮雕二十三步、长三十余米，刻罗马与达契亚之事百五十余景、人物百余组，营寨、渡河与俘使之状如在目前。", impact: "为以像纪史之最宏者，其浮雕为军装、工役与俘掠之图典；广场与大库之制为后世京城之所本。", figures: ["图拉真", "大马士革之阿波罗多洛斯（传为营造者）"], place: "罗马（图拉真广场）", state: "罗马", sources: ["纪功柱基之铭（113年，载削山与基之高）", "卡西乌斯·狄奥《罗马史》卷69第4节论其葬于柱下"], tags: ["浮雕", "纪功", "广场"] }, related: [] },
  { id: "world--115--p01", track: "world", year: 115, yearApprox: false, dim: "politics", weight: 3, title: "罗马至波斯湾之置省", summary: "亚美尼亚、美索不达米亚与亚述内属。", detail: { background: "图拉真乘帕提亚内乱东征，先取亚美尼亚，又沿两河而下。", process: "113年废亚美尼亚王而置行省；114至115年取尼西比斯与辛格刺，沿底格里斯入苏萨；116年冬巴比伦一带内属，又置美索不达米亚与亚述两省，罗马之界直达波斯湾。", impact: "元老院以其“远达东海”上号；然东方之守不可久，犹太与基列之乱继起，两年后即弃两河之地。", figures: ["图拉真", "路奇乌斯·昆图斯（巡抚）"], place: "亚美尼亚、美索不达米亚与亚述", state: "罗马", sources: ["卡西乌斯·狄奥《罗马史》卷68第17至30节（撮要）", "图拉真时代东方之铸币与里程铭（113至116年）"], tags: ["东征", "置省", "极界"] }, related: [] },
  { id: "world--115--d01", track: "world", year: 115, yearApprox: true, dim: "disaster", weight: 3, title: "安条克大震", summary: "冬夜地动，城覆而元首几不免。", detail: { background: "安条克为东方之都，累世有震；图拉真东征之冬驻跸其郊。", process: "115年冬（一说116年），地大震，城郭庐舍多覆，军中帐幕亦坏，图拉真自崩屋中得出；后世编年家纪其伤毁之甚。", impact: "地震死者以万计，叙利亚与腓尼基诸城同被其害；罗马以减赋与发帑缮城，而帝身自危之闻播于行省。", figures: ["图拉真"], place: "安条克（今土耳其安塔基亚）与叙利亚北部诸城", state: "罗马", sources: ["卡西乌斯·狄奥《罗马史》卷68第24至25节", "玛拉拉斯《编年史》卷10论安条克之震"], tags: ["地震", "帝躬", "缮城"] }, related: [] },
  { id: "world--117--p01", track: "world", year: 117, yearApprox: false, dim: "politics", weight: 4, title: "版图之极与固边之策", summary: "图拉真殁于奇里乞亚，新君弃两河之地。", detail: { background: "东省未安，115至117年犹太与基列相继起事，埃及之希腊人与犹太相攻，行省之兵分于两地。", process: "117年图拉真在卡利卡耳帕（奇里乞亚）病重，养子之说出于皇后与近臣之口，8月8日殁；哈德良即日弃美索不达米亚、亚述与亚美尼亚之直隶，以幼发拉底为界，还军西归。", impact: "罗马之界至是以可守为度，不复以远略为功；巡边、定界与常设之堡即本此策，版图之极遂终于此年。", figures: ["图拉真", "哈德良", "普洛丁娜（皇后）"], place: "卡利卡耳帕（奇里乞亚，今土耳其南部）", state: "罗马", sources: ["卡西乌斯·狄奥《罗马史》卷68第32至52节（撮要）", "《罗马帝王纪·哈德良传》第21章论其弃东方诸省"], tags: ["极界", "固边", "承替"] }, related: [] },
  { id: "world--122--i01", track: "world", year: 122, yearApprox: true, dim: "institution", weight: 3, title: "哈德良北墙与定界之策", summary: "以可守为度，不列颠北界筑石墙与关塞。", detail: { background: "东征既罢，不列颠与莱茵、多瑙诸省皆须固界；哈德良巡边，以可守为度而止远略。", process: "122年起自沃尔森德至索尔湾筑石墙，长八十罗马里，墙北掘壕，沿线置堡与台屋，屯兵万余；同期于日耳曼、毛里塔尼亚诸边立栅表与哨道。", impact: "罗马之界自此有常设之线与戍所，出入之税由关隘行之；墙南之屯聚渐成城邑，不列颠北界定于此三百年。", figures: ["哈德良", "不列颠诸军团之将"], place: "不列颠北边（今英格兰卡莱尔至苏格兰福斯湾）", state: "罗马（不列颠行省）", sources: ["《罗马帝王纪·哈德良传》第11章论其筑墙", "比德《英吉利教会史》卷1第5节论石垣之制", "北墙沿线营垒与界石铭刻"], tags: ["边墙", "定界", "屯戍"] }, related: [] },
  { id: "world--125--a01", track: "world", year: 125, yearApprox: true, dim: "art", weight: 4, title: "万神祠穹顶之成", summary: "四十三米之无筋混凝土穹，顶开圆孔。", detail: { background: "万神之祠本阿格里巴所建，80年毁于火；哈德良因旧基而改其制。", process: "约125至128年成今存之形：穹顶阔四十三米余，以浮石骨料自上渐薄，顶开直径八米八之孔；鼓座之下以巨室与十六墩承重，门廊仍存旧刻。", impact: "无筋混凝土之大穹至十九世纪犹为天下第一，其骨料与模之法承维特鲁威之传；后世之洗礼堂与大殿皆以其为式。", figures: ["哈德良", "大马士革之阿波罗多洛斯（传与其役）"], place: "罗马（万神祠）", state: "罗马", sources: ["《罗马帝王纪·哈德良传》第19章论万神祠", "万神祠砖印之年代测定（110至125年间）", "卡西乌斯·狄奥《罗马史》卷53第27节论旧祠"], tags: ["穹顶", "混凝土", "无筋"] }, related: [] },
  { id: "world--132--m01", track: "world", year: 132, yearApprox: true, dim: "military", weight: 3, title: "巴尔科赫巴之乱", summary: "“星之子”据耶路撒冷，罗马行坚壁乃定。", detail: { background: "哈德良营殖民之城于耶路撒冷并立别神之像，又限行身礼之俗，犹太之怨复积。", process: "132至135年，西门·本·柯斯巴以“星之子”之称起，据京邑，铸币纪“以色列之自由”，山地之堡与洞穴为守；罗马调多瑙与不列颠之兵，行坚壁清野之策，积岁乃平。", impact: "据卡西乌斯·狄奥载犹太战死者数十万，行省兵力大损；其地改名、旧族不得入，会堂之制自此代祭祀而行。", figures: ["西门·本·柯斯巴", "哈德良", "塞克斯图斯·尤利乌斯·塞味路斯（将）"], place: "犹太（耶路撒冷与犹大丘陵、死海诸窟）", state: "罗马（犹太行省）", sources: ["卡西乌斯·狄奥《罗马史》卷69第12至14节", "《巴尔科赫巴书信》与诸窟出土之币（20世纪考古报告）"], tags: ["围守", "改名", "铸币"] }, related: [] },
  { id: "world--150--c01", track: "world", year: 150, yearApprox: true, dim: "culture", weight: 4, title: "龙树之空论与大乘之兴", summary: "以二谛与缘起说空，大乘始有系统之论。", detail: { background: "大乘之经渐出，说一切有部之论盛于西北；有诸师以“空”破定说而未成系统。", process: "约2世纪中，南印之龙树作《中论》等，以二谛与八不之缘起明“空”，又注大品之经而立大乘之宗；其说由弟子提婆等传于西北与中印。", impact: "大乘教理自此有据，东入中亚与东亚，后继者复起“有”之辨；千年之论争多沿其所立之题。", figures: ["龙树", "提婆（其弟子）"], place: "南印度至阿马拉瓦蒂一带", state: "印度（案达罗诸国）", sources: ["龙树《中论》（汉译青目释本）", "《大智度论》题龙树造（学界断代有争议）"], tags: ["中观", "二谛", "大乘"] }, related: [] },
  { id: "world--150--s01", track: "world", year: 150, yearApprox: true, dim: "science", weight: 4, title: "托勒密《天学集成》", summary: "以本轮与星表总成前代之历算。", detail: { background: "希巴恰斯已定岁差与星等，亚历山大里亚之算学足以治圆；历须一总其成。", process: "约150年，托勒密成《天学集成》十三卷，以偏心圆与本轮均轮定日月五星之行，列千有余星之位与亮度，又论昼夜长短、交食与仪器之制。", impact: "其书经阿拉伯之译注而西归，为中古欧洲与伊斯兰之天文标准垂八百年；其式虽废，量法与表格犹存于历算。", figures: ["克劳狄乌斯·托勒密", "希巴恰斯（其所据）"], place: "亚历山大里亚（埃及）", state: "罗马（埃及行省）", sources: ["托勒密《天学集成》卷1至卷7（传本）", "托勒密《地理学》卷1论观测与制图之法"], tags: ["本轮", "星表", "历算"] }, related: [] },
  { id: "world--150--x01", track: "world", year: 150, yearApprox: true, dim: "explore", weight: 3, title: "托勒密《地理学》与经纬之表", summary: "以两万地名列经纬，定世界之可图。", detail: { background: "自埃拉托斯特尼测地以来，行省与商路之日程渐积，而诸地之位未有通表。", process: "托勒密以八卷列两万有余地名之经纬，以加那利诸岛为本初之线，分“旧知之舆”与“新知之舆”，其东界及于赛里斯与印度之金岛。", impact: "其表入阿拉伯之译而西归，15世纪之航海家据以度世界之广；其过张亚细亚之东伸，遂为西航求印度之张本。", figures: ["克劳狄乌斯·托勒密", "马利努斯（其先躯）"], place: "亚历山大里亚（埃及）", state: "罗马（埃及行省）", sources: ["托勒密《地理学》卷1第24至26节、卷8论赛里斯与印度", "《剑桥古代史》卷11论其经纬表之传"], tags: ["经纬", "图法", "东界"] }, related: [] },
  { id: "world--161--p01", track: "world", year: 161, yearApprox: false, dim: "politics", weight: 4, title: "两君同治之始", summary: "奥勒略不受单立，与路求斯同享大权。", detail: { background: "138年安敦尼立，161年3月殁；马可·奥勒略为其养子，时驻罗马。", process: "161年3月，奥勒略不受单立之号，即以路奇乌斯·维鲁斯为同治之凯撒，与之同享保民官权与最高祭司长，命同日宣告于诸军。", impact: "罗马第一次以两君同权为定制，为后世共政之式；其年即有东方之警与北方边患，兵费与疫患相仍。", figures: ["马尔库斯·奥勒略", "路奇乌斯·维鲁斯", "安敦尼"], place: "罗马（元老院与禁卫营）", state: "罗马", sources: ["《罗马帝王纪·马可传》第5至7章论同治", "《罗马帝王纪·维鲁斯传》第2章论其受号"], tags: ["同治", "承统", "边警"] }, related: [] },
  { id: "world--165--d01", track: "world", year: 165, yearApprox: true, dim: "disaster", weight: 5, title: "安东尼尼大疫", summary: "东征之军带疫西归，二十年间再发。", detail: { background: "162至165年之东征自美索不达米亚诸城还军，随军之疫循行省与海路入意大利。", process: "165年秋疫发于罗马及诸省，热疮、泻与咽肿为候，盖伦纪其证并言京中日病者众；189年前后复大起，前后垂二十五年，军与民俱损。", impact: "军额与丁赋大减，莱茵、多瑙之防渐资附庸之兵；教会以看护病者得名，此为罗马人口与信仰之枢机。", figures: ["马尔库斯·奥勒略", "盖伦（记其证者）", "路奇乌斯·维鲁斯"], place: "罗马、东地海与莱茵诸省", state: "罗马", sources: ["盖伦《论药方之效力》卷11、《论疾病之部位》论其候", "《罗马帝王纪·维鲁斯传》第7至9章论东征与疫", "近世疫病史研究之以币与墓数推计者"], tags: ["大疫", "军额", "看护"] }, related: [] },
  { id: "world--169--f01", track: "world", year: 169, yearApprox: true, dim: "figure", weight: 3, title: "盖伦在罗马讲解剖", summary: "以活剖与断椎示众，为二帝之医。", detail: { background: "帕加马之盖伦少从诸师习医，先任剑士之医，后入罗马行讲习。", process: "168至169年间在罗马以解剖与断椎之说示众，又为奥勒略与维鲁斯疗疾；其据猿与豕之骨以论人体，著医经数百种。", impact: "其解剖与生理之说为后世医学之准，历阿拉伯与中世纪欧洲之学校数百年，直至近代实测乃有改。", figures: ["盖伦", "马尔库斯·奥勒略"], place: "罗马与帕加马（今贝尔加马）", state: "罗马", sources: ["盖伦《论骨与肌》《医法》卷首自叙讲习之时", "苏达斯《辞林》论盖伦之著目"], tags: ["解剖", "实验", "医经"] }, related: [] },
  { id: "world--180--p01", track: "world", year: 180, yearApprox: false, dim: "politics", weight: 3, title: "哲人殁而嗣立", summary: "奥勒略死于多瑙前线，子康莫都斯承位。", detail: { background: "马可·奥勒略晚年驻多瑙前线，178年已立子康莫都斯为凯撒并同治。", process: "180年3月死于卡民图（今维也纳一带）军中；诸将以子承父位，康莫都斯旋与北狄成和，还京诛近臣与将佐十数人。", impact: "以贤为嗣之例自此止；父所定之边略与府库十年之内几废，193年之内战基于此。", figures: ["马尔库斯·奥勒略", "康莫都斯", "佩伦尼斯（近臣）"], place: "卡民图（今奥地利维也纳一带）", state: "罗马", sources: ["《罗马帝王纪·马可传》第27至28章", "卡西乌斯·狄奥《罗马史》卷71第4节、卷72论其承"], tags: ["承替", "边和", "府库"] }, related: [] },
  { id: "world--200--c01", track: "world", year: 200, yearApprox: true, dim: "culture", weight: 3, title: "灵知诸派与护教之辨", summary: "以隐秘之知立二宗之说，教父因之作驳。", detail: { background: "2世纪中，兼取希腊之流出说与东方之二元论者数派并起，自谓得秘传之知。", process: "其师各立其说：或立善、恶二本与诸“流溢”，或以沦于质料之“火花”为待救，各以其经与洗礼别于众会；爱任纽在里昂作《驳异端》，摘其诸说而断之。", impact: "正典、信条与“使徒统绪”之议皆因辨异说而急；被斥诸派之经后出于拿格哈马诸库。", figures: ["爱任纽（里昂之祭司长）", "瓦伦廷（诸师之一）", "特土良（同时之护教者）"], place: "亚历山大里亚、小亚细亚与高卢诸城", state: "罗马（早期信众诸会）", sources: ["爱任纽《驳异端》卷1至2述诸派之说", "《拿格哈马文集》诸篇（20世纪出土抄本）"], tags: ["灵知", "二宗", "护教"] }, related: [] },
  { id: "world--200--x01", track: "world", year: 200, yearApprox: true, dim: "explore", weight: 3, title: "加拉曼特斯与撒哈拉驼道", summary: "绿洲之民驾车驼南行，砂路始通黄金。", detail: { background: "撒哈拉南缘之加拉曼特斯（今利比亚南部费赞）以绿洲为栈，北通罗马之非洲，南接砂中之民。", process: "1至2世纪，其民以牛车与驼栈南入金砂之道，运象牙、兽皮与生口；老普林尼记罗马之兵与向导尝逾砂海南至“埃塞俄比亚”之地，又记费赞之枣与麻。", impact: "跨撒哈拉之商道自是入罗马之市，南方之金与象牙循此北出；其路为中古砂路贸易之骨。", figures: ["老普林尼（记其地者）", "加拉曼特斯诸族（无名之民）"], place: "费赞绿洲与撒哈拉南缘（今利比亚南部至尼日尔）", state: "加拉曼特斯／罗马非洲", sources: ["老普林尼《自然史》卷5第35至36节论加拉曼特斯", "希罗多德《历史》卷4第183节论其驾车之俗"], tags: ["绿洲", "驼队", "砂路"] }, related: [] },
  { id: "world--212--i01", track: "world", year: 212, yearApprox: false, dim: "institution", weight: 5, title: "卡拉卡拉公民敕令", summary: "普给罗马之籍，税基与讼法随之而一。", detail: { background: "行省之民有籍者日众，而公民与非公民之税、讼与刑不同；军与边之费日增。", process: "212年颁敕于全国，凡城内居住之民（除归附之众与释奴之裔）皆予罗马公民之籍；其文今见于埃及之木牌与纸草，税目随之而改。", impact: "罗马之籍自此及于帝国全域之自由民，遗产与释放诸税之基遂广；后世所谓“罗马法”之万民之分由是而变。", figures: ["卡拉卡拉", "盖乌斯·尤利乌斯·保罗（同时之法家）"], place: "罗马与诸行省（敕文见埃及纸草）", state: "罗马", sources: ["《公民敕令》之纸草残片（基森收藏之校释本）", "卡西乌斯·狄奥《罗马史》卷78第9至10节论其税之由"], tags: ["籍", "税基", "敕令"] }, related: [] },
  { id: "world--220--a01", track: "world", year: 220, yearApprox: true, dim: "art", weight: 3, title: "犍陀罗与秣菟罗之佛像", summary: "两系石作并兴，佛始有人形之像。", detail: { background: "自阿输迦之石柱与巴尔胡特之栏楯以来，印度之佛迹但以足迹、菩提树与塔表之，不作人形。", process: "1至3世纪，犍陀罗之匠以灰岩、片岩造佛与菩萨之像，衣纹厚重、发为螺髻；同时秣菟罗之工就赤色砂岩作像，衣薄贴身，坐相与手印自成其式。", impact: "佛像自此有北、南二系：北系经中亚东传于塔里木与东亚，南系为笈多之像所承；造像之量与印亦自此有则可依。", figures: ["迦腻色迦（其世多与像兴相及）", "犍陀罗与秣菟罗之匠（佚名）"], place: "犍陀罗（今白沙瓦、塔克特依巴希）与秣菟罗（印度北方邦）", state: "贵霜／印度诸邦", sources: ["塔克特依巴希与布特拉卡拉之发掘报告（20世纪）", "《剑桥印度史》卷1论佛像之两系"], tags: ["造像", "片岩", "赤砂岩"] }, related: [] },
  { id: "world--224--p01", track: "world", year: 224, yearApprox: true, dim: "politics", weight: 4, title: "帕提亚亡与萨珊代兴", summary: "伊士塔赫尔之族起，杀末王而据泰西封。", detail: { background: "帕提亚诸王以七大族与方镇之兵相维，末叶内战与罗马东警俱起。", process: "约224年，伊士塔赫尔之阿尔达希尔与末王阿尔达班五世战于胡泽斯坦之奥尔干河，杀之；226年入泰西封，自号“伊朗与非伊朗之王”，萨珊之统始。", impact: "东方代之以奉火教、重中央之署之朝；沙普尔一世之西侵遂为罗马百年之患，岩铭与银币纪其功。", figures: ["阿尔达希尔一世", "阿尔达班五世"], place: "胡泽斯坦与泰西封（今伊朗西南部、伊拉克中部）", state: "萨珊波斯", sources: ["沙普尔一世与克尔提尔之功业岩铭（比沙普尔、纳克许·鲁斯塔姆）", "《剑桥伊朗史》卷3论萨珊之代兴"], tags: ["代兴", "岩铭", "王号"] }, related: [] },
  { id: "world--240--c01", track: "world", year: 240, yearApprox: true, dim: "culture", weight: 4, title: "摩尼创明暗二宗", summary: "以二宗三际立教，著书七种而遣使四方。", detail: { background: "巴比伦之末，洗者诸派与火教祭司并峙；摩尼生于美索不达米亚之裔，少时自谓蒙召。", process: "约240或241年出而传“二宗三际”之说，著书七种（含《活福音》与图卷），以斋戒、诵经与画辅其教，自承继亚当、琐罗亚斯达、耶稣诸圣之后；其王世得容而东传。", impact: "其教西至罗马与高卢、东至印度西北与中亚，抄本以诸语传世，与火教、基督诸教累世相攻。", figures: ["摩尼", "沙普尔一世（容其教者）"], place: "美索不达米亚与泰西封", state: "萨珊波斯", sources: ["摩尼《克弗来亚》与《活福音》残篇（诸语抄本）", "奥古斯丁驳摩尼诸书论其说之要"], tags: ["二宗", "抄本", "传播"] }, related: [] },
  { id: "world--240--c02", track: "world", year: 240, yearApprox: true, dim: "culture", weight: 3, title: "密陀罗密祠与七阶之礼", summary: "兵与民入地祠受阶，共食而不血祭。", detail: { background: "自1世纪，密陀罗之敬由军与商入罗马之世，其说不出于经而出于像与仪。", process: "2至3世纪，行省与京邑多凿地作密祠，中列二神屠牛之像；入礼者历乌鸦、雄牛、战士、狮子、波斯、日使与父之七阶，共食饼与水，无祭牲之血。", impact: "其以盟誓结军士与平民之群，与诸会争信众；4世纪后随国教之定而衰，今存祠址数百处。", figures: ["密陀罗之祭司（佚名）", "献额之兵（无名之碑）"], place: "罗马与莱茵、多瑙诸营之城", state: "罗马", sources: ["杜拉欧罗波斯与罗马圣普里斯库斯密祠之发掘报告", "密祠献额与阶次之名之铭刻汇编"], tags: ["密祠", "七阶", "兵俗"] }, related: [] },
  { id: "world--240--p01", track: "world", year: 240, yearApprox: true, dim: "politics", weight: 3, title: "邪马台之一君", summary: "倭诸国共立女王，遣使于魏而受印绶。", detail: { background: "倭国（今日本西部）自1世纪分百余国，1世纪末相攻数十年不已。", process: "约239年前后（同时之使录所见），倭诸国共立一名卑弥呼者为主，以其亲鬼道者言神命，宫室、城栅与仓储备焉；是年遣使于魏，魏假以金印紫绶而号之曰“亲魏倭王”。", impact: "倭之共主始见于当时之邻国纪载，九州与近畿之盟由此而显；后世大和之统出自其间。", figures: ["卑弥呼", "壹与（其宗女之继者）", "难升米（使其）"], place: "邪马台（今日本九州或大和，学界未定）", state: "倭（邪马台）", sources: ["《三国志·魏书·乌丸鲜卑东夷传》注引魏人之纪倭事", "倭之石冢与铜镜出土之报告（20至21世纪）"], tags: ["共主", "遣使", "鬼道"] }, related: [] },
  { id: "world--250--d01", track: "world", year: 250, yearApprox: true, dim: "disaster", weight: 5, title: "居普良大疫", summary: "疫起近东而西及京邑，十数年三发。", detail: { background: "165年之疫未远，249年前后边境与京邑又见疫；250年起于近东而西行。", process: "250至262年间数作：热与泻、咽烂、手足脱落为候，据同时之纪，京中日死者数千；医多避，而教会载尸共洗，奴仆死于看护者众。", impact: "军额、丁赋与耕作之损相仍，三世纪之财政与征兵愈困；其丧制与护教之文皆以是疫为背景。", figures: ["居普良（迦太基之祭司长）", "哥利略（卡帕多西亚之师）", "德米特里乌斯（同时之医家）"], place: "亚历山大里亚、罗马与诸省", state: "罗马", sources: ["居普良《论死之必至》第3至12章论其疫之重", "哥利略《大年斋讲》记其候与日数"], tags: ["大疫", "看护", "丁赋"] }, related: [] },
  { id: "world--260--m01", track: "world", year: 260, yearApprox: true, dim: "military", weight: 3, title: "埃德萨之役与瓦勒良被虏", summary: "罗马主为外虏所获，东防遂溃。", detail: { background: "沙普尔一世屡入美索不达米亚与叙利亚，256至257年取杜拉欧罗波斯；瓦勒良东征分兵御之。", process: "约260年沙普尔围埃德萨，以伏兵断其进路，瓦勒良与麾下将佐、近卫之众俱被虏；其子加利恩奴斯独立于西，东方诸省之守尽坏。", impact: "罗马第一次有主为外敌所获，其功业刻于岩铭与崖壁；帕尔米拉因是以自树其界，三世纪之分裂形焉。", figures: ["沙普尔一世", "瓦勒良", "加利恩奴斯"], place: "埃德萨（今土耳其尚勒乌尔法）", state: "萨珊波斯／罗马", sources: ["沙普尔一世之岩铭与凿崖纪功（纳克许·鲁斯塔姆、比沙普尔）", "《罗马帝王纪·二伽列传》第4至6章", "奥罗修斯《史钞》卷1论其为虏之传"], tags: ["被虏", "崖刻", "东防"] }, related: [] },
  { id: "world--262--i01", track: "world", year: 262, yearApprox: true, dim: "institution", weight: 3, title: "萨珊之爵秩与王廷之署", summary: "立诸州之王与百署之序，铭刻兼三书。", detail: { background: "萨珊承帕提亚之方镇与七族，而欲以一身总之，乃更定爵秩与官署。", process: "沙普尔一之世定“诸州之王”与方镇之秩，列司书、司藏、司祭与将、法官之序，下有司民之官；众祭司之长克尔提尔掌寺产与文书，铸金银之印行敕，铭刻以三书并列。", impact: "波斯之朝廷自此有籍、有印、有阶；使、商与教争皆由署出，行省之税与兵籍渐密，历四百年而不改其目。", figures: ["沙普尔一世", "克尔提尔（众祭司之长）"], place: "泰西封与比沙普尔（今伊拉克、伊朗法尔斯）", state: "萨珊波斯", sources: ["克尔提尔之爵秩铭（纳克许·鲁斯塔姆，三书并列）", "《剑桥伊朗史》卷3论萨珊官制"], tags: ["爵秩", "官署", "三书铭"] }, related: [] },
  { id: "world--270--e01", track: "world", year: 270, yearApprox: true, dim: "economy", weight: 3, title: "三世纪之币坏与物价", summary: "银币含银不及一成，纸草之价屡倍。", detail: { background: "自瓦勒良被虏与边患日棘，军赏与雇募之费不给，铸币之银日减。", process: "253至270年间，银币含银自尼禄时之九成余降至一成上下，其重不足二克，又以厚铜之品充军饷；埃及纸草所记谷价自250年代至270年代累倍至数十倍。", impact: "饷以实物与折色并行，税之实物化日甚；其弊为戴克里先之税册与限价所承，三世纪之民生由此一变。", figures: ["加利恩奴斯", "克劳狄乌斯（其世之币）", "奥勒良（复铸者）"], place: "罗马与亚历山大里亚（纸草价之据）", state: "罗马", sources: ["2至3世纪埃及纸草价目之辑校", "克劳狄乌斯至奥勒良银币成色之测定系列"], tags: ["减质", "物价", "折色"] }, related: [] },
  { id: "world--290--s01", track: "world", year: 290, yearApprox: true, dim: "science", weight: 3, title: "水转之锯与磨坊之制", summary: "水力代人力，锯石与磨面同出于一轮。", detail: { background: "自1世纪行省已有水磨，然立式之轮力弱，锯石与研物犹资人畜。", process: "3世纪末之小亚细亚与高卢诸坊，以水轮带曲柄与连杆，使锯条往复而剖石；同期之坊并设磨、锤与旋车，以齿轮换其向。", impact: "工役之力由身外之水力取之，石料与谷面之费日廉；其曲柄连杆之法为中古水力坊之祖。", figures: ["小亚细亚与高卢之坊主（佚名）"], place: "以弗所、高卢诸水坊（近世出土之锯石坊遗址）", state: "罗马", sources: ["希拉波利斯水锯石坊之铭（3世纪末）", "维特鲁威与晚期石坊之机械构件报告"], tags: ["水轮", "曲柄", "锯石"] }, related: [] },
  { id: "world--293--i01", track: "world", year: 293, yearApprox: false, dim: "institution", weight: 4, title: "四帝共治之制", summary: "两主两副，各分区与兵额而世其任。", detail: { background: "三世纪之兵变与边患并至，一主不能周四方；戴克里先自286年已用同僚分治。", process: "293年定二“奥古斯都”与二“凯撒”之制：各分区、各拥兵额、各铸币，二十年而后禅，以养子与姻娅相维；其朝会、礼仪与文书皆定其等。", impact: "帝国之政分为东西四署，京城移于边镇之侧；其制免一时之乱，然承替之争终起于兵与姻亲之间。", figures: ["戴克里先", "马克西米安", "伽列里乌斯", "君士坦提乌斯"], place: "尼科米底亚、米兰、特里尔与萨尔马提斯诸都", state: "罗马", sources: ["293年前后之币与铭刻纪四主之号", "拉克坦提乌斯《迫害者之死》第7至18章论其制"], tags: ["共治", "分防", "禅代"] }, related: [] },
  { id: "world--300--a01", track: "world", year: 300, yearApprox: true, dim: "art", weight: 3, title: "前方后方之古坟与埴轮", summary: "钥匙形之冢与陶列，为大和之丧制。", detail: { background: "倭近畿之诸豪累世以高冢表其位，前此之圆冢渐改为两重之制。", process: "约3至4世纪，前方后方之坟成：以壕绕冢，两重或三重之台，上列圆筒之陶与陶塑之人、马、器（埴轮），大者长逾百米，木椟与铜镜、铁器为副。", impact: "其制为大和之统所专用，豪族之等以冢之大小与埴轮之数别之；百济、加耶之冢与之同风。", figures: ["大和诸豪之匠（佚名）"], place: "近畿（今奈良、大阪之古坟群）", state: "倭（大和）", sources: ["佐纪米山古坟与大和诸古坟之发掘报告（20至21世纪）", "《日本书纪》论履中、仁德之陵（后世纪，与坟制相校）"], tags: ["古坟", "埴轮", "丧制"] }, related: [] },
  { id: "world--301--e01", track: "world", year: 301, yearApprox: true, dim: "economy", weight: 3, title: "限价敕与百物之格", summary: "以铁定上下之直，逾限者罪至死。", detail: { background: "币坏而物价屡腾，兵饷与官给之费不支；301年冬戴克里先以敕齐天下之物直。", process: "敕刻石于行省之市，列一千余品之上直，自谷、油、布至舟车之赁、佣工之日皆有限；逾限者罪至死，又禁囤与结伙抬直。", impact: "格直之石今存数本，为古代物价最密之表；其令寻废，然税之实物与官定之价遂为后此之常。", figures: ["戴克里先", "诸行省之市吏"], place: "撒尔底迦、亚基利亚等地之市（石刻存）", state: "罗马", sources: ["《物价敕》之石本（撒尔底迦、亚基利亚残片之校刊）", "拉克坦提乌斯《迫害者之死》第7章论其敕之由"], tags: ["限价", "佣直", "石本"] }, related: [] },
  { id: "world--313--x01", track: "world", year: 313, yearApprox: true, dim: "explore", weight: 3, title: "粟特商人之信与东行之驿", summary: "撒马尔罕之商团东贸，书札记其折与乱。", detail: { background: "索格底亚那（今撒马尔罕、布哈拉一带）之商用驼队通印度、波斯与东方，自有其文字与商约。", process: "约313年，一粟特商团之信札记其自撒马尔罕东行，经敦煌、姑臧而贩金、麝、绵与银，并言驿路断绝、洛阳陷没与商侣之死；诸书以粟特文写，出土于东行之途。", impact: "此为丝路商团最早之自纪文书，其货物与债务之约见商法之实；索格底之语与字遂为东道商旅之通。", figures: ["粟特商团之诸商（书札之署名人）"], place: "撒马尔罕至敦煌、姑臧之道", state: "索格底亚那", sources: ["《粟特古信札》诸篇之校释（20世纪出土）", "《剑桥古代史》卷13论索格底之商网"], tags: ["商札", "丝路", "驼队"] }, related: [] },
  { id: "world--313--p01", track: "world", year: 313, yearApprox: false, dim: "politics", weight: 3, title: "乐浪之更与东界之变", summary: "高句丽取带方、乐浪，海东之郡县始改。", detail: { background: "汉之末东界有乐浪、带方二郡之置，魏、晋因之；高句丽自辽东之东渐强。", process: "313年高句丽取带方郡，乐浪之民多东徙；其王据平壤之地，兼有海东诸县之旧名，百济与新罗由是并起于半岛之南。", impact: "半岛北境之旧郡之名入高句丽之制，东面之权自中国之边郡转归三国之相争；其界累世不改。", figures: ["高句丽之王（乙弗利之世）", "乐浪、带方之故吏"], place: "乐浪、带方（今平壤一带与黄海北道）", state: "高句丽", sources: ["《三国志》《晋书》东夷诸传纪二郡之置废", "好太王陵之铭（414年立，追纪其东取诸城）"], tags: ["东界", "郡县", "三国"] }, related: [] },
  { id: "world--320--p01", track: "world", year: 320, yearApprox: true, dim: "politics", weight: 4, title: "笈多之起与摩揭陀之统", summary: "恒河中之主并五中之国，王号自冠。", detail: { background: "贵霜衰而印度北方分主林立；恒河中游之笈多氏以摩揭陀之地渐大。", process: "约320年，旃陀罗笈多以“大王与王中之王”之号称，都华氏城，娶离车氏以固其援；其子三多笈多并西印之诸国，王号加“维克拉玛迭多”之美名。", impact: "北印自此有一统之朝，梵语之文书、寺之檀施与商路之币并行；后世印度诸王之号与其纪元多沿于此。", figures: ["旃陀罗笈多一世", "三多笈多一世", "离车公主之婚（佚名）"], place: "华氏城与摩揭陀（今巴特那一带）", state: "笈多王朝", sources: ["笈多诸王之铜币与阿耶穆伽之金铭（学界断代有异说）", "《南海寄归内法传》追纪其寺与王（后世之据）"], tags: ["王号", "并国", "钱铭"] }, related: [] },
  { id: "world--325--c01", track: "world", year: 325, yearApprox: false, dim: "culture", weight: 5, title: "尼西亚之会", summary: "三百余祭与修士定同性之词。", detail: { background: "亚历山大里亚之长老亚流谓“子非与父同性”，东方诸会因此相讼；朝廷遣使观之。", process: "325年夏，尼西亚开会议，自皇帝召三百余位祭长与修士，亚他那修随其师与议；争论数月，定“同性”之词为信，另定逾越节之日与都邑之序，亚流与拒签者二人见逐。", impact: "此为国家所召第一次之大会议，信条、会议与纪年之例皆始于此；其后六十余年的信理之争方定。", figures: ["君士坦丁", "亚流", "亚他那修", "何西乌（会议之长）"], place: "尼西亚（今土耳其伊兹尼克）", state: "罗马", sources: ["尤比乌斯之《教会史》撮要说其“三百一十八位”之会（近世疑其数）", "苏克拉底等后世教会史据会议之文录（残本）", "亚他那修《论尼西亚会议之法令》"], tags: ["会议", "同性", "信纲"] }, related: [] },
  { id: "world--330--p01", track: "world", year: 330, yearApprox: false, dim: "politics", weight: 4, title: "君士坦丁堡为新都", summary: "旧之拜占庭之地，新罗马之朝廷。", detail: { background: "尼科米底亚久为东都而界近波斯；海峡扼黑海之口，粮道通埃及，旧城之险可守。", process: "327年起大筑：引泉、建仓、立广场与元老院，迁百官、工匠与粮票之户实之；330年5月11日行落成之礼，号称“新罗马”，另设与旧京同等之秩。", impact: "自此帝国重心东移，东西两廷之局遂定；此城后千年为欧亚通商与东方教会之首府。", figures: ["君士坦丁"], place: "君士坦丁堡（今土耳其伊斯坦布尔）", state: "罗马", sources: ["佐西莫斯《新史》卷二（后世抄本）", "尤比乌斯《君士坦丁传》"], tags: ["迁都", "新罗马", "海峡"] }, related: [] },
  { id: "world--335--e01", track: "world", year: 335, yearApprox: true, dim: "economy", weight: 3, title: "阿克苏姆之币与红海之市", summary: "高原自铸金铜之币，港口为印度洋之枢。", detail: { background: "高原雨足，农牧可业；陆有驼道通尼罗上源，海借季风可达印度南岸。", process: "3世纪后自铸金、银、铜之币，币文兼用希腊文与塞巴之文；港阿杜里斯出象牙、金、犀角与生口，入葡萄酒、织物与铁器；国王埃安纳之碑以三体刻其功业。", impact: "此为非洲腹地通印度洋之门户；其币远出于印度南境，可见商网之广。", figures: ["埃安纳（阿克苏姆王）"], place: "阿克苏姆与阿杜里斯（今埃塞俄比亚、厄立特里亚）", state: "阿克苏姆", sources: ["《厄立特里亚海航行记》之后世续补", "阿杜里斯碑铭与出土钱币之报告"], tags: ["自铸币", "海港", "三体碑"] }, related: [] },
  { id: "world--361--p01", track: "world", year: 361, yearApprox: false, dim: "politics", weight: 3, title: "尤利安复古教与波斯之役", summary: "欲以古神之祭代基督之教，兵败东征而亡。", detail: { background: "君士坦丁以后教会日盛，古庙之祭渐绝，而宫廷与军中之旧教徒犹众。", process: "361年尤利安即位，许诸教并立而夺教会之产与教师之禄，以新庙、仪典与主教之品秩复多神之教；363年率军入美索不达米亚，焚舟重而进，至底格里斯河被创死。", impact: "复古教之谋遂止，其后诸帝不复疑基督之教；东征之败亦见波斯之难制。", figures: ["尤利安", "沙普尔二世"], place: "安条克至底格里斯河", state: "罗马", sources: ["安米安努斯《罗马史》第二十二至二十五卷（残本）", "尤特罗匹斯《史纲》卷十"], tags: ["复教", "东征", "阵亡"] }, related: [] },
  { id: "world--367--c01", track: "world", year: 367, yearApprox: false, dim: "culture", weight: 3, title: "新经正典之目始定", summary: "年节之书历数二十七卷，此外不得增削。", detail: { background: "自2世纪末，诸教会所诵福音与书信各有其目，正本与伪篇之辨未一。", process: "367年亚历山太主教亚他那修于其第39年节书中历数新约27卷，谓“皆救赎之泉源，不得增、不得削”；此目随译本传于西方，397年加太基之会复申其定。", impact: "新经之目由此画一，抄本、讲经与圣像之据皆出于此；教外福音书渐至散佚。", figures: ["亚他那修", "耶柔米"], place: "亚历山太（今埃及）", state: "罗马", sources: ["亚他那修《第39年节书》（希腊、叙利亚文残本）", "《加太基会议教规》第24条（后世辑本）"], tags: ["正典", "年节书", "二十七卷"] }, related: [] },
  { id: "world--376--a01", track: "world", year: 376, yearApprox: true, dim: "art", weight: 3, title: "玛雅古典期之城与碑", summary: "二十进之纪年刻于石碑，城邦各纪其王。", detail: { background: "低地诸城承前此奥尔梅克之历与字，以碑记王位、祭祀与战争之日。", process: "4世纪前后蒂卡尔、卡拉克穆尔诸邦立纪年之碑，以二十进之位与“长纪”之数计日，碑阴刻王名与即位之辰；其字兼用意符与音节，书于石碑、玉器与树皮纸之书。", impact: "玛雅之信史由是可读，其历能推日食与金星之周期；碑制遂为城邦之史官。", figures: ["蒂卡尔之王"], place: "蒂卡尔（今危地马拉佩滕）", state: "玛雅诸邦", sources: ["蒂卡尔与纳兰霍碑铭之摹本与发掘记", "近人释读玛雅音节文字之研究"], tags: ["长纪年", "石碑", "音节文字"] }, related: [] },
  { id: "world--378--m01", track: "world", year: 378, yearApprox: false, dim: "military", weight: 4, title: "阿得里亚堡之败", summary: "三万之军没于平原，皇帝与鹰旗俱失。", detail: { background: "376年朝廷许哥特之众渡多瑙河就食，边吏侵刻之，遂聚众而反。", process: "378年8月9日阿得里亚堡之役，东军约三万人战殁，皇帝瓦伦斯与前锋同没；哥特骑兵冲溃步兵之阵，军中之鹰旗失坠，营地辎重尽为所获。", impact: "罗马野战军一时空竭，其后以“盟田”之名听诸部内附，边患遂在帝国之腹心。", figures: ["瓦伦斯", "弗里提格恩（哥特渠帅）"], place: "阿得里亚堡（今土耳其埃迪尔内）", state: "罗马", sources: ["安米安努斯《罗马史》第三十一卷", "佐西莫斯《新史》卷四"], tags: ["骑兵", "覆军", "内附"] }, related: [] },
  { id: "world--380--i01", track: "world", year: 380, yearApprox: false, dim: "institution", weight: 4, title: "国教之诏与“公教”之正", summary: "诏命罗马之民皆信使徒所传，余为异端。", detail: { background: "尼西亚以后两党迭为兴废，诸帝左右其词，教会之判未归于国家之一令。", process: "380年2月27日格拉提安与狄奥多西同诏于帖撒罗尼迦：凡属罗马之民皆宜信使徒彼得所传之教，称“公教”之徒；余者谓之异端，不许会集，没其聚会之所；381年君士坦丁堡之会又定其信经。", impact: "自是国教与公教相合，异端之会散，信纲之判始由国家之力行之。", figures: ["狄奥多西", "格拉提安"], place: "帖撒罗尼迦（今希腊塞萨洛尼基）", state: "罗马", sources: ["诏文存《狄奥多西法典》十六篇一（后世辑本）", "索佐门《教会史》（后世抄本）"], tags: ["国教", "异端", "信经"] }, related: [] },
  { id: "world--384--c01", track: "world", year: 384, yearApprox: true, dim: "culture", weight: 3, title: "佛教入百济与经像之东", summary: "天竺沙门赍经与像，王迎之于郊。", detail: { background: "佛教自海路东传，先及高句丽之廷（372年）；其南之百济与南朝之商船相接。", process: "384年，西天竺沙门胡摩多藏随使至百济，赍经与佛像，枕流王迎之于郊，馆于宫中；明年立寺于都，听民出家。", impact: "佛法自是入半岛之南，寺塔、文字与医咒并东；百济后为日本受佛之中介。", figures: ["胡摩多藏（天竺沙门）", "枕流王"], place: "慰礼城（今汉江流域）", state: "百济", sources: ["《三国史记》百济纪枕流王五年（12世纪追撰）", "法兴王以来之碑与寺基出土"], tags: ["经像", "立寺", "海路"] }, related: [] },
  { id: "world--395--p01", track: "world", year: 395, yearApprox: false, dim: "politics", weight: 4, title: "两帝分立与东西之离", summary: "一统之业及其身而止，两廷不复相通。", detail: { background: "狄奥多西一统之业仅及其身，诸子并立而各有其府。", process: "395年1月帝殁于米兰，遗命长子阿卡丢斯承东，都君士坦丁堡；幼子霍诺留承西，都米兰而徙拉文纳；两廷之执政大臣相忌，军与财不复相通。", impact: "东西两廷自此不复合并，法律、军费与信理之判各为其政；西土之弱由此益显。", figures: ["狄奥多西", "阿卡丢斯", "霍诺留"], place: "米兰与君士坦丁堡", state: "罗马", sources: ["佐西莫斯《新史》卷四", "克劳狄安《颂霍诺留之诗》"], tags: ["分国", "两廷", "摄政"] }, related: [] },
  { id: "world--400--a01", track: "world", year: 400, yearApprox: true, dim: "art", weight: 3, title: "莫切之土台与写容之瓶", summary: "沙漠引水成田，陶工塑王与祭之容。", detail: { background: "秘鲁北岸之沙漠倚河成田，渠网连为阡陌；诸邦无文字而重塑。", process: "约400年，莫切以德瓦瓦科为都，筑二大土台之庙，高十余丈；陶工作写容之瓶，塑王、祭、病与舞之事，又善金银之镶与红铜之镜。", impact: "其器像为安第斯无文字之国之史册，仪礼与疾疫之状由是可见；其制后为奇穆所承。", figures: ["莫切之塑工（佚名）"], place: "德瓦瓦科（今秘鲁特鲁希略附近）", state: "莫切", sources: ["德瓦瓦科土台之发掘与层位记", "莫切陶塑图像之近世研究"], tags: ["土台", "陶塑", "无文字"] }, related: [] },
  { id: "world--406--m01", track: "world", year: 406, yearApprox: false, dim: "military", weight: 3, title: "莱茵河之冰渡与诸部入高卢", summary: "除夕之夜三部渡河，高卢之防遂崩。", detail: { background: "莱茵边之戍兵内调，与诸部之约久弛；匈人西压，众部求入内地。", process: "406年12月31日夜，汪达尔、阿兰与苏维汇之众于美因茨之界乘冰渡河，高卢之军不能御；数年间劫掠二省，诸城相继残破，唯存军号。", impact: "边河之防既破，罗马在高卢之权不复完整；诸部以盟田之名自立，其地由是改名。", figures: ["汪达尔、阿兰诸部之渠帅（名多不传）"], place: "美因茨至高卢（今莱茵兰与法国）", state: "罗马（高卢边省）", sources: ["哲罗姆《书简》第107篇追纪其劫", "《高卢编年》与《百官志》之记"], tags: ["冰渡", "边防空", "盟田"] }, related: [] },
  { id: "world--410--p01", track: "world", year: 410, yearApprox: false, dim: "politics", weight: 4, title: "西哥特入罗马之劫", summary: "三日之掠，永城之号遂摇。", detail: { background: "378年后哥特之众久居巴尔干，朝廷羁縻而已；阿拉利克求田、求饷不得。", process: "410年8月24日，西哥特因城内之叛者开门入罗马，掠三日，掘陵求宝，虏摄政之妹加拉·普拉西狄亚以去；京之粮票遂绝。", impact: "“永城”之破震动诸方：异教之徒归罪于新教，罗马不可破之说自此出。", figures: ["阿拉利克", "加拉·普拉西狄亚"], place: "罗马", state: "罗马", sources: ["奥罗修斯《历史驳异端》卷七之末（同时之记）", "哲罗姆《书简》第127篇"], tags: ["破城", "三日之掠", "虏宗室"] }, related: [] },
  { id: "world--413--c01", track: "world", year: 413, yearApprox: true, dim: "culture", weight: 3, title: "奥古斯丁发《天城》之论", summary: "罗马既破，乃论两城之始终。", detail: { background: "410年之劫，异教之徒谓祸由弃古神之祭，两方之讼遂兴。", process: "413年起，奥古斯丁历二十余年著《天城论》二十二卷，以“爱己而成城”与“爱神而成城”辨两城之始终，兼论罗马之兴衰、天命与世代之序。", impact: "此为基督教史观之成书，中世纪之王权与教权之辨皆出其下。", figures: ["奥古斯丁"], place: "希波（今阿尔及利亚安纳巴）", state: "罗马（非洲行省）", sources: ["《天城论》之抄本（近世校刊）", "希波之会与其《更正》之目（后世辑本）"], tags: ["两城", "史观", "护教"] }, related: [] },
  { id: "world--420--c01", track: "world", year: 420, yearApprox: true, dim: "culture", weight: 3, title: "那烂陀之寺学与讲席", summary: "聚经、立讲、给食，学僧以千计。", detail: { background: "笈多诸王檀施寺塔；摩揭陀之都旁渐成大寺。", process: "约420年后，那烂陀自王舍城之北起寺，累世增筑；藏经之阁、讲席之阶、食与住之供各有其规，学僧自中印、师子国与西域来者以千计，因明、量、医与咒皆所讲。", impact: "此为千年佛寺大学之始，其规约与学目随佛法至西藏与南海诸国。", figures: ["那烂陀初基之诸王（佚名）"], place: "那烂陀（今印度比哈尔）", state: "笈多王朝", sources: ["《南海寄归内法传》与《大唐西域记》纪其规", "那烂陀遗址之发掘记"], tags: ["寺学", "讲席", "藏经"] }, related: [] },
  { id: "world--430--a01", track: "world", year: 430, yearApprox: true, dim: "art", weight: 3, title: "迦梨陀娑之戏与梵文之诗", summary: "声韵与情味为体，王与仙女之缘入戏。", detail: { background: "笈多之朝以梵语为文书之语，文士献诗与戏于王之廷。", process: "约4世纪末至5世纪初，迦梨陀娑作《沙恭达罗》之剧与《云使之诗》，以声韵之饰与情味之论为体，叙王与仙女之缘、苦行与失忆之讼。", impact: "梵文诗剧自此定其程式，情味之说为千年印度文论之纲；其戏近世译入欧洲诸语。", figures: ["迦梨陀娑"], place: "乌贾因或华氏城（今印度中央邦）", state: "笈多王朝", sources: ["《沙恭达罗》诸抄本之近世校刊", "《曲语庄严论》论其诗之格"], tags: ["诗剧", "情味", "梵文"] }, related: [] },
  { id: "world--438--i01", track: "world", year: 438, yearApprox: false, dim: "institution", weight: 3, title: "狄奥多西法典之颁", summary: "辑累朝之敕为十六篇，裁判依其文。", detail: { background: "自哈德良以来之诏敕积数百万言，有司无所据依，伪本错出。", process: "438年狄奥多西二世颁其法典于两廷，凡十六篇，辑通行之敕而削其复；439年行于西廷，裁判须依其文，不得引未辑之敕。", impact: "此为罗马法存于官定辑本之最早者，后世之法典皆自此出。", figures: ["狄奥多西二世", "编纂之诸法律臣"], place: "君士坦丁堡", state: "罗马（东廷）", sources: ["《狄奥多西法典》之抄本（近世校刊）", "438年在拉文纳之副署本"], tags: ["辑敕", "十六篇", "裁判"] }, related: [] },
  { id: "world--439--p01", track: "world", year: 439, yearApprox: false, dim: "politics", weight: 3, title: "汪达尔取迦太基", summary: "因丧入城而据其坞，西京之粮遂绝。", detail: { background: "429年汪达尔自西班牙渡海峡，据北非之东，十年围迦太基。", process: "439年10月盖塞里克乘戍兵出葬之日取迦太基，据其船坞而有其海，始称海王之号；442年以其子为质，西廷乃与约和。", impact: "罗马之非洲遂亡，地中海之权分；西京之粮与油不继，税源不复。", figures: ["盖塞里克"], place: "迦太基（今突尼斯）", state: "汪达尔", sources: ["《希达提乌斯编年史》439年之条", "约达尼斯《汪达尔王政表》（6世纪追撰）"], tags: ["取城", "海权", "粮道"] }, related: [] },
  { id: "world--450--s01", track: "world", year: 450, yearApprox: true, dim: "science", weight: 3, title: "双镫之制与重骑之稳", summary: "足踏二镫而身定，甲骑乃可持长矟。", detail: { background: "古之骑以鞍与鞦，跃马而射者易坠；北方之工装始悬镫于鞍之两侧。", process: "约4至5世纪，北亚诸部之骑用双镫，足踏之而身定；鞍桥益高，甲骑之重乃可持长矟而冲。其制随诸部四出，渐西及于欧罗巴。", impact: "镫之出使重甲之骑得以冲击，北方军势由是胜步兵；后为骑士之常制。", figures: ["北亚之鞍工装（佚名）"], place: "北亚草原至中原与欧洲", state: "北亚诸部", sources: ["3至5世纪镫具之出土（辽西、内蒙古与蒙古高原）", "欧洲早镫仅见于6世纪后之比较研究"], tags: ["双镫", "重骑", "鞍具"] }, related: [] },
  { id: "world--451--m01", track: "world", year: 451, yearApprox: false, dim: "military", weight: 3, title: "沙隆之会战与阿提拉之退", summary: "合诸部以拒匈人，一日而两军俱弊。", detail: { background: "阿提拉并诸部于黑海之东至莱茵，岁索东廷之贡；451年西入高卢。", process: "451年6月20日沙隆之野战，西廷之将阿埃提乌斯合西哥特、法兰克与勃艮第之众与匈人相拒，一日而两军死者以万数，西哥特王战殁；阿提拉明日引去。", impact: "匈人之势止于高卢，而罗马之胜实赖诸部；明年移兵入意大利，破阿奎雷亚而还。", figures: ["阿提拉", "阿埃提乌斯"], place: "沙隆（今法国香槟沙隆附近）", state: "罗马与诸部", sources: ["约达尼斯《哥特史》第36至38章（6世纪追撰）", "《希达提乌斯编年史》451年之条"], tags: ["车营", "诸部之合", "相拒"] }, related: [] },
  { id: "world--476--p01", track: "world", year: 476, yearApprox: false, dim: "politics", weight: 5, title: "西罗马之亡与末帝之废", summary: "节冠东送，西廷自此无君。", detail: { background: "自439年非洲之失，西廷之兵与税俱竭；诸将专兵，皇帝拥虚位。", process: "476年9月4日，奥多阿塞尔于拉文纳废末帝罗穆路斯·奥古斯都，送帝之节冠于君士坦丁堡，自居东廷之督护而治意大利；元老院亦上书谓东西不必两君。", impact: "西廷自此无君，而其官署、法与教会如旧；后世以此为古来之界，实一时之变而非一朝之亡。", figures: ["奥多阿塞尔", "罗穆路斯·奥古斯都", "芝诺"], place: "拉文纳与君士坦丁堡", state: "罗马（西廷）", sources: ["《君士坦丁堡年表》476年条（后世传本）", "约达尼斯《哥特史》第57章追纪"], tags: ["废帝", "节冠东送", "督护"] }, related: [] },
  { id: "world--490--c01", track: "world", year: 490, yearApprox: true, dim: "culture", weight: 3, title: "玛兹达克之均产说与被诛", summary: "请开仓廪、均神仆之食，贵戚合而诛之。", detail: { background: "萨珊之世，祭团与贵戚占田，民多失所；488年前后大旱与饥。", process: "玛兹达克倡言“神之食当均于神之仆”，请开仓廪、禁多蓄与多妻之侈、夺贵戚之田以业贫民；从者数万人，王喀瓦德一世藉之以抑诸族。", impact: "贵族与祭团反，其说虽禁而党不止；贵戚之权少戢，后此之税制与兵制因其乱而更定。", figures: ["玛兹达克", "喀瓦德一世"], place: "泰西封与波斯诸州", state: "萨珊", sources: ["塔巴里《年代记》所传之波斯旧事（后世辑本）", "比鲁尼《古代诸国年表》追纪其党"], tags: ["均产", "祭团", "民变"] }, related: [] },
  { id: "world--496--c01", track: "world", year: 496, yearApprox: true, dim: "culture", weight: 3, title: "克洛维受洗与法兰克之教会", summary: "渠帅从公教之祭，诸祭长与罗马之座援之。", detail: { background: "法兰克诸渠帅分据高卢之北；克洛维并其同辈，娶勃艮第之公主，彼奉公教之徒。", process: "约496年冬，克洛维于苏瓦松从雷米久斯受洗，其亲兵数千人俱入水，从公教之祭而不从亚流之派；高卢之诸祭长与罗马之座皆援之。", impact: "自是王与祭相倚：法兰克之征伐得教会之祝，其法与地产皆入教会之制。", figures: ["克洛维", "雷米久斯（苏瓦松祭长）"], place: "苏瓦松（今法国北部）", state: "法兰克", sources: ["图尔之格雷戈里《法兰克诸王史》卷二（6世纪）", "克洛维与诸祭长之书简（存辑本）"], tags: ["受洗", "公教", "王教相倚"] }, related: [] },
  { id: "world--499--s01", track: "world", year: 499, yearApprox: false, dim: "science", weight: 4, title: "阿耶波多与零位之算", summary: "立位值之算与空位之记，推弦表与周率。", detail: { background: "印度之算自祭需之数与输入之天文渐进；位值之记未定。", process: "499年，阿耶波多于拘苏摩补罗成《阿耶波多算书》，立位值之算与空位之记，定日、月、五星之周期与地球自转之说；以弦表推三角，定圆周之率为3.1416。", impact: "十进之位值与零之记自此可行大数之算，其法后入印度诸国、大食与欧洲。", figures: ["阿耶波多"], place: "拘苏摩补罗（今印度巴特那）", state: "摩揭陀（笈多之后）", sources: ["《阿耶波多算书》之抄本（14世纪后传本）", "巴沙伽罗《释算》之校刊"], tags: ["位值", "零之记", "历算"] }, related: [] },
  { id: "world--500--p01", track: "world", year: 500, yearApprox: true, dim: "politics", weight: 3, title: "东廷之富与查士丁尼之前夜", summary: "西土破碎而东廷独全，府库积金。", detail: { background: "西土破碎而东廷独全：商税、矿与埃及之粮皆在其府。", process: "500年前后，阿纳斯塔丢斯改金币之重，行省之税折以金，府库积金至三十七万磅（后世之纪）；君士坦丁堡之粮票、水道与市肆如旧，而巴尔干之戍渐竭。", impact: "此府之富为后此复西土之资；波斯之患与诸部之迫，不因此而解。", figures: ["阿纳斯塔丢斯"], place: "君士坦丁堡", state: "罗马（东廷）", sources: ["《诸王之纪》（6世纪之续编）", "阿纳斯塔丢斯金币之出土计量"], tags: ["金币", "府库", "东廷"] }, related: [] }
];
